CREATE OR REPLACE FUNCTION "private"."enforce_user_board_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  existing_board_count bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text, 0));

  SELECT count(*)
  INTO existing_board_count
  FROM public.boards
  WHERE user_id = NEW.user_id
    AND retired_at IS NULL;

  IF existing_board_count >= 10 THEN
    RAISE EXCEPTION 'board_limit_reached'
      USING
        ERRCODE = '23514',
        DETAIL = 'user_board_limit_10',
        HINT = 'Retire a board before adding another.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "private"."enforce_user_board_limit"() OWNER TO "postgres";


COMMENT ON FUNCTION "private"."enforce_user_board_limit"() IS 'Enforces the app-wide limit of 10 active (not retired) boards per user on insert and un-retire.';



CREATE OR REPLACE FUNCTION "public"."accept_invite_for_user"("inviter" "uuid", "invitee" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_follow_id uuid;
  v_follow_created boolean;
  v_referral_result jsonb;
BEGIN
  IF auth.uid() IS DISTINCT FROM $2 THEN
    RAISE EXCEPTION 'invitee mismatch: must match auth.uid()'
      USING ERRCODE = '42501';
  END IF;

  IF $1 IS NULL OR $2 IS NULL THEN
    RAISE EXCEPTION 'inviter and invitee are required'
      USING ERRCODE = '22023';
  END IF;

  IF $1 = $2 THEN
    RAISE EXCEPTION 'cannot accept your own invite'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.user_follows (follower_id, following_id)
  VALUES ($2, $1)
  ON CONFLICT (follower_id, following_id) DO NOTHING
  RETURNING id INTO v_follow_id;

  v_follow_created := v_follow_id IS NOT NULL;

  v_referral_result := public.record_referral_attribution(
    $1,
    $2,
    'invite_token',
    NULL
  );

  RETURN jsonb_build_object(
    'follow_created', v_follow_created,
    'follow_existing', NOT v_follow_created,
    'referral_created', COALESCE((v_referral_result->>'created')::boolean, false),
    'referral_existing', COALESCE((v_referral_result->>'existing')::boolean, false)
  );
END;
$_$;


ALTER FUNCTION "public"."accept_invite_for_user"("inviter" "uuid", "invitee" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."accept_invite_for_user"("inviter" "uuid", "invitee" "uuid") IS 'Accepts an invite for the authenticated invitee by creating the follow edge and referral attribution idempotently.';


SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."trusted_forecast_alerts" (
    "alert_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "beach_id" "uuid" NOT NULL,
    "local_date" "date" NOT NULL,
    "decision_id" "uuid",
    "alert_code" "text" NOT NULL,
    "separation_ft" numeric(8,4) NOT NULL,
    "primary_issue_id" "uuid",
    "conflicting_issue_id" "uuid",
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "build_key" "text" NOT NULL,
    "acknowledged" boolean DEFAULT false NOT NULL,
    "acknowledged_by" "text",
    "acknowledged_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "trusted_forecast_alerts_acknowledgement_check" CHECK (((("acknowledged" = false) AND ("acknowledged_by" IS NULL) AND ("acknowledged_at" IS NULL)) OR (("acknowledged" = true) AND ("acknowledged_by" IS NOT NULL) AND ("acknowledged_at" IS NOT NULL)))),
    CONSTRAINT "trusted_forecast_alerts_code_check" CHECK (("alert_code" = 'range_separation_exceeded'::"text")),
    CONSTRAINT "trusted_forecast_alerts_evidence_object_check" CHECK (("jsonb_typeof"("evidence") = 'object'::"text")),
    CONSTRAINT "trusted_forecast_alerts_separation_check" CHECK (("separation_ft" > 1.0))
);


ALTER TABLE "public"."trusted_forecast_alerts" OWNER TO "postgres";


COMMENT ON TABLE "public"."trusted_forecast_alerts" IS 'Immutable range-separation evidence. Only acknowledge_trusted_forecast_alert may change acknowledged, acknowledged_by, acknowledged_at (D-22).';



CREATE OR REPLACE FUNCTION "public"."acknowledge_trusted_forecast_alert"("p_acknowledgement" "jsonb") RETURNS SETOF "public"."trusted_forecast_alerts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_keys CONSTANT text[] := ARRAY['alertId', 'acknowledgedBy'];
  v_alert_id uuid;
  v_actor text;
  v_alert public.trusted_forecast_alerts%ROWTYPE;
BEGIN
  IF p_acknowledgement IS NULL
     OR jsonb_typeof(p_acknowledgement) <> 'object' THEN
    RAISE EXCEPTION 'alert acknowledgement must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_object_keys(p_acknowledgement) AS supplied(key)
    WHERE supplied.key <> ALL (c_keys)
  ) OR EXISTS (
    SELECT 1
    FROM unnest(c_keys) AS required(key)
    WHERE NOT (p_acknowledgement ? required.key)
  ) THEN
    RAISE EXCEPTION 'alert acknowledgement has an invalid field set'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(p_acknowledgement -> 'acknowledgedBy') <> 'string'
     OR length(p_acknowledgement ->> 'acknowledgedBy') = 0 THEN
    RAISE EXCEPTION 'alert acknowledgement requires a non-empty actor'
      USING ERRCODE = '22023';
  END IF;

  v_alert_id := (p_acknowledgement ->> 'alertId')::uuid;
  v_actor := p_acknowledgement ->> 'acknowledgedBy';

  PERFORM set_config(
    'app.trusted_forecast_alert_acknowledgement',
    'on',
    true
  );

  UPDATE public.trusted_forecast_alerts
  SET acknowledged = true,
      acknowledged_by = v_actor,
      acknowledged_at = transaction_timestamp()
  WHERE alert_id = v_alert_id
    AND acknowledged = false
  RETURNING * INTO v_alert;

  PERFORM set_config(
    'app.trusted_forecast_alert_acknowledgement',
    'off',
    true
  );

  IF v_alert.alert_id IS NULL THEN
    SELECT *
    INTO v_alert
    FROM public.trusted_forecast_alerts
    WHERE alert_id = v_alert_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'trusted forecast alert % does not exist', v_alert_id
        USING ERRCODE = 'P0002';
    END IF;
  END IF;

  RETURN NEXT v_alert;
  RETURN;
END;
$$;


ALTER FUNCTION "public"."acknowledge_trusted_forecast_alert"("p_acknowledgement" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."acknowledge_trusted_forecast_alert"("p_acknowledgement" "jsonb") IS 'Service-role-only acknowledgement that may change only acknowledgement status, actor, and timestamp (D-22).';



CREATE OR REPLACE FUNCTION "public"."activate_qr_business_venue_on_scan"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.qr_scan_count >= NEW.activation_threshold AND NEW.activated_at IS NULL THEN
    NEW.activated_at := now();
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."activate_qr_business_venue_on_scan"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_community_spot_photos_v1"("p_status" "text" DEFAULT 'all'::"text", "p_target_type" "text" DEFAULT NULL::"text", "p_target_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH page AS (
    SELECT
      p.*,
      NULLIF(btrim(pr.display_name), '') AS display_name,
      count(DISTINCT v.voter_id) FILTER (WHERE v.vote = 'up')::integer AS upvotes,
      count(DISTINCT v.voter_id) FILTER (WHERE v.vote = 'down')::integer AS downvotes,
      count(DISTINCT r.reporter_id) FILTER (
        WHERE r.reason IN ('explicit', 'privacy', 'safety')
      )::integer AS severe_reports,
      count(DISTINCT r.reporter_id) FILTER (
        WHERE r.reason IN ('wrong_spot', 'stale')
      )::integer AS quality_reports,
      count(DISTINCT r.reporter_id)::integer AS total_reports,
      EXISTS (
        SELECT 1 FROM public.community_photo_feature_pins pin
        WHERE pin.photo_id = p.id AND pin.revoked_at IS NULL
      ) AS is_pinned,
      (
        SELECT jsonb_build_object(
          'id', h.id, 'reason', h.reason, 'placedAt', h.placed_at
        )
        FROM public.community_photo_investigation_holds h
        WHERE h.photo_id = p.id AND h.released_at IS NULL
      ) AS hold,
      (
        SELECT jsonb_build_object(
          'reasonCode', cr.reason_code, 'restrictedUntil', cr.restricted_until
        )
        FROM public.community_photo_contributor_restrictions cr
        WHERE cr.contributor_id = p.uploader_id AND cr.lifted_at IS NULL
          AND (cr.restricted_until IS NULL OR cr.restricted_until > now())
      ) AS contributor_restriction
    FROM public.community_spot_photos p
    LEFT JOIN public.profiles pr ON pr.id = p.uploader_id
    LEFT JOIN public.community_photo_votes v ON v.photo_id = p.id
    LEFT JOIN public.community_photo_reports r ON r.photo_id = p.id
    WHERE (p_status = 'all'
      OR (p_status = 'visible' AND p.moderation_status = 'visible' AND p.lifecycle_status = 'active')
      OR (p_status = 'hidden' AND p.moderation_status = 'hidden' AND p.lifecycle_status = 'active')
      OR (p_status = 'removed' AND p.lifecycle_status = 'removed'))
      AND (p_target_type IS NULL OR p.target_type = p_target_type)
      AND (p_target_id IS NULL OR COALESCE(p.beach_id, p.custom_spot_id) = p_target_id)
      AND (p_before IS NULL OR p.created_at < p_before)
    GROUP BY p.id, pr.display_name
    ORDER BY p.created_at DESC, p.id ASC
    LIMIT LEAST(GREATEST(p_limit, 1), 100)
  )
  SELECT jsonb_build_object(
    'photos',
    COALESCE(jsonb_agg(jsonb_build_object(
      'id', id,
      'targetType', target_type,
      'targetId', COALESCE(beach_id, custom_spot_id),
      'imageUrl', '/api/community-photos/' || id || '/image',
      'visibility', visibility,
      'processingStatus', processing_status,
      'moderationStatus', moderation_status,
      'lifecycleStatus', lifecycle_status,
          'attribution', jsonb_build_object(
            'kind', CASE
              WHEN uploader_id IS NOT NULL AND display_name IS NOT NULL
                THEN 'profile'
              ELSE 'community'
            END,
            'displayName', COALESCE(display_name, 'Quiver community'),
            'profileId', CASE
              WHEN display_name IS NOT NULL THEN uploader_id
              ELSE NULL
            END
          ),
      'upvotes', upvotes,
      'downvotes', downvotes,
      'reportCounts', jsonb_build_object(
        'severe', severe_reports, 'quality', quality_reports, 'total', total_reports
      ),
      'isPinned', is_pinned,
      'hold', hold,
      'contributorRestriction', contributor_restriction,
      'createdAt', created_at,
      'removedAt', removed_at,
      'recoverableUntil', recoverable_until
    ) ORDER BY created_at DESC, id ASC), '[]'::jsonb),
    'nextCursor',
    CASE WHEN count(*) = LEAST(GREATEST(p_limit, 1), 100)
      THEN min(created_at)::text ELSE NULL END
  )
  FROM page
$$;


ALTER FUNCTION "public"."admin_list_community_spot_photos_v1"("p_status" "text", "p_target_type" "text", "p_target_id" "uuid", "p_limit" integer, "p_before" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_swell_watch_event"("p_regional_event_id" "uuid", "p_evaluation_id" "text", "p_beach_impact_id" "uuid", "p_arrival_at" timestamp with time zone, "p_peak_at" timestamp with time zone, "p_transition_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count integer;
  v_impact_evaluation_id text;
  v_impact_identity_kind text;
  v_latest_state text;
  v_latest_evaluation_id text;
  v_cycle_started_at timestamptz;
  v_version integer;
  v_transition_id uuid;
  v_existing_beach_impact_id uuid;
  v_existing_arrival_at timestamptz;
  v_existing_peak_at timestamptz;
  v_existing_evaluation_kind text;
  v_beach_id uuid;
  v_required integer; v_current_count integer; v_latest_stable_evaluation_id text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('swell-watch-event:' || p_regional_event_id::text, 0));
  PERFORM set_config('app.swell_watch_internal_write', 'on', true);
  SELECT impact.evaluation_id, observation.identity_kind, impact.beach_id
  INTO v_impact_evaluation_id, v_impact_identity_kind, v_beach_id
  FROM public.swell_watch_beach_impacts impact
  JOIN public.swell_watch_observations observation ON observation.id = impact.observation_id
  WHERE impact.id = p_beach_impact_id;
  IF v_impact_evaluation_id IS DISTINCT FROM p_evaluation_id THEN
    RAISE EXCEPTION 'evaluation identity does not match beach impact';
  END IF;
  IF v_impact_identity_kind NOT IN ('genuine_completed', 'synthetic_fixture') THEN
    RAISE EXCEPTION 'evaluation identity kind is invalid';
  END IF;
  IF p_arrival_at IS NULL OR p_peak_at IS NULL OR NOT isfinite(p_arrival_at)
    OR NOT isfinite(p_peak_at) OR p_peak_at < p_arrival_at THEN
    RAISE EXCEPTION 'invalid event impact timing';
  END IF;
  SELECT state INTO v_latest_state
  FROM public.swell_watch_event_state_transitions
  WHERE regional_event_id = p_regional_event_id
  ORDER BY version DESC
  LIMIT 1;
  IF v_latest_state = 'suppressed' THEN
    RETURN 'candidate';
  END IF;
  SELECT beach_impact_id, arrival_at, peak_at
  INTO v_existing_beach_impact_id, v_existing_arrival_at, v_existing_peak_at
  FROM public.swell_watch_event_impacts
  WHERE regional_event_id = p_regional_event_id AND evaluation_id = p_evaluation_id
    AND beach_id = v_beach_id;
  IF v_existing_beach_impact_id IS NOT NULL AND (
    v_existing_beach_impact_id IS DISTINCT FROM p_beach_impact_id
    OR v_existing_arrival_at IS DISTINCT FROM p_arrival_at
    OR v_existing_peak_at IS DISTINCT FROM p_peak_at
  ) THEN
    RAISE EXCEPTION 'conflicting event evaluation retry';
  END IF;
  IF v_existing_beach_impact_id IS NOT NULL THEN
    RETURN coalesce(v_latest_state, 'candidate');
  END IF;
  SELECT identity_kind INTO v_existing_evaluation_kind
  FROM public.swell_watch_event_evaluations
  WHERE regional_event_id = p_regional_event_id AND evaluation_id = p_evaluation_id;
  IF FOUND AND v_existing_evaluation_kind IS DISTINCT FROM v_impact_identity_kind THEN
    RAISE EXCEPTION 'conflicting event evaluation retry';
  END IF;
  INSERT INTO public.swell_watch_event_evaluations (id, regional_event_id, evaluation_id, identity_kind, beach_impact_id, arrival_at, peak_at)
  VALUES (p_transition_id, p_regional_event_id, p_evaluation_id, v_impact_identity_kind, p_beach_impact_id, p_arrival_at, p_peak_at)
  ON CONFLICT (regional_event_id, evaluation_id) DO NOTHING;
  INSERT INTO public.swell_watch_event_impacts
    (id, regional_event_id, evaluation_id, beach_id, beach_impact_id, arrival_at, peak_at, evaluated_at)
  SELECT gen_random_uuid(), p_regional_event_id, p_evaluation_id, v_beach_id,
    p_beach_impact_id, p_arrival_at, p_peak_at, evaluation.evaluated_at
  FROM public.swell_watch_event_evaluations evaluation
  WHERE evaluation.regional_event_id = p_regional_event_id AND evaluation.evaluation_id = p_evaluation_id;
  SELECT max(created_at) INTO v_cycle_started_at
  FROM public.swell_watch_event_state_transitions
  WHERE regional_event_id = p_regional_event_id AND state = 'suppressed';
  IF v_latest_state = 'stable' THEN
    SELECT trigger_evaluation_id INTO v_latest_stable_evaluation_id FROM public.swell_watch_event_state_transitions WHERE regional_event_id=p_regional_event_id ORDER BY version DESC LIMIT 1;
    IF EXISTS(SELECT 1 FROM public.swell_watch_event_evaluations evaluation
      JOIN public.swell_watch_beach_impacts impact ON impact.id=evaluation.beach_impact_id
      JOIN public.swell_watch_observations observation ON observation.id=impact.observation_id
      WHERE evaluation.regional_event_id=p_regional_event_id AND evaluation.evaluation_id=v_latest_stable_evaluation_id
        AND public.swell_watch_provider_evidence_is_current(observation.provider_batch_id)) THEN RETURN 'stable'; END IF;
  END IF;
  SELECT evaluation_id INTO v_latest_evaluation_id
  FROM public.swell_watch_event_evaluations
  WHERE regional_event_id = p_regional_event_id
    AND (v_cycle_started_at IS NULL OR evaluated_at > v_cycle_started_at)
  ORDER BY evaluated_at DESC, id DESC
  LIMIT 1;
  IF v_latest_evaluation_id IS DISTINCT FROM p_evaluation_id THEN
    RETURN 'candidate';
  END IF;
  SELECT count(*) INTO v_count FROM (
    SELECT evaluation_id
    FROM public.swell_watch_event_evaluations
    WHERE regional_event_id = p_regional_event_id
      AND (v_cycle_started_at IS NULL OR evaluated_at > v_cycle_started_at)
    ORDER BY evaluated_at DESC, id DESC
    LIMIT 2
  ) contiguous_evaluations;
  SELECT (policy_values #>> '{stability,minimum_genuine_evaluations}')::integer INTO v_required FROM public.swell_watch_get_matching_policy();
  SELECT count(DISTINCT evaluation.evaluation_id) INTO v_current_count
  FROM public.swell_watch_event_evaluations evaluation
  JOIN public.swell_watch_beach_impacts impact ON impact.id=evaluation.beach_impact_id
  JOIN public.swell_watch_observations observation ON observation.id=impact.observation_id
  WHERE evaluation.regional_event_id=p_regional_event_id AND evaluation.identity_kind='genuine_completed'
    AND public.swell_watch_provider_evidence_is_current(observation.provider_batch_id);
  IF coalesce(v_current_count,0) < greatest(coalesce(v_required,2),2) THEN RETURN 'candidate'; END IF;
  SELECT coalesce(max(version), 0) + 1 INTO v_version FROM public.swell_watch_event_state_transitions WHERE regional_event_id = p_regional_event_id;
  INSERT INTO public.swell_watch_event_state_transitions (id, regional_event_id, state, version, trigger_evaluation_id)
  VALUES (gen_random_uuid(), p_regional_event_id, 'stable', v_version, p_evaluation_id)
  ON CONFLICT (regional_event_id, version) DO NOTHING
  RETURNING id INTO v_transition_id;
  IF v_transition_id IS NULL THEN
    SELECT state INTO v_latest_state
    FROM public.swell_watch_event_state_transitions
    WHERE regional_event_id = p_regional_event_id
    ORDER BY version DESC
    LIMIT 1;
    IF v_latest_state = 'suppressed' THEN RETURN 'candidate'; END IF;
  END IF;
  RETURN 'stable';
END;
$$;


ALTER FUNCTION "public"."advance_swell_watch_event"("p_regional_event_id" "uuid", "p_evaluation_id" "text", "p_beach_impact_id" "uuid", "p_arrival_at" timestamp with time zone, "p_peak_at" timestamp with time zone, "p_transition_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."experiment_assignments" (
    "experiment_key" "text" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "arm" smallint NOT NULL,
    "index_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "assignment_version" "text" DEFAULT 'v1'::"text" NOT NULL,
    "build" "text",
    "source" "text",
    "linked_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "experiment_assignments_arm_check" CHECK (("arm" = ANY (ARRAY[0, 1]))),
    CONSTRAINT "experiment_assignments_key_check" CHECK (("experiment_key" = ANY (ARRAY['t3-quicklog-v1'::"text", 't10-freegrowth-v1'::"text", 't2a-swellwatch-v1'::"text"]))),
    CONSTRAINT "experiment_assignments_linkage_pair_check" CHECK ((("build" IS NULL) = ("source" IS NULL))),
    CONSTRAINT "experiment_assignments_source_check" CHECK (("source" = ANY (ARRAY['native_app'::"text", 'web_oauth'::"text"])))
);


ALTER TABLE "public"."experiment_assignments" OWNER TO "postgres";


COMMENT ON TABLE "public"."experiment_assignments" IS 'W-ASSIGN ledger of record (plan 063 §5). Service-role only. arm 0=control 1=treatment. Rows are immutable except a single write-once (build, source) linkage. user_id intentionally has no auth.users foreign key so account deletion retains a detached pseudonymous ITT row.';



COMMENT ON COLUMN "public"."experiment_assignments"."index_at" IS 'Analysis anchor: auth.users.created_at for signup-hook rows (t3/t10); allocation time for batch-allocated rows (t2a). Frozen — 7-day-return windows are computed from this.';



COMMENT ON COLUMN "public"."experiment_assignments"."build" IS 'Write-once eligibility linkage; NULL = eligibility_unknown (reported as its own bucket, never defaulted).';



COMMENT ON COLUMN "public"."experiment_assignments"."source" IS 'Write-once eligibility linkage; NULL = eligibility_unknown (reported as its own bucket, never defaulted).';



CREATE OR REPLACE FUNCTION "public"."allocate_experiment_batch"("p_experiment_key" "text", "p_user_ids" "uuid"[], "p_index_at" timestamp with time zone DEFAULT "now"()) RETURNS SETOF "public"."experiment_assignments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  INSERT INTO public.experiment_assignments
    (experiment_key, user_id, arm, index_at, assignment_version)
  SELECT p_experiment_key, u, public.experiment_arm(u, p_experiment_key), p_index_at, 'v1'
  FROM unnest(p_user_ids) AS u
  ON CONFLICT (experiment_key, user_id) DO NOTHING;

  RETURN QUERY
  SELECT * FROM public.experiment_assignments
  WHERE experiment_key = p_experiment_key AND user_id = ANY(p_user_ids);
END;
$$;


ALTER FUNCTION "public"."allocate_experiment_batch"("p_experiment_key" "text", "p_user_ids" "uuid"[], "p_index_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."anonymize_android_waitlist_for_account"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  DELETE FROM public.android_waitlist_source_links
  WHERE source_kind = 'profile_intent'
    AND source_id = NEW.id;

  UPDATE public.android_waitlist_entries
  SET user_id = NULL, normalized_email_sha256 = NULL, updated_at = now()
  WHERE user_id = NEW.id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."anonymize_android_waitlist_for_account"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."anonymize_community_photos_before_account_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  UPDATE public.community_photo_consents
  SET contributor_id = NULL
  WHERE contributor_id = OLD.id;
  UPDATE public.community_spot_photos
  SET uploader_id = NULL, updated_at = now()
  WHERE uploader_id = OLD.id;
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."anonymize_community_photos_before_account_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."regional_recommendation_hold_refs_are_safe"("p_refs" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_item jsonb;
  v_ref text;
  v_seen text[] := ARRAY[]::text[];
BEGIN
  IF p_refs IS NULL THEN
    RETURN false;
  END IF;

  IF jsonb_typeof(p_refs) <> 'array' THEN
    RETURN false;
  END IF;

  IF jsonb_array_length(p_refs) > 16 THEN
    RETURN false;
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_refs) AS refs(value)
  LOOP
    IF jsonb_typeof(v_item) <> 'string' THEN
      RETURN false;
    END IF;

    v_ref := v_item #>> '{}';
    IF char_length(v_ref) NOT BETWEEN 1 AND 128
       OR v_ref !~ '^(official:rip_current_risks:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|qa:artifact:[A-Za-z0-9_-]{1,64})$'
       OR v_ref = ANY(v_seen) THEN
      RETURN false;
    END IF;

    v_seen := array_append(v_seen, v_ref);
  END LOOP;

  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."regional_recommendation_hold_refs_are_safe"("p_refs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."regional_recommendation_hold_region_keys_are_safe"("p_region_keys" "text"[]) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_key text;
  v_seen text[] := ARRAY[]::text[];
BEGIN
  IF p_region_keys IS NULL OR cardinality(p_region_keys) > 64 THEN
    RETURN false;
  END IF;

  FOREACH v_key IN ARRAY p_region_keys
  LOOP
    IF v_key IS NULL
       OR v_key !~ '^[a-z0-9][a-z0-9_-]{0,63}$'
       OR v_key = ANY(v_seen) THEN
      RETURN false;
    END IF;

    v_seen := array_append(v_seen, v_key);
  END LOOP;

  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."regional_recommendation_hold_region_keys_are_safe"("p_region_keys" "text"[]) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."regional_recommendation_holds" (
    "record_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "hold_id" "uuid" NOT NULL,
    "version" integer NOT NULL,
    "transition" "text" NOT NULL,
    "status" "text" NOT NULL,
    "region_keys" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "scope_beach_ids" "uuid"[] NOT NULL,
    "scope_exposure_classes" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "protected_alternative_beach_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "event_reference" "text",
    "valid_from" timestamp with time zone NOT NULL,
    "valid_until" timestamp with time zone NOT NULL,
    "affected_cohorts" "text"[] NOT NULL,
    "action" "text" NOT NULL,
    "trigger_type" "text" NOT NULL,
    "supporting_evidence_refs" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "automatic_policy_version" "text",
    "authorizing_operator_ref" "uuid",
    "authorizing_actor" "text" NOT NULL,
    "reason_code" "text" NOT NULL,
    "effective_at" timestamp with time zone NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "supersedes_record_id" "uuid",
    "idempotency_key" "text" NOT NULL,
    "payload_hash" "text" NOT NULL,
    "request_id" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "regional_recommendation_hold_protected_alternative_beach__check" CHECK (("cardinality"("protected_alternative_beach_ids") <= 2000)),
    CONSTRAINT "regional_recommendation_holds_action_check" CHECK (("action" = ANY (ARRAY['suppress_positive'::"text", 'protected_alternatives_only'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_affected_cohorts_check" CHECK ((("cardinality"("affected_cohorts") > 0) AND ("affected_cohorts" <@ ARRAY['beginner'::"text", 'intermediate'::"text", 'advanced'::"text", 'expert'::"text", 'unknown'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_authorizing_actor_check" CHECK (("authorizing_actor" = ANY (ARRAY['admin_api'::"text", 'official_automation'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_automatic_policy_version_check" CHECK ((("automatic_policy_version" IS NULL) OR ("automatic_policy_version" ~ '^[a-z0-9._-]{1,64}$'::"text"))),
    CONSTRAINT "regional_recommendation_holds_check" CHECK (("valid_until" > "valid_from")),
    CONSTRAINT "regional_recommendation_holds_check1" CHECK ((("expires_at" > "effective_at") AND ("expires_at" <= ("effective_at" + '7 days'::interval)))),
    CONSTRAINT "regional_recommendation_holds_check2" CHECK (((("transition" = 'activation'::"text") AND ("version" = 1) AND ("supersedes_record_id" IS NULL)) OR (("transition" <> 'activation'::"text") AND ("version" > 1) AND ("supersedes_record_id" IS NOT NULL)))),
    CONSTRAINT "regional_recommendation_holds_check3" CHECK (((("transition" = 'cancellation'::"text") AND ("status" = 'cancelled'::"text")) OR (("transition" <> 'cancellation'::"text") AND ("status" = 'active'::"text")))),
    CONSTRAINT "regional_recommendation_holds_check4" CHECK (((("trigger_type" = 'manual_operator'::"text") AND ("authorizing_operator_ref" IS NOT NULL) AND ("automatic_policy_version" IS NULL)) OR (("trigger_type" = 'automatic_official'::"text") AND ("authorizing_operator_ref" IS NULL) AND ("automatic_policy_version" IS NOT NULL) AND ("jsonb_array_length"("supporting_evidence_refs") > 0)))),
    CONSTRAINT "regional_recommendation_holds_check5" CHECK ((("action" <> 'protected_alternatives_only'::"text") OR ("cardinality"("protected_alternative_beach_ids") > 0))),
    CONSTRAINT "regional_recommendation_holds_check6" CHECK ((("trigger_type" <> 'automatic_official'::"text") OR (("transition" = 'activation'::"text") AND ("action" = 'suppress_positive'::"text") AND ("affected_cohorts" = ARRAY['beginner'::"text", 'intermediate'::"text", 'unknown'::"text"]) AND ("cardinality"("scope_beach_ids") = 1) AND ("cardinality"("region_keys") = 0) AND ("cardinality"("scope_exposure_classes") = 0) AND ("cardinality"("protected_alternative_beach_ids") = 0) AND ("automatic_policy_version" = 'official-rip-high.v1'::"text") AND ("authorizing_actor" = 'official_automation'::"text") AND ("reason_code" = 'official_high_rip_current'::"text") AND ("jsonb_array_length"("supporting_evidence_refs") = 1)))),
    CONSTRAINT "regional_recommendation_holds_event_reference_check" CHECK ((("event_reference" IS NULL) OR ("event_reference" ~ '^(event|official|qa):[a-z0-9_]+:[A-Za-z0-9_-]{1,64}$'::"text"))),
    CONSTRAINT "regional_recommendation_holds_idempotency_key_check" CHECK (("idempotency_key" ~ '^[A-Za-z0-9:_-]{1,160}$'::"text")),
    CONSTRAINT "regional_recommendation_holds_payload_hash_check" CHECK (("payload_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "regional_recommendation_holds_reason_code_check" CHECK (("reason_code" = ANY (ARRAY['major_swell_manual_safety'::"text", 'official_high_rip_current'::"text", 'scope_correction'::"text", 'event_expired'::"text", 'operator_cancelled'::"text", 'policy_rollback'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_region_keys_check" CHECK ("public"."regional_recommendation_hold_region_keys_are_safe"("region_keys")),
    CONSTRAINT "regional_recommendation_holds_request_id_check" CHECK ((("request_id" IS NULL) OR ("request_id" ~ '^[A-Za-z0-9:_-]{1,96}$'::"text"))),
    CONSTRAINT "regional_recommendation_holds_scope_beach_ids_check" CHECK ((("cardinality"("scope_beach_ids") >= 1) AND ("cardinality"("scope_beach_ids") <= 2000))),
    CONSTRAINT "regional_recommendation_holds_scope_exposure_classes_check" CHECK (("scope_exposure_classes" <@ ARRAY['fully_exposed'::"text", 'partially_protected'::"text", 'protected'::"text", 'unknown'::"text"])),
    CONSTRAINT "regional_recommendation_holds_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_supporting_evidence_refs_check" CHECK ((("jsonb_typeof"("supporting_evidence_refs") = 'array'::"text") AND "public"."regional_recommendation_hold_refs_are_safe"("supporting_evidence_refs"))),
    CONSTRAINT "regional_recommendation_holds_transition_check" CHECK (("transition" = ANY (ARRAY['activation'::"text", 'extension'::"text", 'replacement'::"text", 'cancellation'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_trigger_type_check" CHECK (("trigger_type" = ANY (ARRAY['automatic_official'::"text", 'manual_operator'::"text"]))),
    CONSTRAINT "regional_recommendation_holds_version_check" CHECK (("version" > 0))
);


ALTER TABLE "public"."regional_recommendation_holds" OWNER TO "postgres";


COMMENT ON TABLE "public"."regional_recommendation_holds" IS 'Append-only P0-A recommendation safety policy transitions. One row per audited transition.';



CREATE OR REPLACE FUNCTION "public"."append_regional_recommendation_hold_transition"("p_transition" "jsonb") RETURNS SETOF "public"."regional_recommendation_holds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_now timestamptz := transaction_timestamp();
  v_hold_id uuid;
  v_hold_id_text text;
  v_transition text;
  v_status text;
  v_trigger_type text;
  v_version integer;
  v_supersedes_record_id uuid;
  v_region_keys text[] := ARRAY[]::text[];
  v_scope_beach_ids uuid[] := ARRAY[]::uuid[];
  v_scope_exposure_classes text[] := ARRAY[]::text[];
  v_protected_alternative_beach_ids uuid[] := ARRAY[]::uuid[];
  v_event_reference text;
  v_valid_from timestamptz;
  v_valid_until timestamptz;
  v_affected_cohorts text[] := ARRAY[]::text[];
  v_action text;
  v_supporting_evidence_refs jsonb;
  v_automatic_policy_version text;
  v_authorizing_operator_ref uuid;
  v_authorizing_actor text;
  v_reason_code text;
  v_effective_at timestamptz;
  v_expires_at timestamptz;
  v_idempotency_key text;
  v_request_id text;
  v_operator_user_id uuid;
  v_operator_user_id_text text;
  v_operator_free_transition_text text;
  v_official_ref text;
  v_official_id uuid;
  v_risk_beach_id uuid;
  v_risk_valid_date date;
  v_risk_level text;
  v_risk_source text;
  v_risk_fetched_at timestamptz;
  v_beach_timezone text;
  v_local_today date;
  v_input_valid_from timestamptz;
  v_input_valid_until timestamptz;
  v_input_effective_at timestamptz;
  v_input_expires_at timestamptz;
  v_payload jsonb;
  v_payload_hash text;
  v_expected_input jsonb;
  v_key text;
  v_existing public.regional_recommendation_holds%ROWTYPE;
  v_previous public.regional_recommendation_holds%ROWTYPE;
  v_new public.regional_recommendation_holds%ROWTYPE;
BEGIN
  IF p_transition IS NULL OR jsonb_typeof(p_transition) <> 'object' THEN
    RAISE EXCEPTION 'hold transition must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_object_keys(p_transition) AS supplied(key)
    WHERE supplied.key <> ALL (ARRAY[
      'holdId',
      'version',
      'transition',
      'regionKeys',
      'scopeBeachIds',
      'scopeExposureClasses',
      'protectedAlternativeBeachIds',
      'eventReference',
      'validFrom',
      'validUntil',
      'affectedCohorts',
      'action',
      'triggerType',
      'supportingEvidenceRefs',
      'automaticPolicyVersion',
      'operatorUserId',
      'authorizingActor',
      'reasonCode',
      'effectiveAt',
      'expiresAt',
      'supersedesRecordId',
      'idempotencyKey',
      'requestId'
    ]::text[])
  ) THEN
    RAISE EXCEPTION 'hold transition contains an unsupported field'
      USING ERRCODE = '22023';
  END IF;

  v_hold_id_text := p_transition ->> 'holdId';
  IF v_hold_id_text IS NULL
     OR v_hold_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'invalid hold id' USING ERRCODE = '22023';
  END IF;
  v_hold_id := v_hold_id_text::uuid;

  v_transition := p_transition ->> 'transition';
  IF v_transition IS NULL
     OR v_transition NOT IN (
       'activation','extension','replacement','cancellation'
     ) THEN
    RAISE EXCEPTION 'invalid hold transition' USING ERRCODE = '22023';
  END IF;

  v_trigger_type := p_transition ->> 'triggerType';
  IF v_trigger_type IS NULL
     OR v_trigger_type NOT IN ('automatic_official','manual_operator') THEN
    RAISE EXCEPTION 'invalid hold trigger type' USING ERRCODE = '22023';
  END IF;

  v_idempotency_key := p_transition ->> 'idempotencyKey';
  IF v_idempotency_key IS NULL
     OR v_idempotency_key !~ '^[A-Za-z0-9:_-]{1,160}$' THEN
    RAISE EXCEPTION 'invalid idempotency key' USING ERRCODE = '22023';
  END IF;

  v_request_id := p_transition ->> 'requestId';
  IF v_request_id IS NOT NULL
     AND v_request_id !~ '^[A-Za-z0-9:_-]{1,96}$' THEN
    RAISE EXCEPTION 'invalid request id' USING ERRCODE = '22023';
  END IF;

  v_supporting_evidence_refs := COALESCE(
    p_transition -> 'supportingEvidenceRefs',
    '[]'::jsonb
  );
  IF NOT public.regional_recommendation_hold_refs_are_safe(
    v_supporting_evidence_refs
  ) THEN
    RAISE EXCEPTION 'invalid supporting evidence references'
      USING ERRCODE = '22023';
  END IF;

  -- The idempotency-key lock is acquired before the hold lock everywhere.
  -- That fixed order prevents cross-hold retries from deadlocking.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('regional-hold-idempotency:' || v_idempotency_key, 0)
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended('regional-hold:' || v_hold_id::text, 0)
  );

  SELECT *
  INTO v_existing
  FROM public.regional_recommendation_holds
  WHERE idempotency_key = v_idempotency_key;

  IF v_trigger_type = 'automatic_official' THEN
    IF v_transition <> 'activation'
       OR jsonb_array_length(v_supporting_evidence_refs) <> 1 THEN
      RAISE EXCEPTION 'automatic official holds require one activation reference'
        USING ERRCODE = '22023';
    END IF;

    v_official_ref := v_supporting_evidence_refs ->> 0;
    IF v_official_ref !~ '^official:rip_current_risks:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'automatic official reference is not eligible'
        USING ERRCODE = '22023';
    END IF;
    v_official_id := split_part(v_official_ref, ':', 3)::uuid;

    BEGIN
      IF p_transition ? 'validFrom' THEN
        v_input_valid_from := (p_transition ->> 'validFrom')::timestamptz;
      END IF;
      IF p_transition ? 'validUntil' THEN
        v_input_valid_until := (p_transition ->> 'validUntil')::timestamptz;
      END IF;
      IF p_transition ? 'effectiveAt' THEN
        v_input_effective_at := (p_transition ->> 'effectiveAt')::timestamptz;
      END IF;
      IF p_transition ? 'expiresAt' THEN
        v_input_expires_at := (p_transition ->> 'expiresAt')::timestamptz;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'automatic field conflicts with official evidence'
        USING ERRCODE = '22023';
    END;

    -- Exact retries return before clock-dependent normalization. Integrity is
    -- checked against the canonical stored tuple, not caller metadata.
    IF v_existing.record_id IS NOT NULL THEN
      v_new := v_existing;
      v_new.request_id := v_request_id;
      v_payload := public.regional_recommendation_hold_canonical_payload(
        v_new
      );
      v_payload_hash := encode(
        pg_catalog.sha256(convert_to(v_payload::text, 'UTF8')),
        'hex'
      );

      v_expected_input := jsonb_build_object(
        'holdId', v_existing.hold_id::text,
        'version', v_existing.version,
        'transition', v_existing.transition,
        'regionKeys', to_jsonb(v_existing.region_keys),
        'scopeBeachIds', to_jsonb(v_existing.scope_beach_ids),
        'scopeExposureClasses', to_jsonb(v_existing.scope_exposure_classes),
        'protectedAlternativeBeachIds',
          to_jsonb(v_existing.protected_alternative_beach_ids),
        'eventReference', v_existing.event_reference,
        'validFrom', v_existing.valid_from,
        'validUntil', v_existing.valid_until,
        'affectedCohorts', to_jsonb(v_existing.affected_cohorts),
        'action', v_existing.action,
        'triggerType', v_existing.trigger_type,
        'supportingEvidenceRefs', v_existing.supporting_evidence_refs,
        'automaticPolicyVersion', v_existing.automatic_policy_version,
        'authorizingActor', v_existing.authorizing_actor,
        'reasonCode', v_existing.reason_code,
        'effectiveAt', v_existing.effective_at,
        'expiresAt', v_existing.expires_at,
        'supersedesRecordId', v_existing.supersedes_record_id,
        'idempotencyKey', v_existing.idempotency_key,
        'requestId', v_existing.request_id
      );

      FOR v_key IN SELECT jsonb_object_keys(p_transition)
      LOOP
        IF v_key IN ('validFrom','validUntil','effectiveAt','expiresAt') THEN
          CONTINUE;
        END IF;

        IF (p_transition -> v_key) IS DISTINCT FROM (v_expected_input -> v_key) THEN
          RAISE EXCEPTION 'hold idempotency collision'
            USING ERRCODE = '23505';
        END IF;
      END LOOP;

      IF (p_transition ? 'validFrom'
          AND v_input_valid_from IS DISTINCT FROM v_existing.valid_from)
         OR (p_transition ? 'validUntil'
          AND v_input_valid_until IS DISTINCT FROM v_existing.valid_until)
         OR (p_transition ? 'effectiveAt'
          AND v_input_effective_at IS DISTINCT FROM v_existing.effective_at)
         OR (p_transition ? 'expiresAt'
          AND v_input_expires_at IS DISTINCT FROM v_existing.expires_at)
         OR v_request_id IS DISTINCT FROM v_existing.request_id
         OR v_existing.payload_hash <> v_payload_hash THEN
        RAISE EXCEPTION 'hold idempotency collision'
          USING ERRCODE = '23505';
      END IF;

      RETURN NEXT v_existing;
      RETURN;
    END IF;

    IF p_transition ? 'operatorUserId' THEN
      RAISE EXCEPTION 'automatic official holds cannot identify an operator'
        USING ERRCODE = '22023';
    END IF;

    SELECT
      r.beach_id,
      r.valid_date,
      r.risk_level,
      r.source,
      r.fetched_at,
      b.timezone
    INTO
      v_risk_beach_id,
      v_risk_valid_date,
      v_risk_level,
      v_risk_source,
      v_risk_fetched_at,
      v_beach_timezone
    FROM public.rip_current_risks AS r
    JOIN public.beaches AS b ON b.id = r.beach_id
    WHERE r.id = v_official_id
    FOR UPDATE OF r, b;

    IF NOT FOUND
       OR v_risk_level IS DISTINCT FROM 'high'
       OR (
         v_risk_source IS DISTINCT FROM 'srf'
         AND v_risk_source IS DISTINCT FROM 'alert'
       )
       OR v_risk_fetched_at IS NULL
       OR v_risk_fetched_at < transaction_timestamp() - interval '12 hours'
       OR v_risk_fetched_at > transaction_timestamp() + interval '5 minutes'
       OR v_beach_timezone IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM pg_catalog.pg_timezone_names AS zones
         WHERE zones.name = v_beach_timezone
       ) THEN
      RAISE EXCEPTION 'automatic official reference is not eligible'
        USING ERRCODE = '22023';
    END IF;

    v_local_today := (v_now AT TIME ZONE v_beach_timezone)::date;
    IF v_risk_valid_date IS NULL
       OR v_risk_valid_date < v_local_today
       OR v_risk_valid_date > v_local_today + 2 THEN
      RAISE EXCEPTION 'automatic official reference date is not eligible'
        USING ERRCODE = '22023';
    END IF;

    v_version := 1;
    v_status := 'active';
    v_region_keys := ARRAY[]::text[];
    v_scope_beach_ids := ARRAY[v_risk_beach_id];
    v_scope_exposure_classes := ARRAY[]::text[];
    v_protected_alternative_beach_ids := ARRAY[]::uuid[];
    v_event_reference := v_official_ref;
    v_valid_from := v_risk_valid_date::timestamp AT TIME ZONE v_beach_timezone;
    v_valid_until := (v_risk_valid_date + 1)::timestamp
      AT TIME ZONE v_beach_timezone;
    v_affected_cohorts := ARRAY[
      'beginner','intermediate','unknown'
    ]::text[];
    v_action := 'suppress_positive';
    v_automatic_policy_version := 'official-rip-high.v1';
    v_authorizing_operator_ref := NULL;
    v_authorizing_actor := 'official_automation';
    v_reason_code := 'official_high_rip_current';
    v_effective_at := GREATEST(v_now, v_valid_from);
    v_expires_at := v_valid_until;
    v_supersedes_record_id := NULL;

    v_expected_input := jsonb_build_object(
      'holdId', v_hold_id::text,
      'version', v_version,
      'transition', v_transition,
      'regionKeys', to_jsonb(v_region_keys),
      'scopeBeachIds', to_jsonb(v_scope_beach_ids),
      'scopeExposureClasses', to_jsonb(v_scope_exposure_classes),
      'protectedAlternativeBeachIds',
        to_jsonb(v_protected_alternative_beach_ids),
      'eventReference', v_event_reference,
      'validFrom', v_valid_from,
      'validUntil', v_valid_until,
      'affectedCohorts', to_jsonb(v_affected_cohorts),
      'action', v_action,
      'triggerType', v_trigger_type,
      'supportingEvidenceRefs', v_supporting_evidence_refs,
      'automaticPolicyVersion', v_automatic_policy_version,
      'authorizingActor', v_authorizing_actor,
      'reasonCode', v_reason_code,
      'effectiveAt', v_effective_at,
      'expiresAt', v_expires_at,
      'supersedesRecordId', v_supersedes_record_id,
      'idempotencyKey', v_idempotency_key,
      'requestId', v_request_id
    );

    FOR v_key IN SELECT jsonb_object_keys(p_transition)
    LOOP
      IF v_key IN ('validFrom','validUntil','effectiveAt','expiresAt') THEN
        CONTINUE;
      END IF;

      IF (p_transition -> v_key) IS DISTINCT FROM (v_expected_input -> v_key) THEN
        RAISE EXCEPTION 'automatic field conflicts with official evidence'
          USING ERRCODE = '22023';
      END IF;
    END LOOP;

    IF (p_transition ? 'validFrom'
        AND v_input_valid_from IS DISTINCT FROM v_valid_from)
       OR (p_transition ? 'validUntil'
        AND v_input_valid_until IS DISTINCT FROM v_valid_until)
       OR (p_transition ? 'effectiveAt'
        AND v_input_effective_at IS DISTINCT FROM v_effective_at)
       OR (p_transition ? 'expiresAt'
        AND v_input_expires_at IS DISTINCT FROM v_expires_at) THEN
      RAISE EXCEPTION 'automatic field conflicts with official evidence'
        USING ERRCODE = '22023';
    END IF;
  ELSE
    IF (p_transition ->> 'authorizingActor') IS NOT NULL
       AND (p_transition ->> 'authorizingActor') <> 'admin_api' THEN
      RAISE EXCEPTION 'manual transition author is invalid'
        USING ERRCODE = '22023';
    END IF;
    IF p_transition ? 'automaticPolicyVersion'
       AND p_transition -> 'automaticPolicyVersion' <> 'null'::jsonb THEN
      RAISE EXCEPTION 'manual transition cannot set automatic policy'
        USING ERRCODE = '22023';
    END IF;

    v_operator_user_id_text := p_transition ->> 'operatorUserId';
    IF v_operator_user_id_text IS NULL
       OR v_operator_user_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'manual transition requires an operator'
        USING ERRCODE = '22023';
    END IF;
    v_operator_user_id := v_operator_user_id_text::uuid;

    -- The auth UUID is transient authorization input. Reject it anywhere in
    -- the remaining body so it cannot be stored or enter the payload hash.
    v_operator_free_transition_text := lower(
      (p_transition - 'operatorUserId')::text
    );
    IF position(
         lower(v_operator_user_id::text)
         IN v_operator_free_transition_text
       ) > 0
       OR position(
         replace(lower(v_operator_user_id::text), '-', '')
         IN replace(v_operator_free_transition_text, '-', '')
       ) > 0 THEN
      RAISE EXCEPTION 'manual transition metadata cannot identify operator'
        USING ERRCODE = '22023';
    END IF;

    PERFORM pg_advisory_xact_lock(
      hashtextextended(
        'regional-hold-operator:' || v_operator_user_id::text,
        0
      )
    );

    IF EXISTS (
      SELECT 1
      FROM public.account_deletions
      WHERE user_id = v_operator_user_id
    ) THEN
      RAISE EXCEPTION 'manual transition operator is unavailable'
        USING ERRCODE = '22023';
    END IF;

    PERFORM 1
    FROM auth.users AS operator_user
    JOIN public.profiles AS operator_profile
      ON operator_profile.id = operator_user.id
    WHERE operator_user.id = v_operator_user_id
      AND operator_profile.deleted_at IS NULL
      AND (
        operator_user.banned_until IS NULL
        OR operator_user.banned_until <= v_now
      )
    FOR KEY SHARE OF operator_user, operator_profile;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'manual transition operator is unavailable'
        USING ERRCODE = '22023';
    END IF;

    SELECT operator_ref
    INTO v_authorizing_operator_ref
    FROM public.regional_recommendation_hold_operator_refs
    WHERE operator_user_id = v_operator_user_id;

    IF v_authorizing_operator_ref IS NULL
       AND v_existing.record_id IS NOT NULL THEN
      RAISE EXCEPTION 'hold idempotency collision'
        USING ERRCODE = '23505';
    END IF;

    IF v_authorizing_operator_ref IS NULL THEN
      INSERT INTO public.regional_recommendation_hold_operator_refs (
        operator_user_id
      )
      VALUES (v_operator_user_id)
      ON CONFLICT (operator_user_id) DO NOTHING;

      SELECT operator_ref
      INTO v_authorizing_operator_ref
      FROM public.regional_recommendation_hold_operator_refs
      WHERE operator_user_id = v_operator_user_id;
    END IF;

    IF v_authorizing_operator_ref IS NOT DISTINCT FROM v_operator_user_id THEN
      RAISE EXCEPTION 'manual transition operator reference is unavailable'
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      v_version := (p_transition ->> 'version')::integer;
      v_valid_from := (p_transition ->> 'validFrom')::timestamptz;
      v_valid_until := (p_transition ->> 'validUntil')::timestamptz;
      v_effective_at := (p_transition ->> 'effectiveAt')::timestamptz;
      v_expires_at := (p_transition ->> 'expiresAt')::timestamptz;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'manual transition has invalid version or time fields'
        USING ERRCODE = '22023';
    END;

    IF v_version IS NULL
       OR v_valid_from IS NULL
       OR v_valid_until IS NULL
       OR v_effective_at IS NULL
       OR v_expires_at IS NULL
       OR v_valid_until <= v_valid_from
       OR v_expires_at <= v_effective_at
       OR v_expires_at > v_effective_at + interval '7 days' THEN
      RAISE EXCEPTION 'manual transition has invalid time bounds'
        USING ERRCODE = '22023';
    END IF;

    IF p_transition ->> 'supersedesRecordId' IS NOT NULL THEN
      IF (p_transition ->> 'supersedesRecordId')
           !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'invalid superseded record id'
          USING ERRCODE = '22023';
      END IF;
      v_supersedes_record_id := (
        p_transition ->> 'supersedesRecordId'
      )::uuid;
    END IF;

    IF jsonb_typeof(COALESCE(p_transition -> 'regionKeys', '[]'::jsonb))
         <> 'array'
       OR jsonb_typeof(p_transition -> 'scopeBeachIds') <> 'array'
       OR jsonb_typeof(
         COALESCE(p_transition -> 'scopeExposureClasses', '[]'::jsonb)
       ) <> 'array'
       OR jsonb_typeof(
         COALESCE(
           p_transition -> 'protectedAlternativeBeachIds',
           '[]'::jsonb
         )
       ) <> 'array'
       OR jsonb_typeof(p_transition -> 'affectedCohorts') <> 'array' THEN
      RAISE EXCEPTION 'manual transition has invalid array fields'
        USING ERRCODE = '22023';
    END IF;

    BEGIN
      SELECT COALESCE(
        array_agg(item.value ORDER BY item.ordinality),
        ARRAY[]::text[]
      )
      INTO v_region_keys
      FROM jsonb_array_elements_text(
        COALESCE(p_transition -> 'regionKeys', '[]'::jsonb)
      ) WITH ORDINALITY AS item(value, ordinality);

      SELECT COALESCE(
        array_agg(item.value::uuid ORDER BY item.ordinality),
        ARRAY[]::uuid[]
      )
      INTO v_scope_beach_ids
      FROM jsonb_array_elements_text(
        p_transition -> 'scopeBeachIds'
      ) WITH ORDINALITY AS item(value, ordinality);

      SELECT COALESCE(
        array_agg(item.value ORDER BY item.ordinality),
        ARRAY[]::text[]
      )
      INTO v_scope_exposure_classes
      FROM jsonb_array_elements_text(
        COALESCE(p_transition -> 'scopeExposureClasses', '[]'::jsonb)
      ) WITH ORDINALITY AS item(value, ordinality);

      SELECT COALESCE(
        array_agg(item.value::uuid ORDER BY item.ordinality),
        ARRAY[]::uuid[]
      )
      INTO v_protected_alternative_beach_ids
      FROM jsonb_array_elements_text(
        COALESCE(
          p_transition -> 'protectedAlternativeBeachIds',
          '[]'::jsonb
        )
      ) WITH ORDINALITY AS item(value, ordinality);

      SELECT COALESCE(
        array_agg(item.value ORDER BY item.ordinality),
        ARRAY[]::text[]
      )
      INTO v_affected_cohorts
      FROM jsonb_array_elements_text(
        p_transition -> 'affectedCohorts'
      ) WITH ORDINALITY AS item(value, ordinality);
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'manual transition has invalid array values'
        USING ERRCODE = '22023';
    END;

    IF NOT public.regional_recommendation_hold_region_keys_are_safe(
      v_region_keys
    )
       OR cardinality(v_scope_beach_ids) NOT BETWEEN 1 AND 2000
       OR cardinality(v_scope_exposure_classes) > 4
       OR NOT v_scope_exposure_classes <@ ARRAY[
         'fully_exposed','partially_protected','protected','unknown'
       ]::text[]
       OR cardinality(v_protected_alternative_beach_ids) > 2000
       OR cardinality(v_affected_cohorts) = 0
       OR NOT v_affected_cohorts <@ ARRAY[
         'beginner','intermediate','advanced','expert','unknown'
       ]::text[]
       OR cardinality(v_scope_beach_ids) <> (
         SELECT count(DISTINCT beach_id)
         FROM unnest(v_scope_beach_ids) AS beaches(beach_id)
       )
       OR cardinality(v_scope_exposure_classes) <> (
         SELECT count(DISTINCT exposure_class)
         FROM unnest(v_scope_exposure_classes) AS exposures(exposure_class)
       )
       OR cardinality(v_protected_alternative_beach_ids) <> (
         SELECT count(DISTINCT beach_id)
         FROM unnest(v_protected_alternative_beach_ids) AS beaches(beach_id)
       )
       OR cardinality(v_affected_cohorts) <> (
         SELECT count(DISTINCT cohort)
         FROM unnest(v_affected_cohorts) AS cohorts(cohort)
       ) THEN
      RAISE EXCEPTION 'manual transition has invalid scope or cohort fields'
        USING ERRCODE = '22023';
    END IF;

    v_event_reference := p_transition ->> 'eventReference';
    IF v_event_reference IS NOT NULL
       AND v_event_reference
         !~ '^(event|official|qa):[a-z0-9_]+:[A-Za-z0-9_-]{1,64}$' THEN
      RAISE EXCEPTION 'manual transition has invalid event reference'
        USING ERRCODE = '22023';
    END IF;

    v_action := p_transition ->> 'action';
    IF v_action IS NULL
       OR v_action NOT IN (
         'suppress_positive','protected_alternatives_only'
       )
       OR (
         v_action = 'protected_alternatives_only'
         AND cardinality(v_protected_alternative_beach_ids) = 0
       ) THEN
      RAISE EXCEPTION 'manual transition has invalid action'
        USING ERRCODE = '22023';
    END IF;

    v_reason_code := p_transition ->> 'reasonCode';
    IF v_reason_code IS NULL
       OR v_reason_code NOT IN (
         'major_swell_manual_safety',
         'official_high_rip_current',
         'scope_correction',
         'event_expired',
         'operator_cancelled',
         'policy_rollback'
       ) THEN
      RAISE EXCEPTION 'manual transition has invalid reason code'
        USING ERRCODE = '22023';
    END IF;

    v_status := CASE
      WHEN v_transition = 'cancellation' THEN 'cancelled'
      ELSE 'active'
    END;
    v_automatic_policy_version := NULL;
    v_authorizing_actor := 'admin_api';
  END IF;

  v_new.hold_id := v_hold_id;
  v_new.version := v_version;
  v_new.transition := v_transition;
  v_new.status := v_status;
  v_new.region_keys := v_region_keys;
  v_new.scope_beach_ids := v_scope_beach_ids;
  v_new.scope_exposure_classes := v_scope_exposure_classes;
  v_new.protected_alternative_beach_ids :=
    v_protected_alternative_beach_ids;
  v_new.event_reference := v_event_reference;
  v_new.valid_from := v_valid_from;
  v_new.valid_until := v_valid_until;
  v_new.affected_cohorts := v_affected_cohorts;
  v_new.action := v_action;
  v_new.trigger_type := v_trigger_type;
  v_new.supporting_evidence_refs := v_supporting_evidence_refs;
  v_new.automatic_policy_version := v_automatic_policy_version;
  v_new.authorizing_operator_ref := v_authorizing_operator_ref;
  v_new.authorizing_actor := v_authorizing_actor;
  v_new.reason_code := v_reason_code;
  v_new.effective_at := v_effective_at;
  v_new.expires_at := v_expires_at;
  v_new.supersedes_record_id := v_supersedes_record_id;
  v_new.idempotency_key := v_idempotency_key;
  v_new.request_id := v_request_id;

  v_payload := public.regional_recommendation_hold_canonical_payload(v_new);
  v_payload_hash := encode(
    pg_catalog.sha256(convert_to(v_payload::text, 'UTF8')),
    'hex'
  );
  v_new.payload_hash := v_payload_hash;

  IF v_existing.record_id IS NOT NULL THEN
    IF v_existing.payload_hash <> v_payload_hash THEN
      RAISE EXCEPTION 'hold idempotency collision'
        USING ERRCODE = '23505';
    END IF;

    RETURN NEXT v_existing;
    RETURN;
  END IF;

  SELECT *
  INTO v_previous
  FROM public.regional_recommendation_holds
  WHERE hold_id = v_hold_id
  ORDER BY version DESC
  LIMIT 1
  FOR UPDATE;

  IF v_transition = 'activation' THEN
    IF v_version <> 1
       OR v_supersedes_record_id IS NOT NULL
       OR v_previous.record_id IS NOT NULL THEN
      RAISE EXCEPTION 'activation must start a new hold chain'
        USING ERRCODE = '22023';
    END IF;
  ELSIF v_previous.record_id IS NULL
        OR v_version <> v_previous.version + 1
        OR v_supersedes_record_id IS DISTINCT FROM v_previous.record_id THEN
    RAISE EXCEPTION 'transition must supersede the latest hold version'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.regional_recommendation_holds (
    hold_id,
    version,
    transition,
    status,
    region_keys,
    scope_beach_ids,
    scope_exposure_classes,
    protected_alternative_beach_ids,
    event_reference,
    valid_from,
    valid_until,
    affected_cohorts,
    action,
    trigger_type,
    supporting_evidence_refs,
    automatic_policy_version,
    authorizing_operator_ref,
    authorizing_actor,
    reason_code,
    effective_at,
    expires_at,
    supersedes_record_id,
    idempotency_key,
    payload_hash,
    request_id
  )
  VALUES (
    v_new.hold_id,
    v_new.version,
    v_new.transition,
    v_new.status,
    v_new.region_keys,
    v_new.scope_beach_ids,
    v_new.scope_exposure_classes,
    v_new.protected_alternative_beach_ids,
    v_new.event_reference,
    v_new.valid_from,
    v_new.valid_until,
    v_new.affected_cohorts,
    v_new.action,
    v_new.trigger_type,
    v_new.supporting_evidence_refs,
    v_new.automatic_policy_version,
    v_new.authorizing_operator_ref,
    v_new.authorizing_actor,
    v_new.reason_code,
    v_new.effective_at,
    v_new.expires_at,
    v_new.supersedes_record_id,
    v_new.idempotency_key,
    v_new.payload_hash,
    v_new.request_id
  )
  RETURNING * INTO v_new;

  RETURN NEXT v_new;
END;
$_$;


ALTER FUNCTION "public"."append_regional_recommendation_hold_transition"("p_transition" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."append_regional_recommendation_hold_transition"("p_transition" "jsonb") IS 'Only application write boundary for manual and database-verified official recommendation hold transitions.';



CREATE OR REPLACE FUNCTION "public"."append_swell_watch_state_transition"("p_transition_id" "uuid", "p_regional_event_id" "uuid", "p_expected_version" integer, "p_state" "text", "p_evaluation_id" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_current integer; v_next integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('swell-watch-event:' || p_regional_event_id::text, 0));
  SELECT coalesce(max(version), 0) INTO v_current FROM public.swell_watch_event_state_transitions WHERE regional_event_id = p_regional_event_id;
  IF v_current IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION 'swell watch transition version conflict'; END IF;
  IF p_state = 'stable' THEN RAISE EXCEPTION 'stable transitions require evidence advancement'; END IF;
  PERFORM set_config('app.swell_watch_internal_write', 'on', true);
  v_next := v_current + 1;
  INSERT INTO public.swell_watch_event_state_transitions (id, regional_event_id, state, version, trigger_evaluation_id) VALUES (p_transition_id, p_regional_event_id, p_state, v_next, p_evaluation_id);
  RETURN v_next;
END;
$$;


ALTER FUNCTION "public"."append_swell_watch_state_transition"("p_transition_id" "uuid", "p_regional_event_id" "uuid", "p_expected_version" integer, "p_state" "text", "p_evaluation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_android_tester_roster_snapshot"("p_actor_user_id" "uuid", "p_claim_token" "uuid", "p_snapshot_complete" boolean, "p_observed_at" timestamp with time zone, "p_observations" "jsonb", "p_direct_user_count" integer, "p_failure_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  observation jsonb;
  v_entry_id uuid;
  v_claim_token uuid;
  v_sync_run_id uuid;
  v_changed integer := 0;
  v_added integer := 0;
  v_rejoined integer := 0;
  v_refreshed integer := 0;
  v_left integer := 0;
  v_purged integer := 0;
BEGIN
  SELECT claim.claim_token
  INTO v_claim_token
  FROM public.android_tester_roster_sync_claims AS claim
  WHERE claim.singleton
    AND claim.claim_token = p_claim_token
  FOR UPDATE;

  IF v_claim_token IS NULL THEN
    RAISE EXCEPTION 'Android tester roster sync claim unavailable';
  END IF;

  INSERT INTO public.android_tester_roster_sync_runs (
    source,
    complete,
    observed_at,
    direct_user_count,
    failure_code
  ) VALUES (
    'google_directory',
    p_snapshot_complete,
    p_observed_at,
    GREATEST(COALESCE(p_direct_user_count, 0), 0),
    p_failure_code
  )
  RETURNING id INTO v_sync_run_id;

  IF NOT p_snapshot_complete THEN
    INSERT INTO public.android_tester_roster_audit (
      actor_user_id,
      action,
      outcome,
      evidence
    ) VALUES (
      p_actor_user_id,
      'sync',
      'failed',
      jsonb_build_object('failureCode', COALESCE(p_failure_code, 'incomplete'))
    );
    DELETE FROM public.android_tester_roster_sync_claims
    WHERE singleton
      AND claim_token = p_claim_token;
    RETURN jsonb_build_object('complete', false);
  END IF;

  FOR observation IN
    SELECT value FROM jsonb_array_elements(COALESCE(p_observations, '[]'::jsonb))
  LOOP
    IF observation->>'kind' = 'new' THEN
      INSERT INTO public.android_tester_roster_entries (
        eligibility_status,
        group_membership_status,
        eligibility_source,
        eligibility_observed_at,
        eligibility_confidence
      ) VALUES (
        'eligible',
        'active',
        'google_directory',
        p_observed_at,
        'verified'
      )
      RETURNING id INTO v_entry_id;

      INSERT INTO public.android_tester_roster_identities (
        entry_id,
        key_version,
        iv,
        ciphertext,
        auth_tag
      ) VALUES (
        v_entry_id,
        (observation->>'keyVersion')::integer,
        observation->>'iv',
        observation->>'ciphertext',
        observation->>'authTag'
      );

      INSERT INTO public.android_tester_roster_stages (
        entry_id,
        stage,
        status,
        source,
        observed_at,
        confidence,
        evidence
      ) VALUES
        (
          v_entry_id,
          'play_opt_in',
          'unknown',
          'roster_initial_state',
          p_observed_at,
          'unknown',
          '{}'::jsonb
        ),
        (
          v_entry_id,
          'install',
          'unknown',
          'roster_initial_state',
          p_observed_at,
          'unknown',
          '{}'::jsonb
        ),
        (
          v_entry_id,
          'first_open',
          'unknown',
          'roster_initial_state',
          p_observed_at,
          'unknown',
          '{}'::jsonb
        ),
        (
          v_entry_id,
          'account_join',
          'unknown',
          'roster_initial_state',
          p_observed_at,
          'unknown',
          '{}'::jsonb
        );
      v_added := v_added + 1;
    ELSIF observation->>'kind' = 'seen' THEN
      v_entry_id := (observation->>'entryId')::uuid;
      UPDATE public.android_tester_roster_entries
      SET
        eligibility_observed_at = p_observed_at,
        updated_at = now()
      WHERE id = v_entry_id
        AND eligibility_status = 'eligible';
    ELSIF observation->>'kind' = 'rejoined' THEN
      v_entry_id := (observation->>'entryId')::uuid;
      UPDATE public.android_tester_roster_entries
      SET
        eligibility_status = 'eligible',
        group_membership_status = 'active',
        eligibility_observed_at = p_observed_at,
        eligibility_confidence = 'verified',
        purge_after = NULL,
        updated_at = now()
      WHERE id = v_entry_id
        AND user_id IS NULL;

      INSERT INTO public.android_tester_roster_identities (
        entry_id,
        key_version,
        iv,
        ciphertext,
        auth_tag
      )
      SELECT
        v_entry_id,
        (observation->>'keyVersion')::integer,
        observation->>'iv',
        observation->>'ciphertext',
        observation->>'authTag'
      WHERE EXISTS (
        SELECT 1
        FROM public.android_tester_roster_entries AS entry
        WHERE entry.id = v_entry_id
          AND entry.user_id IS NULL
      )
      ON CONFLICT (entry_id) DO UPDATE SET
        key_version = EXCLUDED.key_version,
        iv = EXCLUDED.iv,
        ciphertext = EXCLUDED.ciphertext,
        auth_tag = EXCLUDED.auth_tag,
        updated_at = now();
      v_rejoined := v_rejoined + 1;
    ELSIF observation->>'kind' = 'identity_refresh' THEN
      v_entry_id := (observation->>'entryId')::uuid;
      UPDATE public.android_tester_roster_entries
      SET
        eligibility_observed_at = p_observed_at,
        updated_at = now()
      WHERE id = v_entry_id
        AND eligibility_status = 'eligible'
        AND user_id IS NULL;

      INSERT INTO public.android_tester_roster_identities (
        entry_id,
        key_version,
        iv,
        ciphertext,
        auth_tag
      )
      SELECT
        v_entry_id,
        (observation->>'keyVersion')::integer,
        observation->>'iv',
        observation->>'ciphertext',
        observation->>'authTag'
      WHERE EXISTS (
        SELECT 1
        FROM public.android_tester_roster_entries AS entry
        WHERE entry.id = v_entry_id
          AND entry.user_id IS NULL
      )
      ON CONFLICT (entry_id) DO UPDATE SET
        key_version = EXCLUDED.key_version,
        iv = EXCLUDED.iv,
        ciphertext = EXCLUDED.ciphertext,
        auth_tag = EXCLUDED.auth_tag,
        updated_at = now();
      GET DIAGNOSTICS v_changed = ROW_COUNT;
      v_refreshed := v_refreshed + v_changed;
    ELSIF observation->>'kind' = 'rejoined_linked' THEN
      v_entry_id := (observation->>'entryId')::uuid;
      UPDATE public.android_tester_roster_entries
      SET
        eligibility_status = 'eligible',
        group_membership_status = 'active',
        eligibility_observed_at = p_observed_at,
        eligibility_confidence = 'verified',
        purge_after = NULL,
        updated_at = now()
      WHERE id = v_entry_id
        AND user_id IS NOT NULL;
      v_rejoined := v_rejoined + 1;
    ELSIF observation->>'kind' = 'left' THEN
      v_entry_id := (observation->>'entryId')::uuid;
      PERFORM 1
      FROM public.android_tester_roster_entries AS entry
      WHERE entry.id = v_entry_id
      FOR UPDATE;

      UPDATE public.android_tester_roster_entries
      SET
        eligibility_status = 'ineligible',
        group_membership_status = 'left',
        eligibility_observed_at = p_observed_at,
        purge_after = p_observed_at + interval '30 days',
        updated_at = now()
      WHERE id = v_entry_id
        AND user_id IS NULL;
      GET DIAGNOSTICS v_changed = ROW_COUNT;
      v_left := v_left + v_changed;
      IF v_changed = 0 THEN
        CONTINUE;
      END IF;
    ELSIF observation->>'kind' = 'left_linked' THEN
      v_entry_id := (observation->>'entryId')::uuid;
      UPDATE public.android_tester_roster_entries
      SET
        eligibility_status = 'ineligible',
        group_membership_status = 'left',
        eligibility_observed_at = p_observed_at,
        purge_after = NULL,
        updated_at = now()
      WHERE id = v_entry_id
        AND user_id IS NOT NULL;
      v_left := v_left + 1;
    ELSE
      RAISE EXCEPTION 'Unsupported roster observation';
    END IF;

    INSERT INTO public.android_tester_roster_stages (
      entry_id,
      stage,
      status,
      source,
      observed_at,
      confidence,
      evidence
    ) VALUES (
      v_entry_id,
      'group_eligibility',
      CASE
        WHEN observation->>'kind' IN ('left', 'left_linked')
          THEN 'ineligible'
        ELSE 'eligible'
      END,
      'google_directory',
      p_observed_at,
      'verified',
      '{}'::jsonb
    );
  END LOOP;

  DELETE FROM public.android_tester_roster_identities AS identity
  USING public.android_tester_roster_entries AS entry
  WHERE identity.entry_id = entry.id
    AND entry.user_id IS NULL
    AND entry.eligibility_status = 'ineligible'
    AND entry.purge_after <= p_observed_at;
  GET DIAGNOSTICS v_purged = ROW_COUNT;

  UPDATE public.android_tester_roster_sync_runs
  SET
    added_count = v_added,
    rejoined_count = v_rejoined,
    refreshed_count = v_refreshed,
    left_count = v_left,
    purged_count = v_purged
  WHERE id = v_sync_run_id;

  INSERT INTO public.android_tester_roster_audit (
    actor_user_id,
    action,
    outcome,
    evidence
  ) VALUES (
    p_actor_user_id,
    'sync',
    'succeeded',
    jsonb_build_object(
      'directUserCount', p_direct_user_count,
      'addedCount', v_added,
      'rejoinedCount', v_rejoined,
      'refreshedCount', v_refreshed,
      'leftCount', v_left,
      'purgedCount', v_purged
    )
  );

  DELETE FROM public.android_tester_roster_sync_claims
  WHERE singleton
    AND claim_token = p_claim_token;

  RETURN jsonb_build_object(
    'complete', true,
    'addedCount', v_added,
    'rejoinedCount', v_rejoined,
    'refreshedCount', v_refreshed,
    'leftCount', v_left,
    'purgedCount', v_purged
  );
END;
$$;


ALTER FUNCTION "public"."apply_android_tester_roster_snapshot"("p_actor_user_id" "uuid", "p_claim_token" "uuid", "p_snapshot_complete" boolean, "p_observed_at" timestamp with time zone, "p_observations" "jsonb", "p_direct_user_count" integer, "p_failure_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_session_rip_current_risk"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  session_local_date DATE;
BEGIN
  NEW.rip_current_risk := NULL;

  IF NEW.beach_id IS NULL OR NEW.arrival_time IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT (NEW.arrival_time AT TIME ZONE b.timezone)::date
  INTO session_local_date
  FROM public.beaches b
  WHERE b.id = NEW.beach_id
    AND b.timezone IS NOT NULL;

  IF session_local_date IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT r.risk_level
  INTO NEW.rip_current_risk
  FROM public.rip_current_risks r
  WHERE r.beach_id = NEW.beach_id
    AND r.valid_date = session_local_date
  LIMIT 1;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."apply_session_rip_current_risk"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_session_tide_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  snapshot RECORD;
  has_snapshot BOOLEAN := false;
  has_manual_tide BOOLEAN := false;
  status_only_tide BOOLEAN := false;
  cleared_user_status BOOLEAN := false;
  should_recompute_tide BOOLEAN := false;
BEGIN
  IF NEW.beach_id IS NULL OR NEW.arrival_time IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT * INTO snapshot FROM public.compute_session_tide_snapshot(NEW.beach_id, NEW.arrival_time) LIMIT 1;
  has_snapshot := FOUND;

  should_recompute_tide :=
    TG_OP = 'UPDATE'
    AND (NEW.beach_id IS DISTINCT FROM OLD.beach_id OR NEW.arrival_time IS DISTINCT FROM OLD.arrival_time)
    AND COALESCE(NEW.tide_data_source, '') <> 'user';

  IF should_recompute_tide THEN
    -- A height typed in the same save as the move is the user's measurement; keep it.
    IF NEW.tide_height_ft IS NOT NULL AND NEW.tide_height_ft IS DISTINCT FROM OLD.tide_height_ft THEN
      NEW.tide_data_source := 'user';
      IF NEW.tide_rate_ft_per_hr IS NULL AND has_snapshot THEN
        NEW.tide_rate_ft_per_hr := snapshot.tide_rate_ft_per_hr;
      END IF;
      RETURN NEW;
    END IF;
    -- A chip tapped in the same save is the user's status.
    IF NEW.tide_status IS NOT NULL AND NEW.tide_status IS DISTINCT FROM OLD.tide_status THEN
      NEW.tide_status_user_set := true;
    END IF;
    IF has_snapshot THEN
      NEW.tide_height_ft := snapshot.tide_height_ft;
      IF NOT NEW.tide_status_user_set THEN
        NEW.tide_status := snapshot.tide_status;
      END IF;
      NEW.tide_rate_ft_per_hr := snapshot.tide_rate_ft_per_hr;
      NEW.tide_data_source := snapshot.tide_data_source;
    ELSE
      NEW.tide_height_ft := NULL;
      IF NOT NEW.tide_status_user_set THEN
        NEW.tide_status := NULL;
      END IF;
      NEW.tide_rate_ft_per_hr := NULL;
      NEW.tide_data_source := NULL;
    END IF;
    RETURN NEW;
  END IF;

  cleared_user_status :=
    TG_OP = 'UPDATE'
    AND OLD.tide_status_user_set
    AND OLD.tide_status IS NOT NULL
    AND NEW.tide_status IS NULL
    AND NEW.tide_height_ft IS NOT DISTINCT FROM OLD.tide_height_ft;

  IF cleared_user_status THEN
    NEW.tide_status_user_set := false;
  END IF;

  status_only_tide :=
    NEW.tide_status IS NOT NULL
    AND (
      (TG_OP = 'INSERT' AND NEW.tide_height_ft IS NULL)
      OR (
        TG_OP = 'UPDATE'
        AND NEW.tide_status IS DISTINCT FROM OLD.tide_status
        AND NEW.tide_height_ft IS NOT DISTINCT FROM OLD.tide_height_ft
        AND (OLD.tide_height_ft IS NULL OR COALESCE(OLD.tide_data_source, '') <> 'user')
      )
    );

  IF status_only_tide THEN
    NEW.tide_status_user_set := true;
    IF has_snapshot THEN
      NEW.tide_height_ft := snapshot.tide_height_ft;
      NEW.tide_rate_ft_per_hr := snapshot.tide_rate_ft_per_hr;
      NEW.tide_data_source := snapshot.tide_data_source;
    ELSE
      NEW.tide_height_ft := NULL;
      NEW.tide_rate_ft_per_hr := NULL;
      NEW.tide_data_source := NULL;
    END IF;
    RETURN NEW;
  END IF;

  has_manual_tide :=
    NOT cleared_user_status
    AND (
      COALESCE(NEW.tide_data_source, '') = 'user'
      OR (TG_OP = 'INSERT' AND (NEW.tide_height_ft IS NOT NULL OR NEW.tide_status IS NOT NULL))
      OR (
        TG_OP = 'UPDATE'
        AND (NEW.tide_height_ft IS DISTINCT FROM OLD.tide_height_ft OR NEW.tide_status IS DISTINCT FROM OLD.tide_status)
        AND (NEW.tide_height_ft IS NOT NULL OR NEW.tide_status IS NOT NULL)
      )
    );

  IF has_manual_tide THEN
    NEW.tide_data_source := 'user';
    IF NEW.tide_rate_ft_per_hr IS NULL AND has_snapshot THEN
      NEW.tide_rate_ft_per_hr := snapshot.tide_rate_ft_per_hr;
    END IF;
    RETURN NEW;
  END IF;

  IF has_snapshot THEN
    NEW.tide_height_ft := snapshot.tide_height_ft;
    IF NOT NEW.tide_status_user_set THEN
      NEW.tide_status := snapshot.tide_status;
    END IF;
    NEW.tide_rate_ft_per_hr := snapshot.tide_rate_ft_per_hr;
    NEW.tide_data_source := snapshot.tide_data_source;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."apply_session_tide_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_session_wave_height_source"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  submit_metadata jsonb;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- The snapshot trigger re-syncs truth after this, so an edited height counts again.
    IF OLD.wave_height_source = 'forecast_prefill'
      AND NEW.wave_height_source IS NOT DISTINCT FROM OLD.wave_height_source
      AND NEW.wave_height_ft IS DISTINCT FROM OLD.wave_height_ft
      AND NEW.wave_height_ft IS NOT NULL
    THEN
      NEW.wave_height_source := 'user';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.wave_height_source IS NOT NULL OR NEW.wave_height_ft IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    SELECT e.metadata
    INTO submit_metadata
    FROM public.user_events e
    WHERE e.user_id = NEW.user_id
      AND e.event_type = 'session_log_submit'
      AND (e.metadata->>'event_id') IS NOT NULL
      AND (e.metadata->>'event_id') <> ''
      AND (e.metadata->>'event_id') IN (
        'session:' || NEW.id::text || ':submit:v1',
        'session:' || NEW.id::text || ':submit:web:v1'
      )
    LIMIT 1;

    NEW.wave_height_source := public.session_wave_height_source_from_submit(submit_metadata);
  EXCEPTION WHEN OTHERS THEN
    -- Provenance must never block a session save.
    RAISE WARNING 'apply_session_wave_height_source skipped for session %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."apply_session_wave_height_source"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_submit_wave_height_source_to_session"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  derived_source text;
  labeled public.sessions%ROWTYPE;
BEGIN
  derived_source := public.session_wave_height_source_from_submit(NEW.metadata);
  IF derived_source IS NULL
    OR NEW.user_id IS NULL
    OR coalesce(NEW.metadata->>'session_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  THEN
    RETURN NULL;
  END IF;

  BEGIN
    UPDATE public.sessions
    SET wave_height_source = derived_source
    WHERE id = (NEW.metadata->>'session_id')::uuid
      AND user_id = NEW.user_id
      AND wave_height_ft IS NOT NULL
      AND wave_height_source IS NULL
    RETURNING * INTO labeled;

    -- The snapshot trigger does not watch wave_height_source, so re-run the truth sync.
    IF labeled.id IS NOT NULL AND derived_source = 'forecast_prefill' THEN
      PERFORM public.sync_session_wave_observation_candidate(
        labeled.id,
        labeled.user_id,
        labeled.beach_id::uuid,
        labeled.arrival_time,
        labeled.status,
        labeled.wave_height_ft,
        'trigger'
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- An analytics insert must never fail because of provenance.
    RAISE WARNING 'apply_submit_wave_height_source_to_session skipped for event %: %', NEW.id, SQLERRM;
  END;

  RETURN NULL;
END;
$_$;


ALTER FUNCTION "public"."apply_submit_wave_height_source_to_session"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_verified_pro_offer_mirror"("p_award_id" "uuid", "p_receipt" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE a public.pro_offer_awards%ROWTYPE;
BEGIN
 PERFORM pg_advisory_xact_lock(739302);
 SELECT * INTO a FROM public.pro_offer_awards WHERE id=p_award_id AND state='verified' FOR UPDATE;
 IF a.id IS NULL OR a.expires_at<=now() OR p_receipt->>'user_id' IS DISTINCT FROM a.user_id::text
 OR p_receipt->>'store' IS DISTINCT FROM 'promotional' OR p_receipt->>'product_id' IS DISTINCT FROM a.provider_receipt->>'product_id'
 OR p_receipt->>'entitlement_id' IS DISTINCT FROM a.entitlement_id OR (p_receipt->>'expires_at')::timestamptz IS DISTINCT FROM a.expires_at
 OR (p_receipt->>'observed_at')::timestamptz IS NULL OR (p_receipt->>'observed_at')::timestamptz NOT BETWEEN now()-interval '1 minute' AND now()+interval '5 seconds'
 THEN RAISE EXCEPTION 'Fresh provider proof required for mirror repair'; END IF;
 INSERT INTO public.user_entitlements(user_id,is_pro,is_trialing,trial_ends_at,expires_at,product_id)
 VALUES(a.user_id,true,false,NULL,a.expires_at,p_receipt->>'product_id')
 ON CONFLICT(user_id) DO UPDATE SET is_pro=true,is_trialing=false,trial_ends_at=NULL,expires_at=excluded.expires_at,product_id=excluded.product_id
 WHERE NOT (user_entitlements.is_pro OR user_entitlements.is_trialing) OR user_entitlements.expires_at<=now();
END; $$;


ALTER FUNCTION "public"."apply_verified_pro_offer_mirror"("p_award_id" "uuid", "p_receipt" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assess_apple_identity_recovery"("p_canonical_user_id" "uuid", "p_apple_sub" "text", "p_apple_token_sha256" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $_$
DECLARE
  v_identity auth.identities%ROWTYPE;
  v_existing public.apple_identity_recovery_requests%ROWTYPE;
  v_dependency record;
  v_dependency_count bigint;
  v_data_counts jsonb := '{}'::jsonb;
  v_has_product_data boolean := false;
  v_recovery_id uuid;
  v_support_reference text;
  v_secondary_created_at timestamptz;
  v_expires_at timestamptz := clock_timestamp() + interval '10 minutes';
BEGIN
  IF p_canonical_user_id IS NULL
     OR length(p_apple_sub) = 0
     OR p_apple_token_sha256 !~ '^[0-9a-f]{64}$'
     OR length(p_idempotency_key) < 8
     OR length(p_idempotency_key) > 128 THEN
    RAISE EXCEPTION 'invalid apple recovery assessment input';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_constraint current_constraint
    JOIN pg_class source_table ON source_table.oid = current_constraint.conrelid
    JOIN pg_namespace source_ns ON source_ns.oid = source_table.relnamespace
    JOIN pg_class target_table ON target_table.oid = current_constraint.confrelid
    JOIN pg_namespace target_ns ON target_ns.oid = target_table.relnamespace
    WHERE current_constraint.contype = 'f'
      AND source_ns.nspname = 'public'
      AND current_constraint.confrelid IN ('auth.users'::regclass, 'public.profiles'::regclass)
      AND NOT EXISTS (
        SELECT 1
        FROM public.apple_recovery_dependency_registry registry
        WHERE registry.source_schema = source_ns.nspname
          AND registry.source_table = source_table.relname
          AND registry.constraint_name = current_constraint.conname
          AND registry.target_schema = target_ns.nspname
          AND registry.target_table = target_table.relname
      )
  ) THEN
    INSERT INTO public.apple_identity_recovery_audit (
      canonical_user_id,
      event_type
    ) VALUES (
      p_canonical_user_id,
      'schema_coverage_incomplete'
    );
    RETURN jsonb_build_object('status', 'schema_coverage_incomplete');
  END IF;

  SELECT *
  INTO v_identity
  FROM auth.identities
  WHERE provider = 'apple'
    AND (
      provider_id = p_apple_sub
      OR identity_data->>'sub' = p_apple_sub
    )
  ORDER BY created_at
  LIMIT 1;

  IF NOT FOUND THEN
    INSERT INTO public.apple_identity_recovery_audit (
      canonical_user_id,
      event_type
    ) VALUES (
      p_canonical_user_id,
      'apple_identity_unclaimed'
    );
    RETURN jsonb_build_object('status', 'unclaimed');
  END IF;

  IF v_identity.user_id = p_canonical_user_id THEN
    INSERT INTO public.apple_identity_recovery_audit (
      canonical_user_id,
      event_type
    ) VALUES (
      p_canonical_user_id,
      'apple_identity_already_linked'
    );
    RETURN jsonb_build_object('status', 'already_linked');
  END IF;

  SELECT *
  INTO v_existing
  FROM public.apple_identity_recovery_requests
  WHERE apple_token_sha256 = p_apple_token_sha256
     OR (
       canonical_user_id = p_canonical_user_id
       AND assessment_idempotency_key = p_idempotency_key
     )
  ORDER BY created_at DESC
  LIMIT 1;

  IF FOUND THEN
    IF v_existing.canonical_user_id <> p_canonical_user_id
       OR v_existing.assessment_idempotency_key <> p_idempotency_key THEN
      RETURN jsonb_build_object('status', 'replayed');
    END IF;

    RETURN jsonb_build_object(
      'status', v_existing.status,
      'recovery_id', v_existing.id,
      'expires_at', v_existing.expires_at,
      'support_reference', v_existing.support_reference,
      'secondary_created_at', (
        SELECT created_at FROM auth.users WHERE id = v_existing.secondary_user_id
      )
    );
  END IF;

  SELECT created_at
  INTO v_secondary_created_at
  FROM auth.users
  WHERE id = v_identity.user_id;

  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = v_identity.user_id) THEN
    v_has_product_data := true;
    v_data_counts := v_data_counts || jsonb_build_object('public.profiles', 1);
  END IF;

  FOR v_dependency IN
    SELECT *
    FROM public.apple_recovery_dependency_registry
    WHERE NOT (
      source_schema = 'public'
      AND source_table IN (
        'profiles',
        'apple_identity_recovery_requests',
        'apple_identity_recovery_audit'
      )
    )
  LOOP
    IF cardinality(v_dependency.source_columns) <> 1 THEN
      v_has_product_data := true;
      v_data_counts := v_data_counts || jsonb_build_object(
        format('%I.%I', v_dependency.source_schema, v_dependency.source_table),
        'unsupported_composite_fk'
      );
      CONTINUE;
    END IF;

    EXECUTE format(
      'SELECT count(*) FROM %I.%I WHERE %I = $1',
      v_dependency.source_schema,
      v_dependency.source_table,
      v_dependency.source_columns[1]
    )
    INTO v_dependency_count
    USING v_identity.user_id;

    IF v_dependency_count > 0 THEN
      v_has_product_data := true;
      v_data_counts := v_data_counts || jsonb_build_object(
        format('%I.%I', v_dependency.source_schema, v_dependency.source_table),
        v_dependency_count
      );
    END IF;
  END LOOP;

  v_recovery_id := gen_random_uuid();
  v_support_reference := 'AR-' || upper(substr(replace(v_recovery_id::text, '-', ''), 1, 8));

  INSERT INTO public.apple_identity_recovery_requests (
    id,
    canonical_user_id,
    secondary_user_id,
    apple_identity_id,
    apple_sub_sha256,
    apple_token_sha256,
    assessment_idempotency_key,
    status,
    eligibility_snapshot,
    support_reference,
    expires_at
  ) VALUES (
    v_recovery_id,
    p_canonical_user_id,
    v_identity.user_id,
    v_identity.id,
    encode(extensions.digest(p_apple_sub, 'sha256'), 'hex'),
    p_apple_token_sha256,
    p_idempotency_key,
    CASE WHEN v_has_product_data THEN 'support_required' ELSE 'eligible' END,
    jsonb_build_object(
      'schema_coverage_complete', true,
      'data_counts', v_data_counts,
      'assessed_at', clock_timestamp()
    ),
    v_support_reference,
    v_expires_at
  );

  INSERT INTO public.apple_identity_recovery_audit (
    recovery_id,
    canonical_user_id,
    event_type,
    event_details
  ) VALUES (
    v_recovery_id,
    p_canonical_user_id,
    CASE WHEN v_has_product_data THEN 'support_required' ELSE 'eligible' END,
    jsonb_build_object(
      'dependency_count',
      (SELECT count(*) FROM jsonb_object_keys(v_data_counts))
    )
  );

  IF v_has_product_data THEN
    RETURN jsonb_build_object(
      'status', 'support_required',
      'support_reference', v_support_reference
    );
  END IF;

  RETURN jsonb_build_object(
    'status', 'eligible',
    'recovery_id', v_recovery_id,
    'expires_at', v_expires_at,
    'secondary_created_at', v_secondary_created_at
  );
END;
$_$;


