COMMENT ON FUNCTION "public"."assign_nearest_beach_to_intel_post"() IS 'Trigger function that automatically assigns the nearest beach to intel posts on INSERT. Only assigns if beach_id is NULL (preserves explicit assignments). Uses SECURITY DEFINER to bypass RLS when reading beaches table.';



CREATE OR REPLACE FUNCTION "public"."assign_signup_experiments"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  PERFORM public.assign_experiment(NEW.id, 't3-quicklog-v1', NEW.created_at);
  PERFORM public.assign_experiment(NEW.id, 't10-freegrowth-v1', NEW.created_at);
  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    -- The exception savepoint rolls back both inserts, so this is both-or-neither.
    -- The deterministic hash makes any gap repairable from auth.users.created_at.
    RAISE WARNING 'assign_signup_experiments failed for %: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;


