CREATE OR REPLACE FUNCTION "public"."backfill_android_waitlist_entries"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_profile record;
  v_lead record;
  v_roster record;
BEGIN
  FOR v_profile IN
    SELECT
      p.id,
      p.android_waitlist_joined_at,
      p.android_waitlist_source,
      p.android_waitlist_surface,
      p.android_waitlist_placement,
      auth_user.email
    FROM public.profiles AS p
    JOIN auth.users AS auth_user ON auth_user.id = p.id
    WHERE p.wants_android_access
      AND p.android_waitlist_joined_at IS NOT NULL
    ORDER BY p.android_waitlist_joined_at, p.id
  LOOP
    PERFORM public.resolve_android_waitlist_entry(
      v_profile.id,
      CASE WHEN NULLIF(btrim(lower(v_profile.email)), '') IS NULL THEN NULL
        ELSE encode(
          extensions.digest(
            convert_to(btrim(lower(v_profile.email)), 'UTF8'),
            'sha256'
          ),
          'hex'
        )
      END,
      NULL,
      'profile_intent',
      v_profile.id,
      COALESCE(NULLIF(v_profile.android_waitlist_source, ''), 'legacy_profile'),
      COALESCE(NULLIF(v_profile.android_waitlist_surface, ''), 'profile'),
      COALESCE(NULLIF(v_profile.android_waitlist_placement, ''), 'unknown'),
      v_profile.android_waitlist_joined_at
    );
  END LOOP;

  FOR v_lead IN
    SELECT
      l.id,
      l.email,
      l.source,
      l.surface,
      l.placement,
      l.created_at
    FROM public.android_beta_leads AS l
    ORDER BY l.created_at, l.id
  LOOP
    PERFORM public.resolve_android_waitlist_entry(
      NULL,
      encode(
        extensions.digest(
          convert_to(btrim(lower(v_lead.email)), 'UTF8'),
          'sha256'
        ),
        'hex'
      ),
      NULL,
      'anonymous_lead',
      v_lead.id,
      v_lead.source,
      v_lead.surface,
      v_lead.placement,
      v_lead.created_at
    );
  END LOOP;

  FOR v_roster IN
    SELECT
      r.id,
      r.user_id,
      r.eligibility_observed_at,
      auth_user.email
    FROM public.android_tester_roster_entries AS r
    LEFT JOIN auth.users AS auth_user ON auth_user.id = r.user_id
    ORDER BY r.eligibility_observed_at, r.id
  LOOP
    PERFORM public.resolve_android_waitlist_entry(
      v_roster.user_id,
      CASE WHEN NULLIF(btrim(lower(v_roster.email)), '') IS NULL THEN NULL
        ELSE encode(
          extensions.digest(
            convert_to(btrim(lower(v_roster.email)), 'UTF8'),
            'sha256'
          ),
          'hex'
        )
      END,
      v_roster.id,
      'roster_evidence',
      v_roster.id,
      'google_directory',
      'android_tester_roster',
      'direct_group_membership',
      v_roster.eligibility_observed_at
    );
  END LOOP;

  RETURN jsonb_build_object(
    'entries', (SELECT count(*) FROM public.android_waitlist_entries),
    'sourceLinks', (
      SELECT count(*) FROM public.android_waitlist_source_links
    ),
    'joinedEvents', (
      SELECT count(*) FROM public.android_waitlist_events
      WHERE event_type = 'android_waitlist_joined'
    )
  );
END;
$$;


ALTER FUNCTION "public"."backfill_android_waitlist_entries"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."backfill_ml_observations"("batch_size" integer DEFAULT 1000) RETURNS TABLE("processed" integer, "matched" integer, "no_match" integer, "elapsed_ms" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  start_time TIMESTAMPTZ := clock_timestamp();
  v_processed INT := 0;
  v_matched INT := 0;
  v_no_match INT := 0;
  cutoff TIMESTAMPTZ := NOW() - INTERVAL '2 hours';
  observation_window_start TIMESTAMPTZ := NOW() - INTERVAL '7 days';
  pred RECORD;
  obs RECORD;
BEGIN
  -- Get pending predictions for observable beaches
  FOR pred IN
    SELECT p.id, p.beach_id, p.predicted_at, p.raw_forecast_m, p.corrected_forecast_m
    FROM ml_predictions_log p
    INNER JOIN observable_beaches o ON p.beach_id = o.beach_id
    WHERE p.observed_m IS NULL
      AND p.predicted_at < cutoff
      AND p.predicted_at > observation_window_start
    ORDER BY p.predicted_at ASC
    LIMIT batch_size
  LOOP
    v_processed := v_processed + 1;
    
    -- Find nearest observation within 1 hour window
    SELECT mf.wave_height_m INTO obs
    FROM marine_forecasts mf
    WHERE mf.beach_id = pred.beach_id
      AND mf.is_observed = true
      AND mf.wave_height_m IS NOT NULL
      AND mf.ts >= pred.predicted_at - INTERVAL '1 hour'
      AND mf.ts <= pred.predicted_at + INTERVAL '1 hour'
    ORDER BY mf.ts ASC
    LIMIT 1;
    
    IF obs.wave_height_m IS NOT NULL THEN
      -- Update prediction with ground truth
      UPDATE ml_predictions_log
      SET 
        observed_m = obs.wave_height_m,
        raw_error_m = ABS(pred.raw_forecast_m - obs.wave_height_m),
        corrected_error_m = ABS(pred.corrected_forecast_m - obs.wave_height_m)
      WHERE id = pred.id;
      
      v_matched := v_matched + 1;
    ELSE
      v_no_match := v_no_match + 1;
    END IF;
  END LOOP;
  
  processed := v_processed;
  matched := v_matched;
  no_match := v_no_match;
  elapsed_ms := EXTRACT(MILLISECONDS FROM clock_timestamp() - start_time)::INT;
  
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."backfill_ml_observations"("batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."backfill_ml_observations"("batch_size" integer) IS 'Backfills ML predictions with ground truth observations. Run via pg_cron every 10 minutes.';



CREATE OR REPLACE FUNCTION "public"."backfill_ml_observations_batch"("batch_size" integer DEFAULT 10000) RETURNS TABLE("processed" integer, "matched" integer, "sentinel_marked" integer, "expired_deleted" integer, "elapsed_ms" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  start_ts TIMESTAMPTZ := clock_timestamp();
  v_matched INT := 0;
  v_sentinel INT := 0;
  v_expired INT := 0;
  cutoff TIMESTAMPTZ := NOW() - INTERVAL '12 hours';
  observation_window_start TIMESTAMPTZ := NOW() - INTERVAL '7 days';
BEGIN
  WITH matchable AS (
    SELECT DISTINCT ON (p.id)
      p.id,
      uwo.wave_height_m AS obs_height
    FROM ml_predictions_log p
    INNER JOIN observable_beaches ob ON ob.beach_id = p.beach_id
    INNER JOIN unified_wave_observations uwo
      ON uwo.nearest_beach_id = p.beach_id
      AND uwo.wave_height_m IS NOT NULL
      AND uwo.observed_at >= p.predicted_at - INTERVAL '12 hours'
      AND uwo.observed_at <= p.predicted_at + INTERVAL '12 hours'
    WHERE p.observed_m IS NULL
      AND p.predicted_at < cutoff
      AND p.predicted_at > observation_window_start
    ORDER BY p.id, ABS(EXTRACT(EPOCH FROM (uwo.observed_at - p.predicted_at)))
    LIMIT batch_size
  ),
  updated AS (
    UPDATE ml_predictions_log p
    SET
      observed_m = m.obs_height,
      raw_error_m = ABS(p.raw_forecast_m - m.obs_height),
      corrected_error_m = ABS(p.corrected_forecast_m - m.obs_height)
    FROM matchable m
    WHERE p.id = m.id
    RETURNING p.id
  )
  SELECT COUNT(*)::INT INTO v_matched FROM updated;

  WITH sentinel AS (
    UPDATE ml_predictions_log
    SET observed_m = -1
    WHERE observed_m IS NULL
      AND predicted_at < NOW() - INTERVAL '24 hours'
    RETURNING id
  )
  SELECT COUNT(*)::INT INTO v_sentinel FROM sentinel;

  WITH expired AS (
    DELETE FROM ml_predictions_log
    WHERE observed_m IS NULL
      AND predicted_at < NOW() - INTERVAL '72 hours'
    RETURNING id
  )
  SELECT COUNT(*)::INT INTO v_expired FROM expired;

  RETURN QUERY SELECT
    v_matched + v_sentinel + v_expired,
    v_matched,
    v_sentinel,
    v_expired,
    ROUND(EXTRACT(EPOCH FROM (clock_timestamp() - start_ts)) * 1000, 2);
END;
$$;


ALTER FUNCTION "public"."backfill_ml_observations_batch"("batch_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."backfill_ml_observations_batch"("batch_size" integer) IS 'JOIN-based ML ground truth matcher with expanded ±4h window.
   Step 1: Match predictions with observations via ±4h window (was ±2h).
   Step 2: Mark predictions >24h old as unmatchable (sentinel -1).
   Step 3: DELETE pending predictions >72h old (TTL cleanup).
   Returns: (processed, matched, sentinel_marked, expired_deleted, elapsed_ms).
   Updated Feb 2 2026: expanded matching window 2h→4h for better match rate.';



CREATE OR REPLACE FUNCTION "public"."begin_email_lifecycle"("p_attempt_id" "uuid", "p_payload" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE a public.email_contact_attempts%ROWTYPE; d jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(739301);
  SELECT * INTO a FROM public.email_contact_attempts WHERE id=p_attempt_id FOR UPDATE;
  IF a.state IS DISTINCT FROM 'reserved' THEN RETURN false; END IF;
  d:=public.evaluate_email_lifecycle(a.user_id,a.id);
  IF NOT EXISTS(SELECT 1 FROM public.email_contact_controls WHERE singleton AND enabled AND lifecycle_enabled)
    OR d->>'status' IS DISTINCT FROM 'due' OR d->>'job' IS DISTINCT FROM a.lifecycle_job OR d->>'episode' IS DISTINCT FROM a.episode
    OR d->>'campaign_id' IS DISTINCT FROM a.campaign_id OR (d->>'campaign_version')::integer IS DISTINCT FROM a.campaign_version
    OR d->>'content_hash' IS DISTINCT FROM a.content_hash OR md5((d->'source')::text) IS DISTINCT FROM a.source_hash
    OR a.claimed_at<now()-interval '5 minutes' THEN
    UPDATE public.email_contact_attempts SET state='cancelled',error_code='eligibility_changed' WHERE id=a.id;
    RETURN false;
  END IF;
  IF p_payload->>'to' IS DISTINCT FROM d->'source'->>'email' OR nullif(p_payload->>'subject','') IS NULL
    OR nullif(p_payload->>'html','') IS NULL OR nullif(p_payload->>'text','') IS NULL THEN RAISE EXCEPTION 'Invalid lifecycle payload'; END IF;
  UPDATE public.email_contact_attempts SET state='handoff_started',handoff_at=now(),payload=p_payload,payload_hash=encode(sha256(convert_to(p_payload::text,'UTF8')),'hex') WHERE id=a.id;
  RETURN true;
END; $$;


ALTER FUNCTION "public"."begin_email_lifecycle"("p_attempt_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_pro_offer"("p_award_id" "uuid", "p_reservation_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(739302);
 UPDATE public.pro_offer_awards a SET state='handoff_started',handoff_at=now() WHERE a.id=p_award_id AND a.reservation_id=p_reservation_id
 AND a.state='reserved' AND a.reserved_at>now()-interval '2 minutes'
 AND EXISTS(SELECT 1 FROM public.pro_offer_programs p WHERE p.id=a.program_id AND p.enabled)
 AND NOT EXISTS(SELECT 1 FROM public.user_entitlements e WHERE e.user_id=a.user_id AND (e.is_pro OR e.is_trialing) AND (e.expires_at IS NULL OR e.expires_at>now()));
 RETURN FOUND;
END; $$;


