CREATE OR REPLACE FUNCTION "public"."cleanup_session_media_storage"("media_id" "uuid") RETURNS TABLE("success" boolean, "message" "text", "storage_path" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  media_record RECORD;
  v_is_admin BOOLEAN;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.is_admin = true
  )
  INTO v_is_admin;

  SELECT sm.*, (sm.user_id = auth.uid() OR v_is_admin) AS can_delete
  INTO media_record
  FROM public.session_media sm
  WHERE sm.id = cleanup_session_media_storage.media_id;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'Media not found'::TEXT, NULL::TEXT;
    RETURN;
  END IF;

  IF NOT media_record.can_delete THEN
    RETURN QUERY SELECT false, 'Unauthorized to delete this media'::TEXT, NULL::TEXT;
    RETURN;
  END IF;

  UPDATE public.session_media sm
  SET deleted_at = NOW()
  WHERE sm.id = media_record.id
    AND sm.deleted_at IS NULL;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, 'Media already deleted'::TEXT, media_record.storage_path;
    RETURN;
  END IF;

  RETURN QUERY SELECT
    true,
    ('Media record soft-deleted. Storage cleanup required: ' || media_record.storage_path)::TEXT,
    media_record.storage_path;
END;
$$;


ALTER FUNCTION "public"."cleanup_session_media_storage"("media_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_session_media_storage"("media_id" "uuid") IS 'Soft deletes session media and returns storage path for cleanup. Caller must remove file from storage bucket separately.';



