CREATE OR REPLACE FUNCTION "public"."detect_apple_orphan_after_sign_in"("p_current_user_id" "uuid", "p_apple_sub" "text", "p_native_install_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
  v_current_created_at timestamptz;
  v_current_name text;
  v_candidate_user_id uuid;
  v_candidate_count integer;
  v_pair_key text;
BEGIN
  IF p_current_user_id IS NULL
     OR length(p_apple_sub) = 0
     OR p_native_install_id IS NULL
     OR length(p_idempotency_key) < 8
     OR length(p_idempotency_key) > 128 THEN
    RAISE EXCEPTION 'invalid apple orphan detection input';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_constraint current_constraint
    JOIN pg_class source_table ON source_table.oid = current_constraint.conrelid
    JOIN pg_namespace source_ns ON source_ns.oid = source_table.relnamespace
    JOIN pg_class target_table ON target_table.oid = current_constraint.confrelid
    JOIN pg_namespace target_ns ON target_ns.oid = target_table.relnamespace
    WHERE current_constraint.contype = 'f'
      AND source_ns.nspname = 'public'
      AND current_constraint.confrelid IN (
        'auth.users'::regclass,
        'public.profiles'::regclass
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.apple_recovery_dependency_registry registry
        WHERE registry.source_schema = source_ns.nspname
          AND registry.source_table = source_table.relname
          AND registry.constraint_name = current_constraint.conname
          AND registry.target_schema = target_ns.nspname
          AND registry.target_table = target_table.relname
      )
  ) THEN
    RETURN jsonb_build_object('status', 'schema_coverage_incomplete');
  END IF;

  SELECT
    signed_in_user.created_at,
    lower(
      regexp_replace(
        trim(
          coalesce(
            nullif(current_profile.full_name, ''),
            nullif(current_profile.display_name, ''),
            nullif(signed_in_user.raw_user_meta_data->>'full_name', ''),
            nullif(signed_in_user.raw_user_meta_data->>'name', ''),
            nullif(
              concat_ws(
                ' ',
                signed_in_user.raw_user_meta_data->>'given_name',
                signed_in_user.raw_user_meta_data->>'family_name'
              ),
              ''
            )
          )
        ),
        '[^[:alnum:]]+',
        '',
        'g'
      )
    )
  INTO v_current_created_at, v_current_name
  FROM auth.users signed_in_user
  LEFT JOIN public.profiles current_profile
    ON current_profile.id = signed_in_user.id
   AND current_profile.deleted_at IS NULL
  WHERE signed_in_user.id = p_current_user_id
    AND signed_in_user.deleted_at IS NULL;

  IF NOT FOUND
     OR v_current_name IS NULL
     OR v_current_name = ''
     OR v_current_created_at < clock_timestamp() - interval '15 minutes'
     OR v_current_created_at > clock_timestamp() + interval '30 seconds' THEN
    RETURN jsonb_build_object('status', 'no_match');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM auth.identities identity_row
    WHERE identity_row.user_id = p_current_user_id
      AND identity_row.provider = 'apple'
      AND (
        identity_row.provider_id = p_apple_sub
        OR identity_row.identity_data->>'sub' = p_apple_sub
      )
  ) THEN
    RETURN jsonb_build_object('status', 'no_match');
  END IF;

  WITH candidate_users AS MATERIALIZED (
    SELECT DISTINCT event_row.user_id
    FROM public.user_events event_row
    WHERE event_row.user_id IS NOT NULL
      AND event_row.user_id <> p_current_user_id
      AND event_row.metadata->>'native_install_id' = p_native_install_id::text
  ),
  named_candidates AS (
    SELECT candidate_user.id
    FROM candidate_users candidate
    JOIN auth.users candidate_user ON candidate_user.id = candidate.user_id
    LEFT JOIN public.profiles candidate_profile
      ON candidate_profile.id = candidate_user.id
     AND candidate_profile.deleted_at IS NULL
    WHERE candidate_user.deleted_at IS NULL
      AND candidate_user.created_at < v_current_created_at
      AND lower(
        regexp_replace(
          trim(
            coalesce(
              nullif(candidate_profile.full_name, ''),
              nullif(candidate_profile.display_name, ''),
              nullif(candidate_user.raw_user_meta_data->>'full_name', ''),
              nullif(candidate_user.raw_user_meta_data->>'name', ''),
              nullif(
                concat_ws(
                  ' ',
                  candidate_user.raw_user_meta_data->>'given_name',
                  candidate_user.raw_user_meta_data->>'family_name'
                ),
                ''
              )
            )
          ),
          '[^[:alnum:]]+',
          '',
          'g'
        )
      ) = v_current_name
  )
  SELECT count(*), (array_agg(id ORDER BY id))[1]
  INTO v_candidate_count, v_candidate_user_id
  FROM named_candidates;

  IF v_candidate_count <> 1 OR v_candidate_user_id IS NULL THEN
    RETURN jsonb_build_object('status', 'no_match');
  END IF;

  v_pair_key := v_candidate_user_id::text || ':' || p_current_user_id::text;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_pair_key, 0));

  IF EXISTS (
    SELECT 1
    FROM public.apple_identity_recovery_audit audit_row
    WHERE audit_row.canonical_user_id = v_candidate_user_id
      AND audit_row.event_type = 'post_sign_in_orphan_flagged'
      AND audit_row.event_details->>'secondary_user_id' = p_current_user_id::text
  ) THEN
    RETURN jsonb_build_object('status', 'flagged');
  END IF;

  INSERT INTO public.apple_identity_recovery_audit (
    canonical_user_id,
    event_type,
    event_details
  ) VALUES (
    v_candidate_user_id,
    'post_sign_in_orphan_flagged',
    jsonb_build_object(
      'secondary_user_id', p_current_user_id,
      'evidence', jsonb_build_array('native_install_id', 'normalized_name'),
      'idempotency_key_sha256',
        encode(extensions.digest(p_idempotency_key, 'sha256'), 'hex')
    )
  );

  INSERT INTO public.user_events (
    user_id,
    event_type,
    metadata
  ) VALUES (
    p_current_user_id,
    'apple_orphan_recovery_flagged',
    jsonb_build_object(
      'detection_surface', 'apple_sign_in',
      'evidence', jsonb_build_array('native_install_id', 'normalized_name'),
      'probable_canonical_user_id', v_candidate_user_id,
      'event_id', 'apple-orphan:' || v_pair_key
    )
  );

  RETURN jsonb_build_object('status', 'flagged');
END;
$$;


ALTER FUNCTION "public"."detect_apple_orphan_after_sign_in"("p_current_user_id" "uuid", "p_apple_sub" "text", "p_native_install_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."detect_apple_orphan_after_sign_in"("p_current_user_id" "uuid", "p_apple_sub" "text", "p_native_install_id" "uuid", "p_idempotency_key" "text") IS 'Service-only post-sign-in detector. Flags one older same-install, exact-name account pair without blocking authentication or mutating auth identities.';



CREATE OR REPLACE FUNCTION "public"."detect_apple_orphan_before_sign_in"("p_apple_sub" "text", "p_native_install_id" "uuid", "p_full_name" "text", "p_token_issued_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'pg_catalog'
    AS $$
DECLARE
  v_normalized_name text;
  v_candidate_user_id uuid;
  v_candidate_count integer;
  v_apple_sub_sha256 text;
  v_audit_key text;
BEGIN
  IF p_apple_sub IS NULL
     OR length(p_apple_sub) = 0
     OR p_native_install_id IS NULL
     OR p_token_issued_at IS NULL
     OR p_token_issued_at < clock_timestamp() - interval '5 minutes'
     OR p_token_issued_at > clock_timestamp() + interval '30 seconds' THEN
    RAISE EXCEPTION 'invalid apple orphan precheck input';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_constraint current_constraint
    JOIN pg_class source_table ON source_table.oid = current_constraint.conrelid
    JOIN pg_namespace source_ns ON source_ns.oid = source_table.relnamespace
    JOIN pg_class target_table ON target_table.oid = current_constraint.confrelid
    JOIN pg_namespace target_ns ON target_ns.oid = target_table.relnamespace
    WHERE current_constraint.contype = 'f'
      AND source_ns.nspname = 'public'
      AND current_constraint.confrelid IN (
        'auth.users'::regclass,
        'public.profiles'::regclass
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.apple_recovery_dependency_registry registry
        WHERE registry.source_schema = source_ns.nspname
          AND registry.source_table = source_table.relname
          AND registry.constraint_name = current_constraint.conname
          AND registry.target_schema = target_ns.nspname
          AND registry.target_table = target_table.relname
      )
  ) THEN
    RETURN jsonb_build_object('status', 'schema_coverage_incomplete');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM auth.identities identity_row
    JOIN auth.users identity_user ON identity_user.id = identity_row.user_id
    WHERE identity_row.provider = 'apple'
      AND identity_user.deleted_at IS NULL
      AND (
        identity_row.provider_id = p_apple_sub
        OR identity_row.identity_data->>'sub' = p_apple_sub
      )
  ) THEN
    RETURN jsonb_build_object('status', 'apple_sub_claimed');
  END IF;

  v_normalized_name := lower(
    regexp_replace(trim(coalesce(p_full_name, '')), '[^[:alnum:]]+', '', 'g')
  );
  IF v_normalized_name = '' THEN
    RETURN jsonb_build_object('status', 'unclaimed_no_match');
  END IF;

  WITH candidate_users AS MATERIALIZED (
    SELECT DISTINCT event_row.user_id
    FROM public.user_events event_row
    WHERE event_row.user_id IS NOT NULL
      AND event_row.metadata->>'native_install_id' = p_native_install_id::text
  ),
  named_candidates AS (
    SELECT candidate_user.id
    FROM candidate_users candidate
    JOIN auth.users candidate_user ON candidate_user.id = candidate.user_id
    LEFT JOIN public.profiles candidate_profile
      ON candidate_profile.id = candidate_user.id
     AND candidate_profile.deleted_at IS NULL
    WHERE candidate_user.deleted_at IS NULL
      AND candidate_user.created_at < p_token_issued_at
      AND lower(
        regexp_replace(
          trim(
            coalesce(
              nullif(candidate_profile.full_name, ''),
              nullif(candidate_profile.display_name, ''),
              nullif(candidate_user.raw_user_meta_data->>'full_name', ''),
              nullif(candidate_user.raw_user_meta_data->>'name', ''),
              nullif(
                concat_ws(
                  ' ',
                  candidate_user.raw_user_meta_data->>'given_name',
                  candidate_user.raw_user_meta_data->>'family_name'
                ),
                ''
              )
            )
          ),
          '[^[:alnum:]]+',
          '',
          'g'
        )
      ) = v_normalized_name
  )
  SELECT count(*), (array_agg(id ORDER BY id))[1]
  INTO v_candidate_count, v_candidate_user_id
  FROM named_candidates;

  IF v_candidate_count <> 1 OR v_candidate_user_id IS NULL THEN
    RETURN jsonb_build_object('status', 'unclaimed_no_match');
  END IF;

  v_apple_sub_sha256 := encode(
    extensions.digest(p_apple_sub, 'sha256'),
    'hex'
  );
  v_audit_key := v_candidate_user_id::text || ':' || v_apple_sub_sha256;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_audit_key, 0));

  IF NOT EXISTS (
    SELECT 1
    FROM public.apple_identity_recovery_audit audit_row
    WHERE audit_row.canonical_user_id = v_candidate_user_id
      AND audit_row.event_type = 'pre_sign_in_orphan_prevented'
      AND audit_row.event_details->>'apple_sub_sha256' = v_apple_sub_sha256
  ) THEN
    INSERT INTO public.apple_identity_recovery_audit (
      canonical_user_id,
      event_type,
      event_details
    ) VALUES (
      v_candidate_user_id,
      'pre_sign_in_orphan_prevented',
      jsonb_build_object(
        'apple_sub_sha256', v_apple_sub_sha256,
        'evidence', jsonb_build_array('native_install_id', 'normalized_name')
      )
    );
  END IF;

  RETURN jsonb_build_object('status', 'prevent');
END;
$$;


ALTER FUNCTION "public"."detect_apple_orphan_before_sign_in"("p_apple_sub" "text", "p_native_install_id" "uuid", "p_full_name" "text", "p_token_issued_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."detect_apple_orphan_before_sign_in"("p_apple_sub" "text", "p_native_install_id" "uuid", "p_full_name" "text", "p_token_issued_at" timestamp with time zone) IS 'Service-only pre-sign-in detector. A stable native install ID is expected to survive app updates and relaunches but may reset on uninstall/reinstall, which weakens prevention to the post-sign-in backstop.';



CREATE OR REPLACE FUNCTION "public"."dev_log_session_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_pid_info record;
BEGIN
  v_user_id := COALESCE(NEW.user_id, OLD.user_id);
  IF v_user_id <> '73040cff-afe9-4fa0-a874-2016203fc015'::uuid THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT application_name, client_addr, query
    INTO v_pid_info
    FROM pg_stat_activity
   WHERE pid = pg_backend_pid();

  INSERT INTO public.dev_session_mutation_audit
    (op, user_id, session_id, old_row, new_row,
     application_name, client_addr, current_user_role, session_user_role,
     current_query)
  VALUES
    (TG_OP, v_user_id, COALESCE(NEW.id, OLD.id),
     to_jsonb(OLD), to_jsonb(NEW),
     v_pid_info.application_name, v_pid_info.client_addr,
     current_user::name, session_user::name,
     v_pid_info.query);

  RETURN COALESCE(NEW, OLD);
END
$$;


ALTER FUNCTION "public"."dev_log_session_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."earn_five_session_offer"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE ids uuid[];
BEGIN
 -- ponytail: pilot-wide serialization prevents enrollment/completion races; shard by user when throughput warrants it.
 PERFORM pg_advisory_xact_lock(739302);
 IF NOT EXISTS(SELECT 1 FROM public.pro_offer_awards WHERE user_id=p_user_id AND program_id='five_sessions_month' AND earned_at IS NULL) THEN RETURN; END IF;
 SELECT array_agg(id) INTO ids FROM (SELECT id FROM public.sessions s WHERE user_id=p_user_id AND status='completed' AND deleted_at IS NULL AND NOT public.is_historical_file_import(s.source, s.arrival_time, s.duration_minutes, s.created_at) ORDER BY id LIMIT 5) completed;
 IF cardinality(ids)=5 THEN
  UPDATE public.pro_offer_awards SET earned_at=now(),session_ids=ids WHERE user_id=p_user_id AND program_id='five_sessions_month' AND earned_at IS NULL;
 END IF;
END; $$;


ALTER FUNCTION "public"."earn_five_session_offer"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."earn_pro_offer_on_session"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
 IF NEW.status='completed' AND NEW.deleted_at IS NULL
 AND NOT public.is_historical_file_import(NEW.source, NEW.arrival_time, NEW.duration_minutes) THEN PERFORM public.earn_five_session_offer(NEW.user_id); END IF;
 RETURN NEW;
END; $$;


