 IF OLD.approved_at IS NOT NULL AND (to_jsonb(NEW)-'enabled') IS DISTINCT FROM (to_jsonb(OLD)-'enabled') THEN
  RAISE EXCEPTION 'Approved offer terms and budget are frozen';
 END IF;
 RETURN NEW;
END; $$;


