Used for Next.js static generation of location pages and sitemaps.';



CREATE OR REPLACE FUNCTION "public"."get_android_tester_roster_join_context"("p_user_id" "uuid", "p_idempotency_key_hash" "text") RETURNS TABLE("snapshot_complete" boolean, "already_linked" boolean, "candidates" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_snapshot_complete boolean := false;
  v_already_linked boolean := false;
  v_linked_entry_id uuid;
  v_candidates jsonb := '[]'::jsonb;
BEGIN
  IF p_idempotency_key_hash !~ '^[a-f0-9]{64}$' THEN
    RETURN;
  END IF;

  SELECT run.complete
  INTO v_snapshot_complete
  FROM public.android_tester_roster_sync_runs AS run
  ORDER BY run.observed_at DESC, run.created_at DESC
  LIMIT 1;

  SELECT join_evidence.entry_id
  INTO v_linked_entry_id
  FROM public.android_tester_roster_join_evidence AS join_evidence
  WHERE join_evidence.user_id = p_user_id
    AND join_evidence.idempotency_key_hash = p_idempotency_key_hash
  LIMIT 1;

  v_already_linked := v_linked_entry_id IS NOT NULL;
  IF v_already_linked THEN
    INSERT INTO public.android_tester_roster_audit (
      actor_user_id,
      entry_id,
      action,
      outcome
    ) VALUES (
      NULL,
      v_linked_entry_id,
      'join',
      'same_key_retry'
    );
  END IF;

  IF COALESCE(v_snapshot_complete, false) AND NOT v_already_linked THEN
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'entry_id', entry.id,
          'key_version', identity.key_version,
          'iv', identity.iv,
          'ciphertext', identity.ciphertext,
          'auth_tag', identity.auth_tag
        )
        ORDER BY entry.created_at
      ),
      '[]'::jsonb
    )
    INTO v_candidates
    FROM public.android_tester_roster_entries AS entry
    JOIN public.android_tester_roster_identities AS identity
      ON identity.entry_id = entry.id
    WHERE entry.eligibility_status = 'eligible'
      AND entry.group_membership_status = 'active'
      AND entry.user_id IS NULL;
  END IF;

  RETURN QUERY SELECT
    COALESCE(v_snapshot_complete, false),
    v_already_linked,
    v_candidates;
END;
$_$;


ALTER FUNCTION "public"."get_android_tester_roster_join_context"("p_user_id" "uuid", "p_idempotency_key_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_android_tester_roster_summary"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH latest_stage AS (
    SELECT DISTINCT ON (entry_id, stage)
      entry_id,
      stage,
      status
    FROM public.android_tester_roster_stages
    ORDER BY entry_id, stage, observed_at DESC, id DESC
  )
  SELECT jsonb_build_object(
    'eligible', (
      SELECT count(*)
      FROM public.android_tester_roster_entries
      WHERE eligibility_status = 'eligible'
    ),
    'ineligible', (
      SELECT count(*)
      FROM public.android_tester_roster_entries
      WHERE eligibility_status = 'ineligible'
    ),
    'linkedAccounts', (
      SELECT count(*)
      FROM public.android_tester_roster_entries
      WHERE user_id IS NOT NULL
    ),
    'unjoinedIdentities', (
      SELECT count(*)
      FROM public.android_tester_roster_entries AS entry
      WHERE entry.user_id IS NULL
        AND EXISTS (
          SELECT 1
          FROM public.android_tester_roster_identities AS identity
          WHERE identity.entry_id = entry.id
        )
    ),
    'purgeScheduled', (
      SELECT count(*)
      FROM public.android_tester_roster_entries
      WHERE purge_after IS NOT NULL
    ),
    'stageCounts', jsonb_build_object(
      'group_eligibility', jsonb_build_object(
        'eligible', count(*) FILTER (
          WHERE stage = 'group_eligibility' AND status = 'eligible'
        ),
        'ineligible', count(*) FILTER (
          WHERE stage = 'group_eligibility' AND status = 'ineligible'
        ),
        'unknown', count(*) FILTER (
          WHERE stage = 'group_eligibility' AND status = 'unknown'
        )
      ),
      'play_opt_in', jsonb_build_object(
        'observed', count(*) FILTER (
          WHERE stage = 'play_opt_in' AND status = 'observed'
        ),
        'notObserved', count(*) FILTER (
          WHERE stage = 'play_opt_in' AND status = 'not_observed'
        ),
        'unknown', count(*) FILTER (
          WHERE stage = 'play_opt_in' AND status = 'unknown'
        )
      ),
      'install', jsonb_build_object(
        'observed', count(*) FILTER (
          WHERE stage = 'install' AND status = 'observed'
        ),
        'unknown', count(*) FILTER (
          WHERE stage = 'install' AND status = 'unknown'
        )
      ),
      'first_open', jsonb_build_object(
        'observed', count(*) FILTER (
          WHERE stage = 'first_open' AND status = 'observed'
        ),
        'unknown', count(*) FILTER (
          WHERE stage = 'first_open' AND status = 'unknown'
        )
      ),
      'account_join', jsonb_build_object(
        'linked', count(*) FILTER (
          WHERE stage = 'account_join' AND status = 'linked'
        ),
        'unknown', count(*) FILTER (
          WHERE stage = 'account_join' AND status = 'unknown'
        )
      )
    )
  )
  FROM latest_stage;
$$;


ALTER FUNCTION "public"."get_android_tester_roster_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_android_tester_roster_sync_identities"() RETURNS TABLE("entry_id" "uuid", "user_id" "uuid", "eligibility_status" "text", "purge_after" timestamp with time zone, "key_version" integer, "iv" "text", "ciphertext" "text", "auth_tag" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT
    entry.id,
    entry.user_id,
    entry.eligibility_status,
    entry.purge_after,
    identity.key_version,
    identity.iv,
    identity.ciphertext,
    identity.auth_tag
  FROM public.android_tester_roster_entries AS entry
  LEFT JOIN public.android_tester_roster_identities AS identity
    ON identity.entry_id = entry.id
  WHERE entry.user_id IS NOT NULL
    OR identity.entry_id IS NOT NULL
  ORDER BY entry.created_at;
$$;


ALTER FUNCTION "public"."get_android_tester_roster_sync_identities"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_android_waitlist_operator_projection"() RETURNS TABLE("entry_id" "uuid", "first_joined_at" timestamp with time zone, "last_joined_at" timestamp with time zone, "authenticated_account_linked" boolean, "source_kinds" "text"[], "source_count" bigint, "group_membership_status" "text", "group_membership_observed_at" timestamp with time zone, "play_opt_in_status" "text", "play_opt_in_observed_at" timestamp with time zone, "install_status" "text", "install_observed_at" timestamp with time zone, "first_open_status" "text", "first_open_observed_at" timestamp with time zone, "account_join_status" "text", "account_join_observed_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  WITH source_rollup AS (
    SELECT
      link.entry_id,
      array_agg(DISTINCT link.source_kind ORDER BY link.source_kind)
        AS source_kinds,
      count(*) AS source_count
    FROM public.android_waitlist_source_links AS link
    GROUP BY link.entry_id
  ),
  latest_stage AS (
    SELECT DISTINCT ON (link.entry_id, stage.stage)
      link.entry_id,
      stage.stage,
      stage.status,
      stage.observed_at
    FROM public.android_waitlist_source_links AS link
    JOIN public.android_tester_roster_stages AS stage
      ON stage.entry_id = link.roster_entry_id
    WHERE link.source_kind = 'roster_evidence'
      AND stage.stage IN (
        'group_eligibility',
        'play_opt_in',
        'install',
        'first_open',
        'account_join'
      )
    ORDER BY
      link.entry_id,
      stage.stage,
      stage.observed_at DESC,
      stage.id DESC
  )
  SELECT
    entry.id,
    entry.first_joined_at,
    entry.last_joined_at,
    entry.user_id IS NOT NULL,
    source.source_kinds,
    source.source_count,
    max(stage.status) FILTER (
      WHERE stage.stage = 'group_eligibility'
    ),
    max(stage.observed_at) FILTER (
      WHERE stage.stage = 'group_eligibility'
    ),
    max(stage.status) FILTER (WHERE stage.stage = 'play_opt_in'),
    max(stage.observed_at) FILTER (WHERE stage.stage = 'play_opt_in'),
    max(stage.status) FILTER (WHERE stage.stage = 'install'),
    max(stage.observed_at) FILTER (WHERE stage.stage = 'install'),
    max(stage.status) FILTER (WHERE stage.stage = 'first_open'),
    max(stage.observed_at) FILTER (WHERE stage.stage = 'first_open'),
    max(stage.status) FILTER (WHERE stage.stage = 'account_join'),
    max(stage.observed_at) FILTER (WHERE stage.stage = 'account_join')
  FROM public.android_waitlist_entries AS entry
  JOIN source_rollup AS source ON source.entry_id = entry.id
  LEFT JOIN latest_stage AS stage ON stage.entry_id = entry.id
  GROUP BY
    entry.id,
    entry.first_joined_at,
    entry.last_joined_at,
    entry.user_id,
    source.source_kinds,
    source.source_count
  ORDER BY entry.first_joined_at, entry.id;
$$;


ALTER FUNCTION "public"."get_android_waitlist_operator_projection"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_android_waitlist_operator_projection"() IS 'Deduplicated non-PII operator projection preserving independent Group, Play, install, first-open, and account-join evidence.';



