CREATE OR REPLACE FUNCTION "public"."get_beaches_near"("_lat" double precision, "_lon" double precision, "_radius_km" double precision DEFAULT 25) RETURNS TABLE("id" "uuid", "name" "text", "lat" double precision, "lon" double precision, "break_type" "text", "aspect_deg" integer, "wind_offshore_deg" integer, "swell_window_center_deg" integer, "swell_window_halfwidth_deg" integer, "preferred_tide_ft_min" numeric, "preferred_tide_ft_max" numeric, "wind_cross_shore_ok_kt" integer, "wind_onshore_bad_kt" integer, "dist_km" double precision)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  WITH base AS (
    SELECT
      b.id,
      b.name,
      b.lat,  -- FIXED: was b.latitude AS lat
      b.lon,  -- FIXED: was b.longitude AS lon
      b.break_type,
      b.aspect_deg,
      b.wind_offshore_deg,  -- FIXED: was offshore_deg
      b.swell_window_center_deg,
      b.swell_window_halfwidth_deg,
      b.preferred_tide_ft_min,  -- FIXED: was tide_min_ft
      b.preferred_tide_ft_max,  -- FIXED: was tide_max_ft
      b.wind_cross_shore_ok_kt,  -- FIXED: was wind_cross_ok_kts
      b.wind_onshore_bad_kt,  -- FIXED: was wind_onshore_bad_kts
      -- Haversine (spherical law of cosines) with clamped argument
      6371 * acos(
        LEAST(1.0, GREATEST(-1.0,
          cos(radians(_lat)) * cos(radians(b.lat)) * cos(radians(b.lon) - radians(_lon))  -- FIXED: was b.latitude and b.longitude
          + sin(radians(_lat)) * sin(radians(b.lat))  -- FIXED: was b.latitude
        ))
      ) AS dist_km
    FROM public.beaches b
    WHERE b.lat IS NOT NULL AND b.lon IS NOT NULL  -- FIXED: was b.latitude and b.longitude
  )
  SELECT *
  FROM base
  WHERE dist_km <= _radius_km
  ORDER BY dist_km
  LIMIT 12;
$$;


ALTER FUNCTION "public"."get_beaches_near"("_lat" double precision, "_lon" double precision, "_radius_km" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_best_times"("p_beach" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_limit" integer DEFAULT 6) RETURNS TABLE("start_ts" timestamp with time zone, "end_ts" timestamp with time zone, "label" "text", "score" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
WITH params AS (
  SELECT 
    b.id AS beach_id,
    b.wind_offshore_deg,
    b.wind_cross_shore_ok_kt,
    b.preferred_tide_ft_min,
    b.preferred_tide_ft_max,
    ((b.swell_window_max_deg - b.swell_window_min_deg + 360) % 360) AS swell_span,
    b.swell_window_min_deg AS swell_min
  FROM public.beaches b
  WHERE b.id = p_beach
),
hrs AS (
  SELECT generate_series(
           date_trunc('hour', p_start),
           date_trunc('hour', p_end),
           interval '1 hour'
         ) AS ts_utc
),
nearest AS (
  SELECT
    h.ts_utc,
    -- nearest marine within ±6 hours
    (
      SELECT m.ts FROM public.marine_forecasts m
      WHERE m.beach_id = p_beach
        AND m.ts BETWEEN h.ts_utc - interval '6 hours' AND h.ts_utc + interval '6 hours'
      ORDER BY ABS(EXTRACT(EPOCH FROM (m.ts - h.ts_utc)))
      LIMIT 1
    ) AS m_ts,
    (
      SELECT m.wave_height_m FROM public.marine_forecasts m
      WHERE m.beach_id = p_beach
        AND m.ts BETWEEN h.ts_utc - interval '6 hours' AND h.ts_utc + interval '6 hours'
      ORDER BY ABS(EXTRACT(EPOCH FROM (m.ts - h.ts_utc)))
      LIMIT 1
    ) AS wave_height_m,
    (
      SELECT m.wave_period_s FROM public.marine_forecasts m
      WHERE m.beach_id = p_beach
        AND m.ts BETWEEN h.ts_utc - interval '6 hours' AND h.ts_utc + interval '6 hours'
      ORDER BY ABS(EXTRACT(EPOCH FROM (m.ts - h.ts_utc)))
      LIMIT 1
    ) AS wave_period_s,
    (
      SELECT m.wave_direction_deg FROM public.marine_forecasts m
      WHERE m.beach_id = p_beach
        AND m.ts BETWEEN h.ts_utc - interval '6 hours' AND h.ts_utc + interval '6 hours'
      ORDER BY ABS(EXTRACT(EPOCH FROM (m.ts - h.ts_utc)))
      LIMIT 1
    ) AS wave_direction_deg,
    (
      SELECT m.wind_speed_ms FROM public.marine_forecasts m
      WHERE m.beach_id = p_beach
        AND m.ts BETWEEN h.ts_utc - interval '6 hours' AND h.ts_utc + interval '6 hours'
      ORDER BY ABS(EXTRACT(EPOCH FROM (m.ts - h.ts_utc)))
      LIMIT 1
    ) AS wind_speed_ms,
    (
      SELECT m.wind_direction_deg FROM public.marine_forecasts m
      WHERE m.beach_id = p_beach
        AND m.ts BETWEEN h.ts_utc - interval '6 hours' AND h.ts_utc + interval '6 hours'
      ORDER BY ABS(EXTRACT(EPOCH FROM (m.ts - h.ts_utc)))
      LIMIT 1
    ) AS wind_direction_deg,
    -- nearest tide within ±90 minutes
    (
      SELECT t.tide_height_m FROM public.tide_forecasts t
      WHERE t.beach_id = p_beach
        AND t.ts BETWEEN h.ts_utc - interval '90 minutes' AND h.ts_utc + interval '90 minutes'
      ORDER BY ABS(EXTRACT(EPOCH FROM (t.ts - h.ts_utc)))
      LIMIT 1
    ) AS tide_height_m
  FROM hrs h
),
scored AS (
  SELECT
    n.ts_utc,
    -- Wind score
    GREATEST(
      0,
      (1 + COS(RADIANS(ABS(MOD(((n.wind_direction_deg)::int - p.wind_offshore_deg + 540),360) - 180))))/2
      * (1 - GREATEST(0, ((COALESCE(n.wind_speed_ms,0) * 1.94384449) - p.wind_cross_shore_ok_kt)::float / 10.0))
    ) AS wind_score,
    -- Tide score (ft band triangle)
    COALESCE(
      GREATEST(
        0,
        1 - ABS(((n.tide_height_m * 3.28084)) - ((p.preferred_tide_ft_min + p.preferred_tide_ft_max)/2.0))
              / NULLIF((p.preferred_tide_ft_max - p.preferred_tide_ft_min)/2.0,0)
      ), 0
    )::numeric AS tide_score,
    -- Swell direction score
    GREATEST(
      0,
      1 - GREATEST(
            0,
            ABS(MOD(((n.wave_direction_deg)::int - ((p.swell_min + p.swell_span/2.0)) + 540)::int, 360) - 180) - (p.swell_span/2.0)
          )::float / 30.0
    ) AS swell_dir_score,
    0.0 AS period_score,
    0.0 AS height_score,
    -- Total score
    ROUND(
      100 * GREATEST(
        0,
        (0.4 * GREATEST(0,
          (1 + COS(RADIANS(ABS(MOD(((n.wind_direction_deg)::int - p.wind_offshore_deg + 540),360) - 180))))/2
          * (1 - GREATEST(0, ((COALESCE(n.wind_speed_ms,0) * 1.94384449) - p.wind_cross_shore_ok_kt)::float / 10.0))
        ))
        + (0.2 * COALESCE(
          GREATEST(
            0,
            1 - ABS(((n.tide_height_m * 3.28084)) - ((p.preferred_tide_ft_min + p.preferred_tide_ft_max)/2.0))
                  / NULLIF((p.preferred_tide_ft_max - p.preferred_tide_ft_min)/2.0,0)
          ), 0
        ))
        + (0.4 * GREATEST(
          0,
          1 - GREATEST(0, ABS(MOD(((n.wave_direction_deg)::int - ((p.swell_min + p.swell_span/2.0)) + 540)::int, 360) - 180) - (p.swell_span/2.0))::float / 30.0
        ))
      )
    )::int AS score_0_100
  FROM nearest n
  JOIN params p ON TRUE
  WHERE n.m_ts IS NOT NULL -- require a marine reference within window
),
win AS (
  SELECT
    h1.ts_utc                       AS start_ts,
    h1.ts_utc + interval '2 hour'   AS end_ts,
    round(avg(h2.score_0_100))::int AS score
  FROM scored h1
  JOIN scored h2
    ON h2.ts_utc BETWEEN h1.ts_utc AND h1.ts_utc + interval '1 hour'
  GROUP BY h1.ts_utc
),
ranked AS (
  SELECT
    w.*,
    CASE
      WHEN w.score >= 85 THEN 'epic'
      WHEN w.score >= 70 THEN 'good'
      WHEN w.score >= 55 THEN 'fair'
      ELSE 'poor'
    END AS grade
  FROM win w
  WHERE w.score >= 55
)
SELECT
  r.start_ts,
  r.end_ts,
  (r.grade || ' (' || r.score || ')')::text AS label,
  r.score
FROM ranked r
ORDER BY r.score DESC, r.start_ts
LIMIT p_limit;
$$;


ALTER FUNCTION "public"."get_best_times"("p_beach" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_bulk_current_forecasts"("p_beach_ids" "uuid"[], "p_target_date" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("beach_id" "uuid", "wave_height" "text", "forecast_date" "date", "forecast_time" time without time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  WITH ranked AS (
    SELECT
      ef.beach_id,
      ef.wave_height,
      ef.forecast_date,
      ef.forecast_time,
      ROW_NUMBER() OVER (
        PARTITION BY ef.beach_id
        ORDER BY
          CASE
            WHEN ef.forecast_date = p_target_date
                 AND ef.forecast_time >= CURRENT_TIME THEN 1
            WHEN ef.forecast_date = p_target_date + 1 THEN 2
            ELSE 3
          END ASC,
          CASE
            WHEN ef.forecast_date = p_target_date
                 AND ef.forecast_time < CURRENT_TIME
            THEN -EXTRACT(EPOCH FROM ef.forecast_time)
            ELSE  EXTRACT(EPOCH FROM ef.forecast_time)
          END ASC
      ) AS rn
    FROM enhanced_forecasts ef
    WHERE ef.beach_id = ANY(p_beach_ids)
      AND ef.forecast_date IN (p_target_date, p_target_date + 1)
  )
  SELECT r.beach_id, r.wave_height, r.forecast_date, r.forecast_time
  FROM ranked r
  WHERE r.rn = 1;
$$;


ALTER FUNCTION "public"."get_bulk_current_forecasts"("p_beach_ids" "uuid"[], "p_target_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_bulk_current_forecasts"("p_beach_ids" "uuid"[], "p_target_date" "date") IS 'Returns the current/next forecast wave_height for each beach. wave_height is the per-beach face-Hs from the transformer (lib/utils/wave-height-transformer.ts). Used by /api/forecasts/bulk to avoid PostgREST row-limit truncation.';



CREATE OR REPLACE FUNCTION "public"."get_bulk_forecast_decision_context"("p_user_id" "uuid", "p_beach_ids" "uuid"[], "p_slots" "jsonb", "p_start" "date", "p_end" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
WITH runs AS MATERIALIZED (
  (SELECT r.* FROM public.county_beach_advisory_runs r
    WHERE source_identifier = 'county-san-diego-dehq-sdbeachinfo'
    ORDER BY fetched_at DESC LIMIT 1)
  UNION
  (SELECT r.* FROM public.county_beach_advisory_runs r
    WHERE source_identifier = 'county-san-diego-dehq-sdbeachinfo' AND status = 'completed'
    ORDER BY fetched_at DESC LIMIT 1)
)
SELECT jsonb_build_object(
  'beaches', (SELECT coalesce(jsonb_agg(to_jsonb(b)), '[]') FROM (
    SELECT id, name, slug, lat, lon,
      city, state, country, region, timezone,
      break_type, skill_level, cdip_station, cdip_eligible, wind_offshore_deg,
      wind_offshore_tol_deg, wind_cross_shore_ok_kt, wind_onshore_bad_kt, swell_window_center_deg, swell_window_halfwidth_deg,
      swell_access_factors, wind_exposure_factors, preferred_tide_direction, preferred_tide_ft_min, preferred_tide_ft_max,
      tide_direction_sensitivity, preference_model, features, hazards, average_rating,
      review_count, shoaling_factors FROM public.beaches
    WHERE id = ANY(p_beach_ids) AND (NOT coalesce(is_private, false) OR owner_id = p_user_id)) b),
  'profile', (SELECT jsonb_build_object('experience_level',experience_level) FROM public.profiles WHERE id=p_user_id),
  'boards', (SELECT coalesce(jsonb_agg(jsonb_build_object('board_type',board_type)), '[]') FROM public.boards WHERE user_id=p_user_id AND retired_at IS NULL),
  'sun_times', (SELECT coalesce(jsonb_agg(jsonb_build_object('beach_id',beach_id,
    'sunrise_utc',sunrise_utc,'sunset_utc',sunset_utc) ORDER BY sunrise_utc), '[]')
    FROM public.sun_times WHERE beach_id=ANY(p_beach_ids) AND date BETWEEN p_start AND p_end),
  'personalization', CASE WHEN p_user_id IS NOT NULL THEN
    public.get_week_scout_personalization(p_user_id,p_beach_ids,p_slots) ELSE NULL END,
  'water_quality', jsonb_build_object(
    'beach_water_quality', (SELECT coalesce(jsonb_agg(to_jsonb(w)), '[]') FROM public.beach_water_quality w WHERE beach_id=ANY(p_beach_ids)),
    'water_quality_held_beaches', (SELECT coalesce(jsonb_agg(to_jsonb(w)), '[]') FROM public.water_quality_held_beaches w WHERE beach_id=ANY(p_beach_ids)),
    'county_beach_advisory_runs', (SELECT coalesce(jsonb_agg(to_jsonb(r)), '[]') FROM runs r),
    'county_beach_advisories', (SELECT coalesce(jsonb_agg(to_jsonb(a)), '[]') FROM public.county_beach_advisories a
      WHERE run_id IN (SELECT id FROM runs) AND beach_id=ANY(p_beach_ids))
  )
);
$$;


ALTER FUNCTION "public"."get_bulk_forecast_decision_context"("p_user_id" "uuid", "p_beach_ids" "uuid"[], "p_slots" "jsonb", "p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_cities_with_beach_skills"("min_beaches" integer DEFAULT 1) RETURNS TABLE("city" "text", "state" "text", "country" "text", "beach_count" bigint, "has_beginner" boolean, "has_advanced" boolean, "has_editorial" boolean, "has_least_crowded" boolean, "has_tide_data" boolean, "has_water_temp_data" boolean)
    LANGUAGE "sql" STABLE
    AS $_$
  SELECT
    b.city,
    b.state,
    COALESCE(b.country, 'USA') as country,
    COUNT(*) as beach_count,
    bool_or(
      LOWER(COALESCE(b.skill_level, '')) LIKE '%beginner%'
      OR LOWER(COALESCE(b.skill_level, '')) LIKE '%longboard%'
    ) as has_beginner,
    bool_or(
      LOWER(COALESCE(b.skill_level, '')) LIKE '%advanced%'
      OR LOWER(COALESCE(b.skill_level, '')) LIKE '%expert%'
    ) as has_advanced,
    COUNT(*) FILTER (
      WHERE COALESCE(b.description, '') <> ''
      AND (
        COALESCE(b.crowd_tips, '') <> ''
        OR COALESCE(b.wave_tips, '') <> ''
        OR COALESCE(b.best_conditions_prose, '') <> ''
      )
    ) >= 2 as has_editorial,
    bool_or(
      LOWER(COALESCE(b.crowd_level, '')) IN ('light', 'moderate')
    ) as has_least_crowded,
    bool_or(
      EXISTS (
        SELECT 1
        FROM enhanced_forecasts ef
        WHERE ef.beach_id = b.id
          AND ef.forecast_at >= date_trunc('day', now())
          AND ef.forecast_at < date_trunc('day', now()) + interval '1 day'
          AND (
            CASE
              WHEN jsonb_typeof(ef.raw_forecast -> 'tide_schedule') = 'array'
              THEN jsonb_array_length(ef.raw_forecast -> 'tide_schedule') >= 2
              ELSE false
            END
            OR ef.tide_status IS NOT NULL
            OR ef.tide_height IS NOT NULL
            OR ef.next_tide_time IS NOT NULL
            OR ef.next_tide_type IS NOT NULL
            OR ef.next_tide_height IS NOT NULL
          )
        LIMIT 1
      )
    ) as has_tide_data,
    bool_or(
      EXISTS (
        SELECT 1
        FROM enhanced_forecasts ef
        WHERE ef.beach_id = b.id
          AND ef.forecast_at >= now() - interval '7 days'
          AND ef.water_temp IS NOT NULL
          AND CASE
            WHEN regexp_replace(ef.water_temp::text, '[°Ff[:space:]]', '', 'g') ~ '^[0-9]+(\.[0-9]+)?$'
            THEN regexp_replace(ef.water_temp::text, '[°Ff[:space:]]', '', 'g')::numeric BETWEEN 30 AND 90
            ELSE false
          END
        LIMIT 1
      )
    ) as has_water_temp_data
  FROM beaches b
  WHERE (b.is_private IS NULL OR b.is_private = false)
    AND b.city IS NOT NULL
    AND b.state IS NOT NULL
    AND b.deleted_at IS NULL
  GROUP BY b.city, b.state, b.country
  HAVING COUNT(*) >= min_beaches
  ORDER BY b.city ASC
$_$;


ALTER FUNCTION "public"."get_cities_with_beach_skills"("min_beaches" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_cities_with_beach_skills"("min_beaches" integer) IS 'Returns cities with at least min_beaches beaches, including skill level, editorial, crowd, and data-backed intent availability flags.
has_beginner includes beginner and longboard skill levels (not lower-intermediate).
has_advanced includes advanced and expert skill levels.
has_editorial is true when >= 2 beaches have description AND at least one of crowd_tips/wave_tips/best_conditions_prose.
has_least_crowded is true when at least one beach has crowd_level of light or moderate.
has_tide_data is true when a city has a current-day enhanced forecast row with tide fields or a tide schedule.
has_water_temp_data is true when a city has water temperature data in enhanced forecasts from the last 7 days.
Used by sitemap generation and intent page static params.';



CREATE TABLE IF NOT EXISTS "public"."city_editorial_content" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "city_slug" "text" NOT NULL,
    "state_slug" "text" DEFAULT 'ca'::"text" NOT NULL,
    "country_slug" "text" DEFAULT 'usa'::"text" NOT NULL,
    "city_name" "text" NOT NULL,
    "region_label" "text" NOT NULL,
    "description" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "session_timing" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "quick_links" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "featured_intents" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "planning_checklist" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "intent" "text",
    "seo_indexable" boolean DEFAULT false NOT NULL,
    "editorial_reviewed_at" timestamp with time zone,
    "editorial_sources" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "seo_intro" "text",
    "seo_local_guidance" "text",
    CONSTRAINT "city_editorial_content_intent_check" CHECK ((("intent" IS NULL) OR ("intent" = ANY (ARRAY['beginner'::"text", 'tide'::"text", 'water-temp'::"text", 'general'::"text", 'least-crowded'::"text", 'longboard'::"text", 'dawn-patrol'::"text", 'sunset'::"text", 'best-time'::"text"])))),
    CONSTRAINT "city_editorial_content_sources_array_check" CHECK (("jsonb_typeof"("editorial_sources") = 'array'::"text"))
);


