CREATE OR REPLACE FUNCTION "public"."get_city_editorial"("p_city" "text", "p_state" "text" DEFAULT 'ca'::"text", "p_country" "text" DEFAULT 'usa'::"text", "p_intent" "text" DEFAULT NULL::"text") RETURNS "public"."city_editorial_content"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT c.*
  FROM public.city_editorial_content c
  WHERE lower(c.city_slug) = lower(p_city)
    AND lower(c.state_slug) = lower(p_state)
    AND lower(c.country_slug) = lower(p_country)
    AND (
      (p_intent IS NULL AND (c.intent IS NULL OR c.intent = 'general'))
      OR (p_intent IS NOT NULL AND c.intent IS NOT DISTINCT FROM p_intent)
    )
  ORDER BY
    CASE WHEN c.editorial_reviewed_at IS NULL THEN 1 ELSE 0 END,
    c.editorial_reviewed_at DESC NULLS LAST,
    c.updated_at DESC NULLS LAST,
    CASE WHEN c.intent IS NULL THEN 0 ELSE 1 END
  LIMIT 1;
$$;


ALTER FUNCTION "public"."get_city_editorial"("p_city" "text", "p_state" "text", "p_country" "text", "p_intent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_coach_picks"("_beach_id" "uuid", "_radius_km" numeric DEFAULT 80) RETURNS TABLE("pick_rank" integer, "beach_id" "uuid", "name" "text", "distance_km" numeric, "score" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  WITH origin AS (
    SELECT b.lat, b.lon
    FROM public.beaches b
    WHERE b.id = _beach_id
      AND b.deleted_at IS NULL
      AND NOT b.is_private
  ),
  candidate_distances AS (
    SELECT
      b.id,
      b.name,
      (
        6371.0088 * 2 * asin(
          least(
            1.0,
            sqrt(
              power(sin(radians((b.lat - o.lat) / 2.0)), 2) +
              cos(radians(o.lat)) * cos(radians(b.lat)) *
              power(sin(radians((b.lon - o.lon) / 2.0)), 2)
            )
          )
        )
      )::numeric AS distance_km
    FROM public.beaches b
    CROSS JOIN origin o
    WHERE b.id <> _beach_id
      AND b.deleted_at IS NULL
      AND NOT b.is_private
      AND b.recommendation_eligible
  ),
  scored_candidates AS (
    SELECT
      candidate.id,
      candidate.name,
      candidate.distance_km,
      coalesce(latest_intel.conditions_score, 0)::int AS score
    FROM candidate_distances candidate
    LEFT JOIN LATERAL (
      SELECT intel.conditions_score
      FROM public.beach_daily_intel intel
      WHERE intel.beach_id = candidate.id
      ORDER BY intel.forecast_date DESC, intel.generated_at DESC
      LIMIT 1
    ) latest_intel ON true
    WHERE candidate.distance_km <= _radius_km
  )
  SELECT
    row_number() OVER (
      ORDER BY candidate.score DESC, candidate.distance_km ASC, candidate.id
    )::int AS pick_rank,
    candidate.id AS beach_id,
    candidate.name,
    candidate.distance_km,
    candidate.score
  FROM scored_candidates candidate
  ORDER BY pick_rank
  LIMIT 3;
$$;


ALTER FUNCTION "public"."get_coach_picks"("_beach_id" "uuid", "_radius_km" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_coach_picks"("_beach_id" "uuid", "_radius_km" numeric) IS 'Returns the top three recommendation-eligible public beaches within a strict radius, ranked by each beach''s latest daily conditions score.';



CREATE OR REPLACE FUNCTION "public"."get_community_photo_monitoring_v1"("p_since" timestamp with time zone DEFAULT ("now"() - '24:00:00'::interval)) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT jsonb_build_object(
    'since', p_since,
    'uploadsReserved', count(*) FILTER (
      WHERE e.action = 'upload_reserved' AND e.outcome = 'accepted'
    ),
    'uploadsReady', count(*) FILTER (
      WHERE e.action = 'upload_ready' AND e.outcome = 'accepted'
    ),
    'uploadsFailed', count(*) FILTER (
      WHERE e.action = 'upload_failed'
    ),
    'reportsAccepted', count(*) FILTER (
      WHERE e.action = 'report' AND e.outcome = 'accepted'
    ),
    'purgesCompleted', count(*) FILTER (
      WHERE e.action = 'purge' AND e.outcome = 'accepted'
    ),
    'processingStuck', (
      SELECT count(*) FROM public.community_spot_photos p
      WHERE p.processing_status = 'processing'
        AND p.updated_at < now() - interval '15 minutes'
    ),
    'processingCleanup', (
      SELECT count(*) FROM public.community_spot_photos p
      WHERE p.processing_status = 'cleanup'
    ),
    'orphanObjects', (
      SELECT count(*) FROM storage.objects o
      WHERE o.bucket_id = 'community-spot-photos'
        AND o.created_at < now() - interval '15 minutes'
        AND NOT EXISTS (
          SELECT 1 FROM public.community_spot_photos p
          WHERE p.storage_path = o.name
        )
    ),
    'hiddenActive', (
      SELECT count(*) FROM public.community_spot_photos p
      WHERE p.lifecycle_status = 'active' AND p.moderation_status = 'hidden'
    ),
    'expiredRemovalBacklog', (
      SELECT count(*) FROM public.community_spot_photos p
      WHERE p.lifecycle_status = 'removed' AND p.recoverable_until <= now()
        AND NOT EXISTS (
          SELECT 1 FROM public.community_photo_investigation_holds h
          WHERE h.photo_id = p.id AND h.released_at IS NULL
        )
    ),
    'activeHolds', (
      SELECT count(*) FROM public.community_photo_investigation_holds h
      WHERE h.released_at IS NULL
    )
  )
  FROM public.community_photo_action_events e
  WHERE e.created_at >= p_since
$$;


ALTER FUNCTION "public"."get_community_photo_monitoring_v1"("p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_community_spot_photo_image_v1"("p_photo_id" "uuid", "p_viewer_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("storage_path" "text", "content_type" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT p.storage_path, p.content_type
  FROM public.community_spot_photos p
  WHERE p.id = p_photo_id
    AND p.processing_status = 'ready'
    AND EXISTS (
      SELECT 1 FROM public.community_photo_feature_config config
      WHERE config.singleton AND config.read_enabled
    )
    AND (
      (
        p.lifecycle_status = 'active'
        AND p.moderation_status = 'visible'
        AND p.target_type = 'beach'
        AND p.visibility = 'public'
        AND EXISTS (
          SELECT 1 FROM public.beaches b
          WHERE b.id = p.beach_id
            AND COALESCE(b.is_private, false) = false
        )
      )
      OR (
        p.lifecycle_status = 'active'
        AND p.moderation_status = 'visible'
        AND p.target_type = 'custom_spot'
        AND EXISTS (
          SELECT 1 FROM public.custom_spots cs
          WHERE cs.id = p.custom_spot_id
            AND cs.deleted_at IS NULL
            AND (
              (p.visibility = 'public' AND cs.visibility = 'public')
              OR (
                p.visibility = 'private'
                AND cs.user_id = p_viewer_id
                AND p.uploader_id = p_viewer_id
              )
            )
        )
      )
      OR (
        p.lifecycle_status = 'removed'
        AND p.recoverable_until > now()
        AND p.uploader_id IS NOT NULL
        AND p.uploader_id = p_viewer_id
      )
    )
$$;


ALTER FUNCTION "public"."get_community_spot_photo_image_v1"("p_photo_id" "uuid", "p_viewer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_conditions_alert_candidates"("p_min_score" integer DEFAULT 7) RETURNS TABLE("user_id" "uuid", "email" "text", "display_name" "text", "experience_level" "text", "home_beach_id" "uuid", "beach_name" "text", "beach_slug" "text", "beach_state" "text", "beach_city" "text", "conditions_score" integer, "surf_description" "text", "wind_description" "text", "best_window_start" time without time zone, "best_window_end" time without time zone, "recommendation" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH eligible_users AS (
    SELECT
      p.id,
      p.email,
      p.display_name,
      p.experience_level,
      p.home_beach_id
    FROM profiles p
    WHERE p.home_beach_id IS NOT NULL
      AND p.email IS NOT NULL
      AND p.notif_email_enabled = true
      AND p.notif_forecast_alerts = true
      AND COALESCE(p.is_mock, false) = false
  ),
  users_with_beach AS (
    SELECT
      eu.id,
      eu.email,
      eu.display_name,
      eu.experience_level,
      eu.home_beach_id,
      COALESCE(b.timezone, 'America/Los_Angeles') AS beach_tz
    FROM eligible_users eu
    INNER JOIN beaches b ON b.id = eu.home_beach_id
  ),
  latest_intel AS (
    SELECT DISTINCT ON (bdi.beach_id)
      bdi.beach_id,
      bdi.conditions_score,
      bdi.surf_description,
      bdi.wind_description,
      bdi.best_window_start,
      bdi.best_window_end,
      bdi.recommendation
    FROM beach_daily_intel bdi
    INNER JOIN users_with_beach uwb ON uwb.home_beach_id = bdi.beach_id
    WHERE bdi.forecast_date = (CURRENT_TIMESTAMP AT TIME ZONE uwb.beach_tz)::date
      AND bdi.conditions_score >= p_min_score
    ORDER BY bdi.beach_id, bdi.generated_at DESC
  ),
  active_today_filter AS (
    SELECT
      uwb.id,
      uwb.email,
      uwb.display_name,
      uwb.experience_level,
      uwb.home_beach_id,
      uwb.beach_tz
    FROM users_with_beach uwb
    WHERE NOT EXISTS (
      SELECT 1
      FROM user_events ue
      WHERE ue.user_id = uwb.id
        AND ue.created_at >= (CURRENT_TIMESTAMP AT TIME ZONE uwb.beach_tz)::date AT TIME ZONE uwb.beach_tz
    )
  ),
  email_dedup AS (
    SELECT
      atf.id,
      atf.email,
      atf.display_name,
      atf.experience_level,
      atf.home_beach_id
    FROM active_today_filter atf
    WHERE NOT EXISTS (
      SELECT 1
      FROM email_send_log esl
      WHERE esl.user_id = atf.id
        AND esl.sent_at >= (CURRENT_TIMESTAMP AT TIME ZONE atf.beach_tz)::date AT TIME ZONE atf.beach_tz
    )
  )
  SELECT
    ed.id AS user_id,
    ed.email,
    ed.display_name,
    ed.experience_level,
    ed.home_beach_id,
    b.name AS beach_name,
    b.slug AS beach_slug,
    b.state AS beach_state,
    b.city AS beach_city,
    li.conditions_score,
    li.surf_description,
    li.wind_description,
    li.best_window_start,
    li.best_window_end,
    li.recommendation
  FROM email_dedup ed
  INNER JOIN beaches b ON b.id = ed.home_beach_id
  INNER JOIN latest_intel li ON li.beach_id = ed.home_beach_id;
END;
$$;


ALTER FUNCTION "public"."get_conditions_alert_candidates"("p_min_score" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_conditions_alert_candidates"("p_min_score" integer) IS 'Returns users eligible for conditions alert emails based on high beach_daily_intel scores today, including experience_level for skill-aware re-scoring. Excludes users active in app today or who received any email today. Uses beach-specific timezone for date calculations.';



CREATE OR REPLACE FUNCTION "public"."get_conversion_funnel"("days" integer DEFAULT 7) RETURNS TABLE("funnel_step" "text", "step_order" integer, "total_count" bigint, "unique_sessions" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  cutoff TIMESTAMPTZ;
BEGIN
  cutoff := NOW() - (days || ' days')::INTERVAL;

  RETURN QUERY
  WITH funnel_events AS (
    SELECT
      event_type,
      COALESCE(session_id::text, user_id::text) AS identity_key
    FROM public.user_events
    WHERE created_at >= cutoff
      AND (bot_flagged IS NULL OR bot_flagged = false)
  )
  SELECT
    s.step_name AS funnel_step,
    s.step_order,
    COALESCE(f.total_count, 0) AS total_count,
    COALESCE(f.unique_sessions, 0) AS unique_sessions
  FROM (
    VALUES
      ('anonymous_sessions', 1),
      ('cta_views', 2),
      ('cta_clicks', 3),
      ('auth_modal_opens', 4),
      ('signup_starts', 5),
      ('signup_completes', 6),
      ('onboarding_completes', 7)
  ) AS s(step_name, step_order)
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*) AS total_count,
      COUNT(DISTINCT fe.identity_key) AS unique_sessions
    FROM funnel_events fe
    WHERE
      CASE s.step_name
        WHEN 'anonymous_sessions' THEN fe.event_type IN (
          'page_view', 'beach_view', 'tab_view', 'forecast_interaction',
          'beach_search', 'map_interaction', 'map_marker_click',
          'signup_cta_view', 'signup_cta_click', 'signin_cta_click',
          'auth_modal_opened', 'auth_method_selected',
          'signup_started', 'signup_success', 'login_success'
        )
        WHEN 'cta_views' THEN fe.event_type = 'signup_cta_view'
        WHEN 'cta_clicks' THEN fe.event_type IN ('signup_cta_click', 'signin_cta_click', 'cta_click')
        WHEN 'auth_modal_opens' THEN fe.event_type = 'auth_modal_opened'
        WHEN 'signup_starts' THEN fe.event_type = 'signup_started'
        WHEN 'signup_completes' THEN fe.event_type = 'signup_success'
        WHEN 'onboarding_completes' THEN fe.event_type = 'onboarding_step'
          AND fe.identity_key IN (
            SELECT p.id::text FROM public.profiles p
            WHERE p.onboarding_completed_at IS NOT NULL
              AND p.onboarding_completed_at >= cutoff
          )
        ELSE false
      END
  ) f ON true
  ORDER BY s.step_order;
END;
$$;


ALTER FUNCTION "public"."get_conversion_funnel"("days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_conversion_funnel"("days" integer) IS 'Returns the signup conversion funnel metrics for the past N days. Steps: anonymous_sessions -> cta_views -> cta_clicks -> auth_modal_opens -> signup_starts -> signup_completes -> onboarding_completes. Excludes bot-flagged events.';



CREATE OR REPLACE FUNCTION "public"."get_current_beach_wind"("p_beach_id" "uuid") RETURNS TABLE("observed_at" timestamp with time zone, "wind_speed_mph" numeric, "wind_direction" "text", "wind_direction_deg" numeric, "wind_gust_mph" numeric, "source" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    observation.observed_at,
    observation.wind_speed_mph,
    observation.wind_direction,
    observation.wind_direction_deg,
    observation.wind_gust_mph,
    observation.source
  FROM public.beach_wind_observations AS observation
  WHERE observation.beach_id = p_beach_id
    AND observation.observed_at >= now() - interval '2 hours'
    AND observation.observed_at <= now() + interval '15 minutes'
  ORDER BY observation.observed_at DESC
  LIMIT 1;
$$;


