COMMENT ON FUNCTION "public"."get_metro_stats"("p_cities" "text"[], "p_state" "text", "p_country" "text") IS 'Returns aggregate statistics for a metro area spanning multiple cities.';



CREATE OR REPLACE FUNCTION "public"."get_ml_health_metrics"() RETURNS TABLE("total_predictions" bigint, "pending_observations" bigint, "pending_12_24h" bigint, "pending_gt_24h" bigint, "sentinel_marked" bigint, "matched_last_24h" bigint, "total_observable_24h" bigint, "match_rate_24h" numeric, "avg_raw_error_24h" numeric, "avg_corrected_error_24h" numeric, "improvement_pct_24h" numeric, "oldest_pending_age_hours" numeric, "observable_beaches_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (
        WHERE p.observed_m IS NULL
          AND p.predicted_at < now() - interval '4 hours'
          AND p.predicted_at > now() - interval '7 days'
          AND ob.beach_id IS NOT NULL
      ) AS pending,
      COUNT(*) FILTER (
        WHERE p.observed_m IS NULL
          AND p.predicted_at < now() - interval '12 hours'
          AND p.predicted_at >= now() - interval '24 hours'
          AND ob.beach_id IS NOT NULL
      ) AS pending_12_24h,
      COUNT(*) FILTER (
        WHERE p.observed_m IS NULL
          AND p.predicted_at < now() - interval '24 hours'
          AND ob.beach_id IS NOT NULL
      ) AS pending_gt_24h,
      COUNT(*) FILTER (
        WHERE p.observed_m = -1
      ) AS sentinel,
      COUNT(*) FILTER (
        WHERE p.predicted_at > now() - interval '24 hours'
          AND p.predicted_at < now() - interval '4 hours'
          AND ob.beach_id IS NOT NULL
      ) AS total_24h,
      COUNT(*) FILTER (
        WHERE p.predicted_at > now() - interval '24 hours'
          AND p.observed_m > 0
          AND ob.beach_id IS NOT NULL
      ) AS matched_24h,
      AVG(ABS(p.raw_display_height_m - p.observed_m)) FILTER (
        WHERE p.predicted_at > now() - interval '24 hours'
          AND p.observed_m > 0
          AND p.raw_display_height_m IS NOT NULL
          AND ob.beach_id IS NOT NULL
      ) AS avg_raw_display_24h,
      AVG(ABS(p.offset_corrected_display_height_m - p.observed_m)) FILTER (
        WHERE p.predicted_at > now() - interval '24 hours'
          AND p.observed_m > 0
          AND p.offset_corrected_display_height_m IS NOT NULL
          AND ob.beach_id IS NOT NULL
      ) AS avg_current_display_24h,
      EXTRACT(EPOCH FROM (now() - MIN(p.predicted_at) FILTER (
        WHERE p.observed_m IS NULL
          AND p.predicted_at < now() - interval '4 hours'
          AND p.predicted_at > now() - interval '7 days'
          AND ob.beach_id IS NOT NULL
      ))) / 3600 AS oldest_pending_hours
    FROM public.ml_predictions_log p
    LEFT JOIN public.observable_beaches ob ON ob.beach_id = p.beach_id
    WHERE p.predicted_at > now() - interval '30 days'
      AND p.display_source = 'face-Hs-transformer-v1'
  ),
  beach_count AS (
    SELECT COUNT(*) AS cnt FROM public.observable_beaches
  )
  SELECT
    s.total::bigint,
    s.pending::bigint,
    s.pending_12_24h::bigint,
    s.pending_gt_24h::bigint,
    s.sentinel::bigint,
    s.matched_24h::bigint,
    s.total_24h::bigint,
    ROUND(100.0 * s.matched_24h / NULLIF(s.total_24h, 0), 1),
    ROUND(s.avg_raw_display_24h::numeric, 3),
    ROUND(s.avg_current_display_24h::numeric, 3),
    ROUND(
      100.0 * (s.avg_raw_display_24h - s.avg_current_display_24h) /
      NULLIF(s.avg_raw_display_24h, 0),
      1
    ),
    ROUND(s.oldest_pending_hours, 1),
    b.cnt::bigint
  FROM stats s, beach_count b;
END;
$$;


ALTER FUNCTION "public"."get_ml_health_metrics"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ml_health_metrics"() IS 'Returns ML pipeline health metrics. Phase 0 repointed 24h MAE from retired raw/corrected error columns to live raw_display_height_m and offset_corrected_display_height_m vs observed_m.';



CREATE OR REPLACE FUNCTION "public"."get_ml_weekly_metrics"() RETURNS TABLE("model_version" "text", "predictions" bigint, "with_ground_truth" bigint, "avg_raw_error_m" numeric, "avg_corrected_error_m" numeric, "avg_improvement_m" numeric, "pct_improved" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH weekly AS (
    SELECT
      p.model_version,
      p.observed_m,
      p.raw_display_height_m,
      p.offset_corrected_display_height_m,
      CASE
        WHEN p.observed_m > 0 AND p.raw_display_height_m IS NOT NULL
        THEN ABS(p.raw_display_height_m - p.observed_m)
        ELSE NULL
      END AS raw_display_error_m,
      CASE
        WHEN p.observed_m > 0 AND p.offset_corrected_display_height_m IS NOT NULL
        THEN ABS(p.offset_corrected_display_height_m - p.observed_m)
        ELSE NULL
      END AS current_display_error_m
    FROM public.ml_predictions_log p
    WHERE p.predicted_at > now() - interval '7 days'
      AND p.display_source = 'face-Hs-transformer-v1'
  )
  SELECT
    weekly.model_version,
    COUNT(*)::bigint AS predictions,
    COUNT(*) FILTER (WHERE weekly.observed_m > 0)::bigint AS with_ground_truth,
    ROUND(AVG(weekly.raw_display_error_m)::numeric, 3) AS avg_raw_error_m,
    ROUND(AVG(weekly.current_display_error_m)::numeric, 3) AS avg_corrected_error_m,
    ROUND(AVG(weekly.raw_display_error_m - weekly.current_display_error_m)::numeric, 3) AS avg_improvement_m,
    ROUND(
      100.0 * COUNT(*) FILTER (
        WHERE weekly.current_display_error_m < weekly.raw_display_error_m
      ) / NULLIF(
        COUNT(*) FILTER (
          WHERE weekly.current_display_error_m IS NOT NULL
            AND weekly.raw_display_error_m IS NOT NULL
        ),
        0
      ),
      1
    ) AS pct_improved
  FROM weekly
  GROUP BY weekly.model_version
  ORDER BY weekly.model_version DESC;
$$;


ALTER FUNCTION "public"."get_ml_weekly_metrics"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_ml_weekly_metrics"() IS 'Compatibility weekly metrics for scripts/ml-stats. Phase 0 repointed MAE from retired corrected_forecast_m/raw_error_m fields to live display snapshot columns vs observed_m.';



CREATE OR REPLACE FUNCTION "public"."get_most_visited_beach"("user_id" "uuid") RETURNS TABLE("beach_id" "uuid", "visit_count" bigint, "beach_name" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.beach_id,
    COUNT(s.id)::BIGINT AS visit_count,
    b.name              AS beach_name
  FROM sessions s
  JOIN beaches b ON b.id = s.beach_id
  WHERE s.user_id = get_most_visited_beach.user_id
    AND s.deleted_at IS NULL
  GROUP BY s.beach_id, b.name
  ORDER BY visit_count DESC
  LIMIT 1;
END;
$$;


