CREATE OR REPLACE FUNCTION "public"."get_user_board_deck_stats"("p_user_id" "uuid") RETURNS TABLE("board_id" "uuid", "sessions_count" integer, "positive_sessions_count" integer, "best_period_range" "text", "best_wind_label" "text", "learned_label" "text", "last_used_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  IF p_user_id <> auth.uid() THEN
    RAISE EXCEPTION 'Access denied: can only query own board stats';
  END IF;

  RETURN QUERY
  WITH board_base AS (
    SELECT b.id AS board_id
    FROM public.boards b
    WHERE b.user_id = p_user_id
      AND b.retired_at IS NULL
  ),
  session_base AS (
    SELECT
      s.board_id,
      s.id AS session_id,
      s.rating,
      s.arrival_time,
      s.custom_spot_id,
      public.parse_numeric_from_text(sfs.forecast_snapshot->>'wave_period') AS wave_period_s,
      public.parse_numeric_from_text(sfs.forecast_snapshot->>'wind_speed') AS wind_speed_mph,
      public.parse_numeric_from_text(COALESCE(
        sfs.forecast_snapshot->>'wind_direction_deg',
        sfs.forecast_snapshot->>'wind_direction'
      )) AS wind_direction_deg
    FROM public.sessions s
    LEFT JOIN public.session_forecast_snapshots sfs ON sfs.session_id = s.id
    WHERE s.user_id = p_user_id
      AND s.board_id IS NOT NULL
      AND s.status = 'completed'
      AND s.deleted_at IS NULL
  ),
  positive AS (
    SELECT *
    FROM session_base
    WHERE rating >= 4
  ),
  aggregate_stats AS (
    SELECT
      bb.board_id,
      COUNT(sb.session_id)::integer AS sessions_count,
      COUNT(p.session_id)::integer AS positive_sessions_count,
      MAX(sb.arrival_time) AS last_used_at,
      percentile_cont(0.25) WITHIN GROUP (ORDER BY p.wave_period_s)
        FILTER (WHERE p.wave_period_s IS NOT NULL) AS p25_period,
      percentile_cont(0.75) WITHIN GROUP (ORDER BY p.wave_period_s)
        FILTER (WHERE p.wave_period_s IS NOT NULL) AS p75_period,
      AVG(p.wind_speed_mph) FILTER (WHERE p.wind_speed_mph IS NOT NULL) AS avg_wind_speed,
      AVG(
        CASE
          WHEN cs.offshore_direction_deg IS NULL OR p.wind_direction_deg IS NULL THEN NULL
          ELSE LEAST(
            ABS(cs.offshore_direction_deg - p.wind_direction_deg),
            360 - ABS(cs.offshore_direction_deg - p.wind_direction_deg)
          )
        END
      ) FILTER (WHERE cs.offshore_direction_deg IS NOT NULL AND p.wind_direction_deg IS NOT NULL) AS avg_offshore_delta
    FROM board_base bb
    LEFT JOIN session_base sb ON sb.board_id = bb.board_id
    LEFT JOIN positive p ON p.board_id = bb.board_id
    LEFT JOIN public.custom_spots cs ON cs.id = p.custom_spot_id
    GROUP BY bb.board_id
  )
  SELECT
    a.board_id,
    COALESCE(a.sessions_count, 0),
    COALESCE(a.positive_sessions_count, 0),
    CASE
      WHEN COALESCE(a.positive_sessions_count, 0) < 3 OR a.p25_period IS NULL OR a.p75_period IS NULL THEN NULL
      ELSE format('Best: %s-%ss', round(a.p25_period)::integer, round(a.p75_period)::integer)
    END AS best_period_range,
    CASE
      WHEN COALESCE(a.positive_sessions_count, 0) < 3 THEN NULL
      WHEN a.avg_offshore_delta IS NOT NULL AND a.avg_offshore_delta <= 45 THEN 'Light offshore'
      WHEN a.avg_offshore_delta IS NOT NULL AND a.avg_offshore_delta <= 75 THEN 'Clean side-off'
      WHEN a.avg_wind_speed IS NULL THEN NULL
      WHEN a.avg_wind_speed <= 7 THEN 'Light wind'
      WHEN a.avg_wind_speed <= 12 THEN 'Handles texture'
      ELSE 'Wind tolerant'
    END AS best_wind_label,
    CASE
      WHEN COALESCE(a.positive_sessions_count, 0) < 3 THEN 'Learning this board'
      ELSE 'Learned from sessions'
    END AS learned_label,
    a.last_used_at
  FROM aggregate_stats a;
END;
$$;


ALTER FUNCTION "public"."get_user_board_deck_stats"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_match_candidates"("p_user_id" "uuid", "p_exclude_beach_id" "uuid" DEFAULT NULL::"uuid", "p_device_lat" double precision DEFAULT NULL::double precision, "p_device_lon" double precision DEFAULT NULL::double precision, "p_radius_km" double precision DEFAULT 50, "p_limit" integer DEFAULT 5) RETURNS TABLE("beach" "jsonb", "score" numeric, "label" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_have_device boolean :=
    p_device_lat IS NOT NULL
    AND p_device_lon IS NOT NULL
    AND p_device_lat BETWEEN -90 AND 90
    AND p_device_lon BETWEEN -180 AND 180;
  v_role text := COALESCE(auth.role(), 'anon');
  v_caller uuid := auth.uid();
  v_is_paid boolean := false;
  v_billing_issue boolean := false;
  v_expires_at timestamptz;
  v_max_drive_minutes integer;
  v_profile_radius_km double precision;
  v_effective_radius_km double precision;
BEGIN
  IF v_role <> 'service_role' THEN
    IF v_caller IS NULL OR p_user_id <> v_caller THEN
      RETURN;
    END IF;

    SELECT
      COALESCE(ue.is_pro, false) OR COALESCE(ue.is_trialing, false),
      COALESCE(ue.billing_issue, false),
      ue.expires_at
    INTO v_is_paid, v_billing_issue, v_expires_at
    FROM public.user_entitlements ue
    WHERE ue.user_id = p_user_id
    LIMIT 1;

    IF v_billing_issue THEN
      RETURN;
    END IF;

    IF (NOT COALESCE(v_is_paid, false)
      OR (v_expires_at IS NOT NULL AND v_expires_at < now()))
      AND NOT public.founding_access_enabled() THEN
      RETURN;
    END IF;
  END IF;

  SELECT p.max_drive_minutes
  INTO v_max_drive_minutes
  FROM public.profiles p
  WHERE p.id = p_user_id
  LIMIT 1;

  v_profile_radius_km := CASE
    WHEN v_max_drive_minutes IS NULL THEN 100.0
    ELSE LEAST(GREATEST(v_max_drive_minutes, 15), 90) * 0.5 * 1.609344
  END;
  v_effective_radius_km := LEAST(
    v_profile_radius_km,
    GREATEST(COALESCE(p_radius_km, v_profile_radius_km), 0)
  );

  RETURN QUERY
  WITH device_location AS (
    SELECT ST_SetSRID(ST_MakePoint(p_device_lon, p_device_lat), 4326)::geography AS geog
    WHERE v_have_device
  ),
  local_candidate_beaches AS (
    SELECT
      b.id,
      b.name,
      b.lat,
      b.lon,
      ST_Distance(b.geog, device_location.geog) / 1000.0 AS distance_km,
      'device_radius'::text AS candidate_source
    FROM public.beaches b
    CROSS JOIN device_location
    WHERE v_have_device
      AND b.deleted_at IS NULL
      AND b.recommendation_eligible
      AND b.geog IS NOT NULL
      AND (p_exclude_beach_id IS NULL OR b.id <> p_exclude_beach_id)
      AND ST_DWithin(
        b.geog,
        device_location.geog,
        v_effective_radius_km * 1000
      )
  ),
  favorite_candidate_beaches AS (
    SELECT
      b.id,
      b.name,
      b.lat,
      b.lon,
      NULL::double precision AS distance_km,
      'favorite'::text AS candidate_source
    FROM public.beaches b
    WHERE NOT v_have_device
      AND b.deleted_at IS NULL
      AND b.recommendation_eligible
      AND (p_exclude_beach_id IS NULL OR b.id <> p_exclude_beach_id)
      AND EXISTS (
        SELECT 1
        FROM public.favorite_beaches fb
        WHERE fb.user_id = p_user_id
          AND fb.beach_id = b.id
      )
  ),
  combined_candidate_beaches AS (
    SELECT * FROM local_candidate_beaches
    UNION ALL
    SELECT * FROM favorite_candidate_beaches
  ),
  actionable_forecast AS (
    SELECT DISTINCT ON (ef.beach_id)
      ef.beach_id,
      ef.wave_height,
      ef.wave_period,
      ef.wind_speed,
      (ef.wind_direction_deg)::text AS wind_direction,
      ef.tide_height
    FROM public.enhanced_forecasts ef
    WHERE ef.beach_id IN (SELECT id FROM combined_candidate_beaches)
      AND ef.forecast_at IS NOT NULL
      AND ef.forecast_at >= now() - interval '45 minutes'
      AND ef.forecast_at <= now() + interval '72 hours'
    ORDER BY
      ef.beach_id,
      CASE WHEN ef.forecast_at::date = now()::date THEN 0 ELSE 1 END,
      ABS(EXTRACT(EPOCH FROM (ef.forecast_at - now()))),
      ef.forecast_at ASC
  ),
  scored AS (
    SELECT
      cb.id,
      cb.name,
      cb.lat,
      cb.lon,
      cb.distance_km,
      cb.candidate_source,
      public.compute_user_match_score(
        p_user_id,
        cb.id,
        af.wave_height,
        af.wave_period,
        af.wind_speed,
        af.wind_direction,
        af.tide_height
      ) AS result
    FROM combined_candidate_beaches cb
    JOIN actionable_forecast af ON af.beach_id = cb.id
  )
  SELECT
    jsonb_build_object(
      'id', s.id,
      'name', s.name,
      'lat', s.lat,
      'lon', s.lon,
      'distance_km', s.distance_km,
      'candidate_source', s.candidate_source
    ) AS beach,
    (s.result->>'score')::numeric AS score,
    COALESCE(s.result->>'label', s.result->>'fit_label') AS label
  FROM scored s
  WHERE s.result->>'state' IN ('ready', 'learned')
    AND jsonb_typeof(s.result->'score') = 'number'
  ORDER BY (s.result->>'score')::numeric DESC NULLS LAST
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_user_match_candidates"("p_user_id" "uuid", "p_exclude_beach_id" "uuid", "p_device_lat" double precision, "p_device_lon" double precision, "p_radius_km" double precision, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_referral_stats"("user_id" "uuid") RETURNS TABLE("total_referrals" bigint, "completed_referrals" bigint, "pending_referrals" bigint, "expired_referrals" bigint, "referral_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(*) AS total_referrals,
        COUNT(*) FILTER (WHERE status = 'completed') AS completed_referrals,
        COUNT(*) FILTER (WHERE status = 'pending') AS pending_referrals,
        COUNT(*) FILTER (WHERE status = 'expired') AS expired_referrals,
        p.referral_code
    FROM public.profiles p
    LEFT JOIN public.referrals r ON r.referrer_id = p.id
    WHERE p.id = user_id
    GROUP BY p.id, p.referral_code;
END;
$$;


ALTER FUNCTION "public"."get_user_referral_stats"("user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_user_referral_stats"("user_id" "uuid") IS 'Returns referral statistics for a given user (total, completed, pending, expired counts)';



CREATE OR REPLACE FUNCTION "public"."get_user_session_match_comparison"("p_user_id" "uuid", "p_beach_id" "uuid", "p_wave_height" "text", "p_wave_period" "text", "p_wind_speed" "text", "p_wind_direction" "text", "p_tide_height" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_profile_count integer;
  v_future_wave numeric := public.parse_numeric_or_null(p_wave_height);
  v_future_period numeric := public.parse_numeric_or_null(p_wave_period);
  v_future_wind numeric := public.parse_numeric_or_null(p_wind_speed);
  v_future_wind_dir numeric := public.parse_numeric_or_null(p_wind_direction);
  v_future_tide numeric := public.parse_numeric_or_null(p_tide_height);
  v_positive jsonb;
  v_negative jsonb;
BEGIN
  IF p_user_id <> auth.uid() THEN
    RAISE EXCEPTION 'Access denied: can only query own match comparison';
  END IF;

  SELECT COUNT(*)::integer INTO v_profile_count
  FROM public.sessions s
  JOIN public.session_forecast_snapshots sfs ON sfs.session_id = s.id
  WHERE s.user_id = p_user_id
    AND s.status = 'completed'
    AND s.rating IS NOT NULL
    AND s.arrival_time > now() - interval '12 months'
    AND s.deleted_at IS NULL
    AND sfs.forecast_snapshot IS NOT NULL;

  IF v_profile_count < 5 THEN
    RETURN jsonb_build_object(
      'state', 'locked',
      'session_count', v_profile_count,
      'sessions_needed', 5 - v_profile_count
    );
  END IF;

  WITH scored AS (
    SELECT
      s.id,
      s.rating,
      s.arrival_time,
      COALESCE(s.board_snapshot->>'name', b.name) AS board_name,
      public.parse_numeric_or_null(sfs.forecast_snapshot->>'wave_height') AS wave_height,
      public.parse_numeric_or_null(sfs.forecast_snapshot->>'wave_period') AS wave_period,
      public.parse_numeric_or_null(sfs.forecast_snapshot->>'wind_speed') AS wind_speed,
      public.parse_numeric_or_null(COALESCE(sfs.forecast_snapshot->>'wind_direction_deg', sfs.forecast_snapshot->>'wind_direction')) AS wind_direction,
      public.parse_numeric_or_null(sfs.forecast_snapshot->>'tide_height') AS tide_height,
      (
        COALESCE(ABS(public.parse_numeric_or_null(sfs.forecast_snapshot->>'wave_height') - v_future_wave), 99) * 0.35 +
        COALESCE(ABS(public.parse_numeric_or_null(sfs.forecast_snapshot->>'wave_period') - v_future_period), 99) * 0.20 +
        COALESCE(ABS(public.parse_numeric_or_null(sfs.forecast_snapshot->>'wind_speed') - v_future_wind), 99) * 0.15 +
        COALESCE(LEAST(
          ABS(public.parse_numeric_or_null(COALESCE(sfs.forecast_snapshot->>'wind_direction_deg', sfs.forecast_snapshot->>'wind_direction')) - v_future_wind_dir),
          360 - ABS(public.parse_numeric_or_null(COALESCE(sfs.forecast_snapshot->>'wind_direction_deg', sfs.forecast_snapshot->>'wind_direction')) - v_future_wind_dir)
        ) / 30, 99) * 0.15 +
        COALESCE(ABS(public.parse_numeric_or_null(sfs.forecast_snapshot->>'tide_height') - v_future_tide), 99) * 0.15
      ) AS distance_score
    FROM public.sessions s
    JOIN public.session_forecast_snapshots sfs ON sfs.session_id = s.id
    LEFT JOIN public.boards b ON b.id = s.board_id
    WHERE s.user_id = p_user_id
      AND s.status = 'completed'
      AND s.rating IS NOT NULL
      AND s.arrival_time > now() - interval '12 months'
      AND s.deleted_at IS NULL
      AND sfs.forecast_snapshot IS NOT NULL
      AND (s.beach_id = p_beach_id OR p_beach_id IS NULL)
  )
  SELECT jsonb_build_object(
    'session_id', id,
    'rating', rating,
    'arrival_time', arrival_time,
    'board_name', board_name,
    'deltas', jsonb_build_object(
      'waves', round((v_future_wave - wave_height)::numeric, 1),
      'period', round((v_future_period - wave_period)::numeric, 0),
      'wind', round((v_future_wind - wind_speed)::numeric, 0),
      'tide', round((v_future_tide - tide_height)::numeric, 1)
    )
  )
  INTO v_positive
  FROM scored
  WHERE rating >= 4
  ORDER BY distance_score ASC NULLS LAST
  LIMIT 1;

  WITH scored AS (
    SELECT
      s.id,
      s.rating,
      s.arrival_time,
      COALESCE(s.board_snapshot->>'name', b.name) AS board_name,
      public.parse_numeric_or_null(sfs.forecast_snapshot->>'wave_height') AS wave_height,
      public.parse_numeric_or_null(sfs.forecast_snapshot->>'wave_period') AS wave_period,
      public.parse_numeric_or_null(sfs.forecast_snapshot->>'wind_speed') AS wind_speed,
      public.parse_numeric_or_null(sfs.forecast_snapshot->>'tide_height') AS tide_height,
      (
        COALESCE(ABS(public.parse_numeric_or_null(sfs.forecast_snapshot->>'wave_height') - v_future_wave), 99) * 0.35 +
        COALESCE(ABS(public.parse_numeric_or_null(sfs.forecast_snapshot->>'wave_period') - v_future_period), 99) * 0.25 +
        COALESCE(ABS(public.parse_numeric_or_null(sfs.forecast_snapshot->>'wind_speed') - v_future_wind), 99) * 0.20 +
        COALESCE(ABS(public.parse_numeric_or_null(sfs.forecast_snapshot->>'tide_height') - v_future_tide), 99) * 0.20
      ) AS distance_score
    FROM public.sessions s
    JOIN public.session_forecast_snapshots sfs ON sfs.session_id = s.id
    LEFT JOIN public.boards b ON b.id = s.board_id
    WHERE s.user_id = p_user_id
      AND s.status = 'completed'
      AND s.rating IS NOT NULL
      AND s.arrival_time > now() - interval '12 months'
      AND s.deleted_at IS NULL
      AND sfs.forecast_snapshot IS NOT NULL
      AND (s.beach_id = p_beach_id OR p_beach_id IS NULL)
  )
  SELECT jsonb_build_object(
    'session_id', id,
    'rating', rating,
    'arrival_time', arrival_time,
    'board_name', board_name
  )
  INTO v_negative
  FROM scored
  WHERE rating <= 2
  ORDER BY distance_score ASC NULLS LAST
  LIMIT 1;

  IF v_positive IS NULL THEN
    RETURN jsonb_build_object(
      'state', 'no_data',
      'session_count', v_profile_count
    );
  END IF;

  RETURN jsonb_build_object(
    'state', 'ready',
    'future', jsonb_build_object(
      'wave_height', p_wave_height,
      'wave_period', p_wave_period,
      'wind_speed', p_wind_speed,
      'wind_direction', p_wind_direction,
      'tide_height', p_tide_height
    ),
    'positive_session', v_positive,
    'negative_session', v_negative,
    'confidence', CASE WHEN v_profile_count >= 20 THEN 'high' WHEN v_profile_count >= 10 THEN 'medium' ELSE 'low' END
  );
END;
$$;


ALTER FUNCTION "public"."get_user_session_match_comparison"("p_user_id" "uuid", "p_beach_id" "uuid", "p_wave_height" "text", "p_wave_period" "text", "p_wind_speed" "text", "p_wind_direction" "text", "p_tide_height" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_storage_stats"("p_user_id" "uuid") RETURNS TABLE("total_bytes" bigint, "image_count" integer, "remaining_bytes" bigint, "usage_percentage" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  user_limit CONSTANT BIGINT := 104857600; -- 100MB per user
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN
    RAISE EXCEPTION 'get_user_storage_stats requires the authenticated owner'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    COALESCE(su.total_bytes, 0) as total_bytes,
    COALESCE(su.image_count, 0) as image_count,
    GREATEST(0, user_limit - COALESCE(su.total_bytes, 0)) as remaining_bytes,
    ROUND((COALESCE(su.total_bytes, 0)::NUMERIC / user_limit::NUMERIC) * 100, 2) as usage_percentage
  FROM public.storage_usage su
  WHERE su.user_id = p_user_id
  UNION ALL
  SELECT 0::BIGINT, 0::INTEGER, user_limit, 0.00::NUMERIC
  WHERE NOT EXISTS (SELECT 1 FROM public.storage_usage WHERE user_id = p_user_id)
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."get_user_storage_stats"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_user_storage_stats"("p_user_id" "uuid") IS 'Returns storage statistics for a user including total bytes, image count, remaining quota, and usage percentage';



CREATE OR REPLACE FUNCTION "public"."get_user_streaks"("p_user_id" "uuid") RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_week_best INT := 0;
  v_week_current INT := 0;
  v_day_best INT := 0;
  v_day_current INT := 0;
  v_this_week DATE := date_trunc('week', NOW())::date;
  v_today DATE := CURRENT_DATE;
  v_caller UUID := auth.uid();
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'get_user_streaks: p_user_id is required'
      USING ERRCODE = '22023';
  END IF;

  IF v_caller IS NOT NULL AND v_caller IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'get_user_streaks: caller may only read own streaks'
      USING ERRCODE = '42501';
  END IF;

  WITH weeks AS (
    SELECT DISTINCT date_trunc('week', arrival_time)::date AS wk
    FROM public.sessions
    WHERE user_id = p_user_id
      AND deleted_at IS NULL
  ),
  islands AS (
    SELECT
      wk,
      (wk - ((ROW_NUMBER() OVER (ORDER BY wk))::int * INTERVAL '7 day'))::date AS grp
    FROM weeks
  ),
  runs AS (
    SELECT grp, COUNT(*)::int AS run_len, MAX(wk) AS last_wk
    FROM islands
    GROUP BY grp
  )
  SELECT
    COALESCE(MAX(run_len), 0),
    COALESCE(MAX(run_len) FILTER (WHERE last_wk >= v_this_week - INTERVAL '7 day'), 0)
  INTO v_week_best, v_week_current
  FROM runs;

  WITH days AS (
    SELECT DISTINCT call_date AS d
    FROM public.daily_calls
    WHERE user_id = p_user_id
  ),
  islands AS (
    SELECT
      d,
      (d - ((ROW_NUMBER() OVER (ORDER BY d))::int * INTERVAL '1 day'))::date AS grp
    FROM days
  ),
  runs AS (
    SELECT grp, COUNT(*)::int AS run_len, MAX(d) AS last_d
    FROM islands
    GROUP BY grp
  )
  SELECT
    COALESCE(MAX(run_len), 0),
    COALESCE(MAX(run_len) FILTER (WHERE last_d >= v_today - INTERVAL '1 day'), 0)
  INTO v_day_best, v_day_current
  FROM runs;

  RETURN json_build_object(
    'weekly_session_streak_current', v_week_current,
    'weekly_session_streak_best',    v_week_best,
    'daily_call_streak_current',     v_day_current,
    'daily_call_streak_best',        v_day_best
  );
END;
$$;


ALTER FUNCTION "public"."get_user_streaks"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_user_streaks"("p_user_id" "uuid") IS 'Weekly session streak (consecutive ISO weeks with >=1 session) and daily call streak (consecutive user-local call_date values) for a user. Current weekly streak stays alive through this week if last session was this week or last week; current daily streak stays alive if the last call was today or yesterday. Applies sessions.deleted_at IS NULL. SECURITY DEFINER with search_path protection and self-read guard.';



CREATE OR REPLACE FUNCTION "public"."get_user_viral_coefficient"("p_user_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  total_sessions bigint;
  total_shares bigint;
  viral_coefficient numeric;
BEGIN
  -- Count user's public sessions
  SELECT COUNT(*)
  INTO total_sessions
  FROM sessions
  WHERE user_id = p_user_id
  AND status = 'completed'
  AND is_public = true;

  -- Return 0 if no sessions
  IF total_sessions = 0 THEN
    RETURN 0;
  END IF;

  -- Count total shares of user's sessions
  SELECT COUNT(*)
  INTO total_shares
  FROM session_shares ss
  INNER JOIN sessions s ON s.id = ss.session_id
  WHERE s.user_id = p_user_id;

  -- Calculate coefficient
  viral_coefficient := total_shares::numeric / total_sessions::numeric;

  RETURN ROUND(viral_coefficient, 2);
END;
$$;


ALTER FUNCTION "public"."get_user_viral_coefficient"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_user_viral_coefficient"("p_user_id" "uuid") IS 'Calculate viral coefficient (avg shares per session) for a user';



CREATE OR REPLACE FUNCTION "public"."get_week_scout_personalization"("p_user_id" "uuid", "p_beach_ids" "uuid"[], "p_slots" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_entitlement jsonb;
  v_matches jsonb := '[]'::jsonb;
BEGIN
  IF p_user_id IS NULL OR p_beach_ids IS NULL
    OR jsonb_typeof(p_slots) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Invalid Week Scout personalization input';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_slots) slot
    WHERE (slot->>'beach_id') IS NULL
      OR NOT ((slot->>'beach_id')::uuid = ANY(p_beach_ids))
      OR NULLIF(slot->>'forecast_at', '') IS NULL
  ) THEN
    RAISE EXCEPTION 'Match slots must belong to the requested beaches';
  END IF;

  SELECT jsonb_build_object(
    'is_pro', ue.is_pro, 'is_trialing', ue.is_trialing,
    'billing_issue', ue.billing_issue, 'expires_at', ue.expires_at
  ) INTO v_entitlement
  FROM public.user_entitlements ue WHERE ue.user_id = p_user_id;

  -- Mirror entitlementFromRow: paid/trial flags, expiry, and billing grace.
  -- Founding access scores matches too, except on billing-issue rows (which
  -- never get founding access); callers still decide what to show.
  IF jsonb_array_length(p_slots) > 0
    AND ((
      (COALESCE((v_entitlement->>'is_pro')::boolean, false)
        OR COALESCE((v_entitlement->>'is_trialing')::boolean, false))
      AND (COALESCE((v_entitlement->>'billing_issue')::boolean, false)
        OR v_entitlement->>'expires_at' IS NULL
        OR (v_entitlement->>'expires_at')::timestamptz >= clock_timestamp())
    ) OR (public.founding_access_enabled()
      AND NOT COALESCE((v_entitlement->>'billing_issue')::boolean, false))) THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'beach_id', m.beach_id, 'forecast_at', m.forecast_at, 'result', m.result
    ) ORDER BY m.slot_idx), '[]'::jsonb) INTO v_matches
    FROM public.compute_user_match_scores(p_user_id, p_beach_ids,
      (SELECT COALESCE(jsonb_agg(slot), '[]'::jsonb)
        FROM (SELECT DISTINCT value AS slot FROM jsonb_array_elements(p_slots)) slots)) m;
  END IF;

  RETURN jsonb_build_object(
    'entitlement', v_entitlement, 'matches', v_matches
  );
END;
$$;


ALTER FUNCTION "public"."get_week_scout_personalization"("p_user_id" "uuid", "p_beach_ids" "uuid"[], "p_slots" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_weekend_scout_candidates"("input_user_id" "uuid", "input_lat" double precision, "input_lon" double precision, "max_distance_meters" integer, "limit_count" integer DEFAULT 1000) RETURNS TABLE("id" "uuid", "distance_meters" double precision, "total_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  WITH origin AS (
    SELECT ST_SetSRID(ST_MakePoint(input_lon, input_lat), 4326)::geography AS geog
    WHERE input_lat BETWEEN -90 AND 90
      AND input_lon BETWEEN -180 AND 180
      AND max_distance_meters > 0
  ),
  eligible AS (
    SELECT b.id, ST_Distance(b.geog, origin.geog) AS distance_meters
    FROM public.beaches b
    CROSS JOIN origin
    WHERE b.geog IS NOT NULL
      AND b.is_private IS NOT TRUE
      AND b.recommendation_eligible
      AND b.deleted_at IS NULL
      AND ST_DWithin(b.geog, origin.geog, max_distance_meters)
      AND NOT EXISTS (
        SELECT 1
        FROM public.user_beach_exclusions ube
        WHERE ube.user_id = input_user_id
          AND ube.beach_id = b.id
      )
  ),
  counted AS (
    SELECT eligible.id, eligible.distance_meters, count(*) OVER () AS total_count
    FROM eligible
  )
  SELECT counted.id, counted.distance_meters, counted.total_count
  FROM counted
  ORDER BY counted.distance_meters ASC, counted.id ASC
  LIMIT LEAST(GREATEST(limit_count, 1), 1000);
$$;


ALTER FUNCTION "public"."get_weekend_scout_candidates"("input_user_id" "uuid", "input_lat" double precision, "input_lon" double precision, "max_distance_meters" integer, "limit_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_weekend_scout_candidates"("input_user_id" "uuid", "input_lat" double precision, "input_lon" double precision, "max_distance_meters" integer, "limit_count" integer) IS 'Returns recommendation-eligible, non-hidden beaches in current-location range, plus total count for truncation detection.';



CREATE OR REPLACE FUNCTION "public"."get_weekend_scout_candidates_page"("input_user_id" "uuid", "input_lat" double precision, "input_lon" double precision, "max_distance_meters" integer, "offset_count" integer DEFAULT 0, "limit_count" integer DEFAULT 500) RETURNS TABLE("id" "uuid", "distance_meters" double precision, "total_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  WITH origin AS (
    SELECT ST_SetSRID(ST_MakePoint(input_lon, input_lat), 4326)::geography AS geog
    WHERE input_lat BETWEEN -90 AND 90
      AND input_lon BETWEEN -180 AND 180
      AND max_distance_meters > 0
  ), eligible AS (
    SELECT b.id,
      ST_Distance(b.geog, origin.geog) AS distance_meters
    FROM public.beaches b
    CROSS JOIN origin
    WHERE b.is_private IS NOT TRUE
      AND b.deleted_at IS NULL
      AND b.recommendation_eligible
      AND b.geog IS NOT NULL
      AND ST_DWithin(b.geog, origin.geog, max_distance_meters)
      AND NOT EXISTS (
        SELECT 1 FROM public.user_beach_exclusions e
        WHERE e.user_id = input_user_id AND e.beach_id = b.id
      )
  ), counted AS (
    SELECT *, count(*) OVER () AS total_count FROM eligible
  )
  SELECT counted.id, counted.distance_meters, counted.total_count
  FROM counted
  ORDER BY counted.distance_meters ASC, counted.id ASC
  OFFSET GREATEST(offset_count, 0)
  LIMIT LEAST(GREATEST(limit_count, 1), 1000);
$$;


ALTER FUNCTION "public"."get_weekend_scout_candidates_page"("input_user_id" "uuid", "input_lat" double precision, "input_lon" double precision, "max_distance_meters" integer, "offset_count" integer, "limit_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_welcome_email_candidates"() RETURNS TABLE("user_id" "uuid", "email" "text", "created_at" timestamp with time zone, "email_confirmed_at" timestamp with time zone, "home_beach_id" "uuid", "case_type" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    p.id,
    p.email,
    p.created_at,
    au.email_confirmed_at,
    p.home_beach_id,
    CASE
      WHEN au.email_confirmed_at IS NULL AND p.created_at < NOW() - INTERVAL '24 hours'
        THEN 'unconfirmed_24h'
      WHEN au.email_confirmed_at IS NOT NULL AND p.home_beach_id IS NULL
        AND p.created_at < NOW() - INTERVAL '48 hours'
        THEN 'no_home_beach_48h'
    END AS case_type
  FROM profiles p
  JOIN auth.users au ON au.id = p.id
  LEFT JOIN email_send_log esl ON esl.user_id = p.id AND esl.email_type = 'welcome'
  WHERE p.is_mock = false
    AND p.email IS NOT NULL
    AND esl.id IS NULL
    AND (
      (au.email_confirmed_at IS NULL AND p.created_at < NOW() - INTERVAL '24 hours')
      OR
      (au.email_confirmed_at IS NOT NULL AND p.home_beach_id IS NULL AND p.created_at < NOW() - INTERVAL '48 hours')
    );
END;
$$;


ALTER FUNCTION "public"."get_welcome_email_candidates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_worst_performing_beaches"("limit_count" integer DEFAULT 10) RETURNS TABLE("beach_id" "uuid", "beach_name" "text", "predictions_matched" bigint, "improvement_rate_pct" numeric, "mae_improvement_pct" numeric, "raw_mae" numeric, "corrected_mae" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    beach_id, beach_name, predictions_matched,
    improvement_rate_pct, mae_improvement_pct, raw_mae, corrected_mae
  FROM beach_ml_performance_baseline
  WHERE predictions_matched >= 10
  ORDER BY improvement_rate_pct ASC NULLS LAST
  LIMIT limit_count;
$$;


