CREATE OR REPLACE FUNCTION "public"."get_yesterday_accuracy"("p_beach_id" "uuid") RETURNS TABLE("beach_id" "uuid", "forecast_date" "date", "avg_predicted_m" numeric, "avg_observed_m" numeric, "mae_m" numeric, "relative_error_pct" numeric, "observation_count" integer, "should_display" boolean)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_tz TEXT;
  v_start TIMESTAMPTZ;
  v_end TIMESTAMPTZ;
BEGIN
  SELECT COALESCE(b.timezone, 'America/Los_Angeles') INTO v_tz
  FROM beaches b WHERE b.id = p_beach_id;

  IF v_tz IS NULL THEN
    v_tz := 'America/Los_Angeles';
  END IF;

  v_start := (CURRENT_DATE AT TIME ZONE v_tz - INTERVAL '1 day') AT TIME ZONE v_tz;
  v_end := (CURRENT_DATE AT TIME ZONE v_tz) AT TIME ZONE v_tz;

  RETURN QUERY
  SELECT
    p.beach_id,
    (v_start AT TIME ZONE v_tz)::date AS forecast_date,
    ROUND(AVG(p.corrected_forecast_m)::numeric, 2) AS avg_predicted_m,
    ROUND(AVG(p.observed_m)::numeric, 2) AS avg_observed_m,
    ROUND(AVG(ABS(p.corrected_error_m))::numeric, 2) AS mae_m,
    LEAST(
      ROUND(
        AVG(
          CASE WHEN ABS(p.observed_m) > 0
          THEN ABS(p.corrected_error_m) / ABS(p.observed_m) * 100
          ELSE NULL END
        )::numeric, 1
      ),
      999
    ) AS relative_error_pct,
    COUNT(*)::integer AS observation_count,
    NOT (
      AVG(ABS(p.corrected_error_m)) > 0.45
      OR COALESCE(AVG(
        CASE WHEN ABS(p.observed_m) > 0
        THEN ABS(p.corrected_error_m) / ABS(p.observed_m)
        ELSE NULL END
      ), 0) > 0.40
    ) AND AVG(p.observed_m) >= 0.3 AS should_display
  FROM ml_predictions_log p
  WHERE p.beach_id = p_beach_id
    AND p.predicted_at >= v_start
    AND p.predicted_at < v_end
    AND p.observed_m > 0
  GROUP BY p.beach_id;
END;
$$;


ALTER FUNCTION "public"."get_yesterday_accuracy"("p_beach_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_yesterday_accuracy"("p_beach_id" "uuid") IS 'Returns forecast accuracy metrics for yesterday at the given beach.
Uses ml_predictions_log with observed ground truth from IOOS buoys.
should_display is false when accuracy is poor (>0.45m MAE OR >40% relative) or waves too small (<0.3m).';



CREATE OR REPLACE FUNCTION "public"."gmail_reply_known"("p_message_ids" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce(array_agg(input.message_id ORDER BY input.ordinality), '{}'::text[])
  FROM unnest(coalesce(p_message_ids, '{}'::text[])) WITH ORDINALITY AS input(message_id, ordinality)
  WHERE NOT EXISTS (
    SELECT 1 FROM public.email_reply_events e
    WHERE e.provider_id LIKE 'gmail:%:' || input.message_id
  );
$$;


ALTER FUNCTION "public"."gmail_reply_known"("p_message_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_swell_watch_evaluation_policy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'evaluation policies are append only'; END IF;
  -- Same lock as detection prevents a policy change during identity selection.
  PERFORM pg_advisory_xact_lock(hashtextextended('swell-watch-control',0));
  IF NEW.epoch <> coalesce((SELECT max(epoch) FROM public.swell_watch_evaluation_policies),0)+1 THEN
    RAISE EXCEPTION 'evaluation policy epoch must advance by one';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_swell_watch_evaluation_policy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_swell_watch_study_authority"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE canonical jsonb;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'study authority is append only'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('swell-watch-control',0));
  IF NEW.epoch<>coalesce((SELECT max(epoch) FROM public.swell_watch_study_authorities),0)+1 THEN
    RAISE EXCEPTION 'study authority epoch must advance by one';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.cohort) s WHERE
    jsonb_typeof(s) IS DISTINCT FROM 'object' OR s-'sourcePointId'-'regionKey'<>'{}'::jsonb
    OR coalesce(s->>'sourcePointId','') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
    OR jsonb_typeof(s->'regionKey') IS DISTINCT FROM 'string'
    OR char_length(btrim(s->>'regionKey')) NOT BETWEEN 1 AND 100
    OR s->>'regionKey' IS DISTINCT FROM btrim(s->>'regionKey'))
    OR (SELECT count(DISTINCT s->>'sourcePointId') FROM jsonb_array_elements(NEW.cohort) s)<>10 THEN
    RAISE EXCEPTION 'invalid study cohort';
  END IF;
  SELECT jsonb_agg(s ORDER BY s->>'sourcePointId') INTO canonical FROM jsonb_array_elements(NEW.cohort) s;
  IF NEW.state='active' THEN
    PERFORM 1 FROM public.beaches b WHERE b.id IN (SELECT (s->>'sourcePointId')::uuid FROM jsonb_array_elements(NEW.cohort) s)
      ORDER BY b.id FOR SHARE;
    IF NEW.scope_inputs IS DISTINCT FROM public.swell_watch_study_scope_inputs(NEW.cohort) THEN
      RAISE EXCEPTION 'study scope inputs differ from current beaches';
    END IF;
  END IF;
  IF canonical IS DISTINCT FROM NEW.cohort OR NEW.config_hash IS DISTINCT FROM
    encode(extensions.digest((jsonb_build_object('policyHash',NEW.policy_hash,'cohort',NEW.cohort,'scopeInputs',NEW.scope_inputs,
      'forecastDays',7,'targetDays',NEW.target_days,'providerContractRef',NEW.provider_contract_ref,'evidenceSha256',NEW.evidence_sha256) || CASE WHEN NEW.qualification_rule='complete_partitions.v1' THEN '{}'::jsonb
      ELSE jsonb_build_object('qualificationRule',NEW.qualification_rule) END)::text,'sha256'),'hex') THEN
    RAISE EXCEPTION 'study config hash or cohort ordering mismatch';
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."guard_swell_watch_study_authority"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_swell_watch_study_beach_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE authority public.swell_watch_study_authorities;
BEGIN
  IF OLD.lat IS NOT DISTINCT FROM NEW.lat AND OLD.lon IS NOT DISTINCT FROM NEW.lon
    AND OLD.swell_window_center_deg IS NOT DISTINCT FROM NEW.swell_window_center_deg
    AND OLD.swell_window_halfwidth_deg IS NOT DISTINCT FROM NEW.swell_window_halfwidth_deg
    AND OLD.swell_access_factors IS NOT DISTINCT FROM NEW.swell_access_factors
    AND OLD.terrain_enabled IS NOT DISTINCT FROM NEW.terrain_enabled
    AND OLD.deepwater_decay_factor IS NOT DISTINCT FROM NEW.deepwater_decay_factor
    AND OLD.shoaling_factors IS NOT DISTINCT FROM NEW.shoaling_factors THEN RETURN NEW; END IF;
  SELECT * INTO authority FROM public.swell_watch_study_authorities WHERE epoch=(SELECT max(epoch) FROM public.swell_watch_study_authorities) AND state='active' AND clock_timestamp()>=not_before AND clock_timestamp()<expires_at;
  IF FOUND AND EXISTS(SELECT 1 FROM jsonb_array_elements(authority.cohort) cohort WHERE (cohort->>'sourcePointId')::uuid=NEW.id) THEN
    RAISE EXCEPTION 'beach % is pinned by the active Swell Watch study (epoch %); change it through a reviewed study authority epoch',NEW.id,authority.epoch;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_swell_watch_study_beach_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_swell_watch_study_observation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.provider_batch_id IS NOT NULL AND EXISTS(
    SELECT 1 FROM public.swell_watch_provider_run_completed_batches b
    JOIN public.swell_watch_study_acceptances s ON s.revision_set_id=b.revision_set_id WHERE b.id=NEW.provider_batch_id) THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('swell-watch-control',0));
    IF public.swell_watch_provider_evidence_is_current(NEW.provider_batch_id) IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'current study evidence required';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_swell_watch_study_observation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_location_data jsonb;
  v_signup_context jsonb;
  v_location text;
  v_home_region text;
  v_timezone text;
  v_profile_name text;
  v_display_name text;
BEGIN
  v_location_data := NEW.raw_user_meta_data->'location_data';
  v_signup_context := NEW.raw_user_meta_data->'signup_context';

  IF v_location_data IS NOT NULL
     AND v_location_data->>'city' IS NOT NULL
     AND v_location_data->>'region' IS NOT NULL THEN
    v_location := v_location_data->>'city' || ', ' || v_location_data->>'region';
  END IF;

  v_home_region := v_location_data->>'region';
  v_timezone := v_signup_context->>'tz';
  v_profile_name := COALESCE(
    NULLIF(BTRIM(NEW.raw_user_meta_data->>'display_name'), ''),
    NULLIF(BTRIM(NEW.raw_user_meta_data->>'full_name'), ''),
    NULLIF(BTRIM(NEW.raw_user_meta_data->>'name'), '')
  );
  v_display_name := v_profile_name;

  IF v_display_name IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM public.profiles p
       WHERE p.display_name = v_display_name
         AND p.id <> NEW.id
     ) THEN
    v_display_name := NULL;
  END IF;

  INSERT INTO public.profiles (
    id,
    email,
    full_name,
    display_name,
    avatar_url,
    location,
    home_region,
    timezone,
    signup_context,
    signup_location,
    created_at,
    updated_at
  )
  VALUES (
    NEW.id,
    NEW.email,
    v_profile_name,
    v_display_name,
    NEW.raw_user_meta_data->>'avatar_url',
    v_location,
    v_home_region,
    v_timezone,
    v_signup_context,
    v_location_data,
    NOW(),
    NOW()
  )
  ON CONFLICT (id) DO UPDATE SET
    email = CASE
      WHEN NULLIF(BTRIM(profiles.email), '') IS NULL THEN EXCLUDED.email
      ELSE profiles.email
    END,
    full_name = CASE
      WHEN NULLIF(BTRIM(profiles.full_name), '') IS NULL THEN EXCLUDED.full_name
      ELSE profiles.full_name
    END,
    display_name = CASE
      WHEN NULLIF(BTRIM(profiles.display_name), '') IS NULL THEN EXCLUDED.display_name
      ELSE profiles.display_name
    END,
    location = COALESCE(profiles.location, EXCLUDED.location),
    home_region = COALESCE(profiles.home_region, EXCLUDED.home_region),
    timezone = COALESCE(profiles.timezone, EXCLUDED.timezone),
    signup_context = COALESCE(profiles.signup_context, EXCLUDED.signup_context),
    signup_location = COALESCE(profiles.signup_location, EXCLUDED.signup_location),
    updated_at = NOW();

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'Failed to create profile for user %: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."handle_new_user"() IS 'Creates or self-heals a profile when an auth user signs up. Normalizes display_name, full_name, and name metadata without overwriting user-set names.';



CREATE OR REPLACE FUNCTION "public"."has_user_block_between"("a" "uuid", "b" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    a IS NOT NULL
    AND b IS NOT NULL
    AND a <> b
    AND EXISTS (
      SELECT 1
      FROM public.user_blocks ub
      WHERE (ub.blocker_id = a AND ub.blocked_id = b)
         OR (ub.blocker_id = b AND ub.blocked_id = a)
    );
$$;


ALTER FUNCTION "public"."has_user_block_between"("a" "uuid", "b" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hold_community_spot_photo_v1"("p_photo_id" "uuid", "p_actor_id" "uuid", "p_reason" "text", "p_idempotency_key" "uuid") RETURNS TABLE("hold_id" "uuid", "reason" "text", "placed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  new_hold_id uuid;
  new_placed_at timestamptz;
  previous_action text;
  photo_lifecycle text;
BEGIN
  SELECT e.action INTO previous_action
  FROM public.community_photo_moderation_events e
  WHERE e.actor_id = p_actor_id AND e.idempotency_key = p_idempotency_key;
  IF previous_action IS NOT NULL THEN
    IF previous_action <> 'admin_hold' THEN RAISE EXCEPTION 'idempotency_conflict'; END IF;
    RETURN QUERY
    SELECT h.id, h.reason, h.placed_at
    FROM public.community_photo_investigation_holds h
    WHERE h.photo_id = p_photo_id AND h.released_at IS NULL;
    RETURN;
  END IF;
  IF char_length(p_reason) NOT BETWEEN 1 AND 280 THEN
    RAISE EXCEPTION 'invalid_request';
  END IF;
  SELECT p.lifecycle_status INTO photo_lifecycle
  FROM public.community_spot_photos p
  WHERE p.id = p_photo_id AND p.processing_status = 'ready'
  FOR UPDATE;
  IF photo_lifecycle IS NULL OR photo_lifecycle NOT IN ('active', 'removed') THEN
    RAISE EXCEPTION 'photo_not_found';
  END IF;
  INSERT INTO public.community_photo_investigation_holds (
    photo_id, reason, placed_by
  ) VALUES (p_photo_id, p_reason, p_actor_id)
  ON CONFLICT (photo_id) WHERE released_at IS NULL DO UPDATE
  SET reason = EXCLUDED.reason, placed_by = EXCLUDED.placed_by, placed_at = now()
  RETURNING id, community_photo_investigation_holds.placed_at
  INTO new_hold_id, new_placed_at;
  INSERT INTO public.community_photo_moderation_events (
    photo_id, actor_id, action, reason, idempotency_key
  ) VALUES (
    p_photo_id, p_actor_id, 'admin_hold', p_reason, p_idempotency_key
  );
  RETURN QUERY SELECT new_hold_id, p_reason, new_placed_at;
END;
$$;


ALTER FUNCTION "public"."hold_community_spot_photo_v1"("p_photo_id" "uuid", "p_actor_id" "uuid", "p_reason" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


