CREATE OR REPLACE FUNCTION "public"."parse_numeric_from_text"("input" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
  SELECT COALESCE(
    (regexp_match(input, '(-?\d+\.?\d*)'))[1]::numeric,
    0
  );
$$;


ALTER FUNCTION "public"."parse_numeric_from_text"("input" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."parse_numeric_or_null"("input" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  SELECT (regexp_match(input, '(-?\d+\.?\d*)'))[1]::numeric;
$$;


ALTER FUNCTION "public"."parse_numeric_or_null"("input" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."parse_numeric_or_null"("input" "text") IS 'First number in a forecast string ("-1.2 ft" -> -1.2); NULL when there is none, unlike parse_numeric_from_text.';



CREATE OR REPLACE FUNCTION "public"."parse_wave_height_midpoint_ft"("p_raw" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
DECLARE token text[]; height double precision; lo double precision; hi double precision;
BEGIN
  FOR token IN SELECT regexp_matches(p_raw, '[0-9.]+', 'g') LOOP
    -- Number() discards malformed decimal tokens and non-finite values.
    IF token[1] !~ '^([0-9]+([.][0-9]*)?|[.][0-9]+)$' THEN CONTINUE; END IF;
    BEGIN
      height := token[1]::double precision;
    EXCEPTION WHEN numeric_value_out_of_range THEN
      -- JavaScript underflows tiny positive numbers to zero; PostgreSQL throws.
      IF token[1] ~ '^0*[.]' THEN height := 0; ELSE CONTINUE; END IF;
    END;
    lo := least(lo,height);
    hi := greatest(hi,height);
  END LOOP;
  BEGIN
    RETURN ((lo+hi)/2)::numeric;
  EXCEPTION WHEN numeric_value_out_of_range THEN
    IF hi < 1 THEN RETURN 0; END IF;
    RETURN 'Infinity'::numeric;
  END;
END;
$_$;


ALTER FUNCTION "public"."parse_wave_height_midpoint_ft"("p_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."persist_trusted_forecast_build"("p_payload" "jsonb") RETURNS SETOF "public"."trusted_forecast_build_receipts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  c_top_level_keys CONSTANT text[] := ARRAY[
    'schemaVersion',
    'policyVersion',
    'buildKey',
    'buildAnchorAt',
    'decisions',
    'applications',
    'alerts',
    'snapshots',
    'expectedDecisionCount',
    'expectedApplicationCount',
    'expectedAlertCount',
    'expectedSnapshotCount'
  ];
  c_decision_keys CONSTANT text[] := ARRAY[
    'beachId',
    'localDate',
    'localTimezone',
    'status',
    'primaryIssueId',
    'baselineMaxFaceFt',
    'trustedMinFaceFt',
    'trustedMaxFaceFt',
    'signedGapFt',
    'appliedDeltaFt'
  ];
  c_application_keys CONSTANT text[] := ARRAY[
    'beachId',
    'localDate',
    'forecastAt',
    'forecastHorizonBucket',
    'displaySource',
    'appliedDeltaFt',
    'baselineMaxFaceFt',
    'adjustedMaxFaceFt'
  ];
  c_alert_keys CONSTANT text[] := ARRAY[
    'beachId',
    'localDate',
    'alertCode',
    'separationFt',
    'primaryIssueId',
    'conflictingIssueId',
    'evidence'
  ];
  c_snapshot_keys CONSTANT text[] := public.trusted_forecast_snapshot_columns();

  v_build_key text;
  v_schema_version text;
  v_policy_version text;
  v_build_anchor_at timestamptz;
  v_expected_decision_count integer;
  v_expected_application_count integer;
  v_expected_alert_count integer;
  v_expected_snapshot_count integer;

  v_canonical jsonb;
  v_payload_sha256 text;
  v_existing public.trusted_forecast_build_receipts%ROWTYPE;
  v_receipt public.trusted_forecast_build_receipts%ROWTYPE;

  v_element jsonb;
  v_decision public.trusted_forecast_decisions%ROWTYPE;
  v_decision_id uuid;
  v_application public.trusted_forecast_applications%ROWTYPE;
  v_snapshot_id uuid;

  v_inserted_decision_count integer := 0;
  v_reused_decision_count integer := 0;
  v_inserted_application_count integer := 0;
  v_reused_application_count integer := 0;
  v_inserted_alert_count integer := 0;
  v_reused_alert_count integer := 0;
  v_inserted_snapshot_count integer := 0;
  v_reused_snapshot_count integer := 0;
  v_durable_alert_count integer := 0;
BEGIN
  -- ---------------------------------------------------------------------
  -- 1. Strict input contract. Everything here runs before any durable write.
  -- ---------------------------------------------------------------------
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'trusted forecast build payload must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_object_keys(p_payload) AS supplied(key)
    WHERE supplied.key <> ALL (c_top_level_keys)
  ) THEN
    RAISE EXCEPTION 'trusted forecast build payload contains an unsupported field'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(c_top_level_keys) AS required(key)
    WHERE NOT (p_payload ? required.key)
  ) THEN
    RAISE EXCEPTION 'trusted forecast build payload is missing a required field'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(p_payload -> 'buildKey') <> 'string'
     OR length(p_payload ->> 'buildKey') = 0
     OR length(p_payload ->> 'buildKey') > 200 THEN
    RAISE EXCEPTION 'trusted forecast build key must be a non-empty string'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(p_payload -> 'schemaVersion') <> 'string'
     OR jsonb_typeof(p_payload -> 'policyVersion') <> 'string'
     OR jsonb_typeof(p_payload -> 'buildAnchorAt') <> 'string' THEN
    RAISE EXCEPTION
      'trusted forecast build versions and anchor must be strings'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(p_payload -> 'decisions') <> 'array'
     OR jsonb_typeof(p_payload -> 'applications') <> 'array'
     OR jsonb_typeof(p_payload -> 'alerts') <> 'array'
     OR jsonb_typeof(p_payload -> 'snapshots') <> 'array' THEN
    RAISE EXCEPTION 'trusted forecast build collections must be JSON arrays'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(p_payload -> 'expectedDecisionCount') <> 'number'
     OR jsonb_typeof(p_payload -> 'expectedApplicationCount') <> 'number'
     OR jsonb_typeof(p_payload -> 'expectedAlertCount') <> 'number'
     OR jsonb_typeof(p_payload -> 'expectedSnapshotCount') <> 'number' THEN
    RAISE EXCEPTION 'trusted forecast build counts must be numbers'
      USING ERRCODE = '22023';
  END IF;

  v_build_key := p_payload ->> 'buildKey';
  v_schema_version := p_payload ->> 'schemaVersion';
  v_policy_version := p_payload ->> 'policyVersion';
  v_build_anchor_at := (p_payload ->> 'buildAnchorAt')::timestamptz;
  v_expected_decision_count := (p_payload ->> 'expectedDecisionCount')::integer;
  v_expected_application_count :=
    (p_payload ->> 'expectedApplicationCount')::integer;
  v_expected_alert_count := (p_payload ->> 'expectedAlertCount')::integer;
  v_expected_snapshot_count := (p_payload ->> 'expectedSnapshotCount')::integer;

  IF v_expected_decision_count
       <> jsonb_array_length(p_payload -> 'decisions')
     OR v_expected_application_count
       <> jsonb_array_length(p_payload -> 'applications')
     OR v_expected_alert_count <> jsonb_array_length(p_payload -> 'alerts')
     OR v_expected_snapshot_count
       <> jsonb_array_length(p_payload -> 'snapshots') THEN
    RAISE EXCEPTION
      'trusted forecast build counts do not match the supplied collections'
      USING ERRCODE = '22023';
  END IF;

  FOR v_element IN
    SELECT element FROM jsonb_array_elements(p_payload -> 'decisions') AS element
  LOOP
    IF jsonb_typeof(v_element) <> 'object'
       OR EXISTS (
         SELECT 1
         FROM jsonb_object_keys(v_element) AS supplied(key)
         WHERE supplied.key <> ALL (c_decision_keys)
       )
       OR EXISTS (
         SELECT 1
         FROM unnest(c_decision_keys) AS required(key)
         WHERE NOT (v_element ? required.key)
       ) THEN
      RAISE EXCEPTION 'trusted forecast decision has an invalid field set'
        USING ERRCODE = '22023';
    END IF;
  END LOOP;

  FOR v_element IN
    SELECT element
    FROM jsonb_array_elements(p_payload -> 'applications') AS element
  LOOP
    IF jsonb_typeof(v_element) <> 'object'
       OR EXISTS (
         SELECT 1
         FROM jsonb_object_keys(v_element) AS supplied(key)
         WHERE supplied.key <> ALL (c_application_keys)
       )
       OR EXISTS (
         SELECT 1
         FROM unnest(c_application_keys) AS required(key)
         WHERE NOT (v_element ? required.key)
       ) THEN
      RAISE EXCEPTION 'trusted forecast application has an invalid field set'
        USING ERRCODE = '22023';
    END IF;
  END LOOP;

  FOR v_element IN
    SELECT element FROM jsonb_array_elements(p_payload -> 'alerts') AS element
  LOOP
    IF jsonb_typeof(v_element) <> 'object'
       OR EXISTS (
         SELECT 1
         FROM jsonb_object_keys(v_element) AS supplied(key)
         WHERE supplied.key <> ALL (c_alert_keys)
       )
       OR EXISTS (
         SELECT 1
         FROM unnest(c_alert_keys) AS required(key)
         WHERE NOT (v_element ? required.key)
       ) THEN
      RAISE EXCEPTION 'trusted forecast alert has an invalid field set'
        USING ERRCODE = '22023';
    END IF;
  END LOOP;

  FOR v_element IN
    SELECT element FROM jsonb_array_elements(p_payload -> 'snapshots') AS element
  LOOP
    IF jsonb_typeof(v_element) <> 'object'
       OR EXISTS (
         SELECT 1
         FROM jsonb_object_keys(v_element) AS supplied(key)
         WHERE supplied.key <> ALL (c_snapshot_keys)
       )
       OR NOT (v_element ? 'beach_id')
       OR NOT (v_element ? 'predicted_at') THEN
      RAISE EXCEPTION 'trusted forecast snapshot has an invalid field set'
        USING ERRCODE = '22023';
    END IF;
  END LOOP;

  -- ---------------------------------------------------------------------
  -- 2. Serialize concurrent builds for this build key.
  -- ---------------------------------------------------------------------
  PERFORM pg_advisory_xact_lock(
    hashtextextended('trusted-forecast-build:' || v_build_key, 0)
  );

  -- ---------------------------------------------------------------------
  -- 3. Database-owned canonical content and SHA-256. A caller-supplied hash
  --    is impossible: 'payloadSha256' is not an accepted input key.
  -- ---------------------------------------------------------------------
  v_canonical := public.trusted_forecast_canonical_build_payload(p_payload);
  v_payload_sha256 := encode(
    pg_catalog.sha256(convert_to(v_canonical::text, 'UTF8')),
    'hex'
  );

  SELECT *
  INTO v_existing
  FROM public.trusted_forecast_build_receipts
  WHERE build_key = v_build_key;

  IF FOUND THEN
    IF v_existing.payload_sha256 <> v_payload_sha256
       OR v_existing.expected_decision_count <> v_expected_decision_count
       OR v_existing.expected_application_count <> v_expected_application_count
       OR v_existing.expected_alert_count <> v_expected_alert_count
       OR v_existing.expected_snapshot_count <> v_expected_snapshot_count THEN
      RAISE EXCEPTION 'trusted forecast build idempotency collision'
        USING ERRCODE = '23505';
    END IF;
    RETURN NEXT v_existing;
    RETURN;
  END IF;

  -- ---------------------------------------------------------------------
  -- 4. Daily decisions: insert once, otherwise reuse the existing row for
  --    that (beach, local day). Divergent content is a hard collision.
  -- ---------------------------------------------------------------------
  FOR v_element IN
    SELECT element FROM jsonb_array_elements(p_payload -> 'decisions') AS element
  LOOP
    SELECT *
    INTO v_decision
    FROM public.trusted_forecast_decisions
    WHERE beach_id = (v_element ->> 'beachId')::uuid
      AND local_date = (v_element ->> 'localDate')::date;

    IF FOUND THEN
      IF v_decision.local_timezone
           IS DISTINCT FROM (v_element ->> 'localTimezone')
         OR v_decision.status IS DISTINCT FROM (v_element ->> 'status')
         OR v_decision.primary_issue_id
           IS DISTINCT FROM (v_element ->> 'primaryIssueId')::uuid
         OR v_decision.baseline_max_face_ft
           IS DISTINCT FROM (v_element ->> 'baselineMaxFaceFt')::numeric
         OR v_decision.trusted_min_face_ft
           IS DISTINCT FROM (v_element ->> 'trustedMinFaceFt')::numeric
         OR v_decision.trusted_max_face_ft
           IS DISTINCT FROM (v_element ->> 'trustedMaxFaceFt')::numeric
         OR v_decision.signed_gap_ft
           IS DISTINCT FROM (v_element ->> 'signedGapFt')::numeric
         OR v_decision.applied_delta_ft
           IS DISTINCT FROM (v_element ->> 'appliedDeltaFt')::numeric THEN
        RAISE EXCEPTION
          'trusted forecast daily decision collision for beach % on %',
          v_element ->> 'beachId', v_element ->> 'localDate'
          USING ERRCODE = '23505';
      END IF;
      v_reused_decision_count := v_reused_decision_count + 1;
    ELSE
      INSERT INTO public.trusted_forecast_decisions (
        beach_id,
        local_date,
        local_timezone,
        status,
        primary_issue_id,
        baseline_max_face_ft,
        trusted_min_face_ft,
        trusted_max_face_ft,
        signed_gap_ft,
        applied_delta_ft,
        policy_version,
        build_key
      ) VALUES (
        (v_element ->> 'beachId')::uuid,
        (v_element ->> 'localDate')::date,
        v_element ->> 'localTimezone',
        v_element ->> 'status',
        (v_element ->> 'primaryIssueId')::uuid,
        (v_element ->> 'baselineMaxFaceFt')::numeric,
        (v_element ->> 'trustedMinFaceFt')::numeric,
        (v_element ->> 'trustedMaxFaceFt')::numeric,
        (v_element ->> 'signedGapFt')::numeric,
        (v_element ->> 'appliedDeltaFt')::numeric,
        v_policy_version,
        v_build_key
      );
      v_inserted_decision_count := v_inserted_decision_count + 1;
    END IF;
  END LOOP;

  -- ---------------------------------------------------------------------
  -- 5. First-write snapshots. ON CONFLICT DO NOTHING against the live
  --    unique index (beach_id, predicted_at, forecast_horizon_bucket,
  --    display_source) NULLS NOT DISTINCT, so an existing row is never
  --    updated. D-18 first-write-wins.
  -- ---------------------------------------------------------------------
  IF v_expected_snapshot_count > 0 THEN
    WITH source AS (
      SELECT *
      FROM jsonb_to_recordset(p_payload -> 'snapshots') AS snapshot(
        beach_id uuid,
        predicted_at timestamptz,
        forecast_horizon_hours integer,
        forecast_horizon_bucket text,
        raw_display_height_m double precision,
        offset_corrected_display_height_m double precision,
        height_offset_m double precision,
        height_offset_sample_count integer,
        feedback_height_calibration_candidate_id uuid,
        feedback_height_offset_ft double precision,
        feedback_height_calibration_applied boolean,
        display_source text,
        display_wave_source text,
        display_raw_input_height_m double precision,
        display_replay_context jsonb,
        model_version text,
        wave_height_om double precision,
        noaa_swell_1_height_m double precision,
        noaa_swell_1_period_s double precision,
        noaa_swell_1_direction_deg double precision,
        noaa_swell_2_height_m double precision,
        noaa_swell_2_period_s double precision,
        noaa_swell_2_direction_deg double precision,
        noaa_wind_wave_height_m double precision,
        noaa_wind_wave_period_s double precision,
        noaa_wind_wave_direction_deg double precision,
        wave_period_s double precision,
        wave_direction_deg double precision,
        wave_period_om double precision,
        wave_direction_om double precision,
        wave_peak_period_om double precision,
        swell_height_om double precision,
        swell_period_om double precision,
        swell_direction_om double precision,
        swell_wave_peak_period_om double precision,
        wind_wave_height_om double precision,
        wind_wave_period_om double precision,
        wind_wave_direction_om double precision,
        wind_wave_peak_period_om double precision,
        secondary_swell_height_om double precision,
        secondary_swell_period_om double precision,
        secondary_swell_direction_om double precision,
        tertiary_swell_height_om double precision,
        tertiary_swell_period_om double precision,
        tertiary_swell_direction_om double precision,
        om_wind_wave_missing boolean,
        om_primary_swell_missing boolean,
        om_secondary_swell_missing boolean,
        om_tertiary_swell_missing boolean,
        om_partition_schema_version integer,
        wind_speed_ms double precision,
        wind_direction_deg double precision,
        v5_shadow_height_m double precision,
        v5_model_version text,
        direction_bucket text,
        om_bucket text
      )
    ), inserted AS (
      INSERT INTO public.ml_predictions_log (
        beach_id,
        predicted_at,
        forecast_horizon_hours,
        forecast_horizon_bucket,
        raw_display_height_m,
        offset_corrected_display_height_m,
        height_offset_m,
        height_offset_sample_count,
        feedback_height_calibration_candidate_id,
        feedback_height_offset_ft,
        feedback_height_calibration_applied,
        display_source,
        display_wave_source,
        display_raw_input_height_m,
        display_replay_context,
        model_version,
        wave_height_om,
        noaa_swell_1_height_m,
        noaa_swell_1_period_s,
        noaa_swell_1_direction_deg,
        noaa_swell_2_height_m,
        noaa_swell_2_period_s,
        noaa_swell_2_direction_deg,
        noaa_wind_wave_height_m,
        noaa_wind_wave_period_s,
        noaa_wind_wave_direction_deg,
        wave_period_s,
        wave_direction_deg,
        wave_period_om,
        wave_direction_om,
        wave_peak_period_om,
        swell_height_om,
        swell_period_om,
        swell_direction_om,
        swell_wave_peak_period_om,
        wind_wave_height_om,
        wind_wave_period_om,
        wind_wave_direction_om,
        wind_wave_peak_period_om,
        secondary_swell_height_om,
        secondary_swell_period_om,
        secondary_swell_direction_om,
        tertiary_swell_height_om,
        tertiary_swell_period_om,
        tertiary_swell_direction_om,
        om_wind_wave_missing,
        om_primary_swell_missing,
        om_secondary_swell_missing,
        om_tertiary_swell_missing,
        om_partition_schema_version,
        wind_speed_ms,
        wind_direction_deg,
        v5_shadow_height_m,
        v5_model_version,
        direction_bucket,
        om_bucket
      )
      SELECT
        source.beach_id,
        source.predicted_at,
        source.forecast_horizon_hours,
        source.forecast_horizon_bucket,
        source.raw_display_height_m,
        source.offset_corrected_display_height_m,
        source.height_offset_m,
        source.height_offset_sample_count,
        source.feedback_height_calibration_candidate_id,
        source.feedback_height_offset_ft,
        coalesce(source.feedback_height_calibration_applied, false),
        source.display_source,
        source.display_wave_source,
        source.display_raw_input_height_m,
        source.display_replay_context,
        coalesce(source.model_version, source.display_source),
        source.wave_height_om,
        source.noaa_swell_1_height_m,
        source.noaa_swell_1_period_s,
        source.noaa_swell_1_direction_deg,
        source.noaa_swell_2_height_m,
        source.noaa_swell_2_period_s,
        source.noaa_swell_2_direction_deg,
        source.noaa_wind_wave_height_m,
        source.noaa_wind_wave_period_s,
        source.noaa_wind_wave_direction_deg,
        source.wave_period_s,
        source.wave_direction_deg,
        source.wave_period_om,
        source.wave_direction_om,
        source.wave_peak_period_om,
        source.swell_height_om,
        source.swell_period_om,
        source.swell_direction_om,
        source.swell_wave_peak_period_om,
        source.wind_wave_height_om,
        source.wind_wave_period_om,
        source.wind_wave_direction_om,
        source.wind_wave_peak_period_om,
        source.secondary_swell_height_om,
        source.secondary_swell_period_om,
        source.secondary_swell_direction_om,
        source.tertiary_swell_height_om,
        source.tertiary_swell_period_om,
        source.tertiary_swell_direction_om,
        source.om_wind_wave_missing,
        source.om_primary_swell_missing,
        source.om_secondary_swell_missing,
        source.om_tertiary_swell_missing,
        source.om_partition_schema_version,
        source.wind_speed_ms,
        source.wind_direction_deg,
        source.v5_shadow_height_m,
        source.v5_model_version,
        source.direction_bucket,
        source.om_bucket
      FROM source
      ON CONFLICT (
        beach_id,
        predicted_at,
        forecast_horizon_bucket,
        display_source
      ) DO NOTHING
      RETURNING 1
    )
    SELECT count(*)::integer INTO v_inserted_snapshot_count FROM inserted;

    v_reused_snapshot_count :=
      v_expected_snapshot_count - v_inserted_snapshot_count;
  END IF;

  -- ---------------------------------------------------------------------
  -- 6. Slot applications. Exactly one decision may claim a forecast slot.
  -- ---------------------------------------------------------------------
  FOR v_element IN
    SELECT element
    FROM jsonb_array_elements(p_payload -> 'applications') AS element
  LOOP
    SELECT decision_id
    INTO v_decision_id
    FROM public.trusted_forecast_decisions
    WHERE beach_id = (v_element ->> 'beachId')::uuid
      AND local_date = (v_element ->> 'localDate')::date;

    IF v_decision_id IS NULL THEN
      RAISE EXCEPTION
        'trusted forecast application has no daily decision for beach % on %',
        v_element ->> 'beachId', v_element ->> 'localDate'
        USING ERRCODE = '23503';
    END IF;

    SELECT id
    INTO v_snapshot_id
    FROM public.ml_predictions_log
    WHERE beach_id = (v_element ->> 'beachId')::uuid
      AND predicted_at = (v_element ->> 'forecastAt')::timestamptz
      AND forecast_horizon_bucket = (v_element ->> 'forecastHorizonBucket')
      AND display_source = (v_element ->> 'displaySource')
    LIMIT 1;

    SELECT *
    INTO v_application
    FROM public.trusted_forecast_applications
    WHERE beach_id = (v_element ->> 'beachId')::uuid
      AND forecast_at = (v_element ->> 'forecastAt')::timestamptz;

    IF FOUND THEN
      IF v_application.decision_id IS DISTINCT FROM v_decision_id
         OR v_application.applied_delta_ft
           IS DISTINCT FROM (v_element ->> 'appliedDeltaFt')::numeric THEN
        RAISE EXCEPTION
          'trusted forecast slot collision for beach % at %',
          v_element ->> 'beachId', v_element ->> 'forecastAt'
          USING ERRCODE = '23505';
      END IF;
      v_reused_application_count := v_reused_application_count + 1;
    ELSE
      INSERT INTO public.trusted_forecast_applications (
        decision_id,
        beach_id,
        forecast_at,
        prediction_snapshot_id,
        applied_delta_ft,
        baseline_max_face_ft,
        adjusted_max_face_ft,
        build_key
      ) VALUES (
        v_decision_id,
        (v_element ->> 'beachId')::uuid,
        (v_element ->> 'forecastAt')::timestamptz,
        v_snapshot_id,
        (v_element ->> 'appliedDeltaFt')::numeric,
        (v_element ->> 'baselineMaxFaceFt')::numeric,
        (v_element ->> 'adjustedMaxFaceFt')::numeric,
        v_build_key
      );
      v_inserted_application_count := v_inserted_application_count + 1;
    END IF;
  END LOOP;

  -- ---------------------------------------------------------------------
  -- 7. Durable conflict alerts.
  -- ---------------------------------------------------------------------
  FOR v_element IN
    SELECT element FROM jsonb_array_elements(p_payload -> 'alerts') AS element
  LOOP
    SELECT decision_id
    INTO v_decision_id
    FROM public.trusted_forecast_decisions
    WHERE beach_id = (v_element ->> 'beachId')::uuid
      AND local_date = (v_element ->> 'localDate')::date;

    IF EXISTS (
      SELECT 1
      FROM public.trusted_forecast_alerts
      WHERE build_key = v_build_key
        AND beach_id = (v_element ->> 'beachId')::uuid
        AND local_date = (v_element ->> 'localDate')::date
        AND alert_code = (v_element ->> 'alertCode')
    ) THEN
      v_reused_alert_count := v_reused_alert_count + 1;
    ELSE
      INSERT INTO public.trusted_forecast_alerts (
        beach_id,
        local_date,
        decision_id,
        alert_code,
        separation_ft,
        primary_issue_id,
        conflicting_issue_id,
        evidence,
        build_key
      ) VALUES (
        (v_element ->> 'beachId')::uuid,
        (v_element ->> 'localDate')::date,
        v_decision_id,
        v_element ->> 'alertCode',
        (v_element ->> 'separationFt')::numeric,
        (v_element ->> 'primaryIssueId')::uuid,
        (v_element ->> 'conflictingIssueId')::uuid,
        coalesce(
          NULLIF(v_element -> 'evidence', 'null'::jsonb),
          '{}'::jsonb
        ),
        v_build_key
      );
      v_inserted_alert_count := v_inserted_alert_count + 1;
    END IF;
  END LOOP;

  SELECT count(*)::integer
  INTO v_durable_alert_count
  FROM public.trusted_forecast_alerts
  WHERE build_key = v_build_key;

  -- ---------------------------------------------------------------------
  -- 8. Receipt last. Any error above rolls the whole build back with it.
  -- ---------------------------------------------------------------------
  INSERT INTO public.trusted_forecast_build_receipts (
    build_key,
    payload_sha256,
    schema_version,
    policy_version,
    build_anchor_at,
    expected_decision_count,
    expected_application_count,
    expected_alert_count,
    expected_snapshot_count,
    inserted_decision_count,
    reused_decision_count,
    inserted_application_count,
    reused_application_count,
    inserted_alert_count,
    reused_alert_count,
    inserted_snapshot_count,
    reused_snapshot_count,
    durable_alert_count
  ) VALUES (
    v_build_key,
    v_payload_sha256,
    v_schema_version,
    v_policy_version,
    v_build_anchor_at,
    v_expected_decision_count,
    v_expected_application_count,
    v_expected_alert_count,
    v_expected_snapshot_count,
    v_inserted_decision_count,
    v_reused_decision_count,
    v_inserted_application_count,
    v_reused_application_count,
    v_inserted_alert_count,
    v_reused_alert_count,
    v_inserted_snapshot_count,
    v_reused_snapshot_count,
    v_durable_alert_count
  )
  RETURNING * INTO v_receipt;

  RETURN NEXT v_receipt;
  RETURN;
END;
$$;


ALTER FUNCTION "public"."persist_trusted_forecast_build"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."persist_trusted_forecast_build"("p_payload" "jsonb") IS 'Atomically persists one trusted-forecast build and inserts the receipt last. Canonicalizes content and computes SHA-256 in the database; a repeated build key returns the existing receipt only when hash and every exact count match (D-19, D-20).';



CREATE OR REPLACE FUNCTION "public"."pin_community_spot_photo_v1"("p_photo_id" "uuid", "p_actor_id" "uuid", "p_target_type" "text", "p_target_id" "uuid", "p_idempotency_key" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  previous_action text;
BEGIN
  SELECT e.action INTO previous_action
  FROM public.community_photo_moderation_events e
  WHERE e.actor_id = p_actor_id AND e.idempotency_key = p_idempotency_key;
  IF previous_action IS NOT NULL THEN
    IF previous_action <> 'admin_pin' THEN RAISE EXCEPTION 'idempotency_conflict'; END IF;
    RETURN true;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.community_spot_photos p
    WHERE p.id = p_photo_id
      AND p.processing_status = 'ready'
      AND p.moderation_status = 'visible'
      AND p.lifecycle_status = 'active'
      AND p.visibility = 'public'
      AND p.target_type = p_target_type
      AND COALESCE(p.beach_id, p.custom_spot_id) = p_target_id
      AND (
        p.target_type = 'beach'
        OR EXISTS (
          SELECT 1 FROM public.custom_spots cs
          WHERE cs.id = p.custom_spot_id
            AND cs.deleted_at IS NULL
            AND cs.visibility = 'public'
        )
      )
  ) THEN
    RAISE EXCEPTION 'photo_not_found';
  END IF;
  UPDATE public.community_photo_feature_pins
  SET revoked_at = now(), revoked_by = p_actor_id
  WHERE revoked_at IS NULL AND (
    (p_target_type = 'beach' AND beach_id = p_target_id)
    OR (p_target_type = 'custom_spot' AND custom_spot_id = p_target_id)
  );
  INSERT INTO public.community_photo_feature_pins (
    photo_id, target_type, beach_id, custom_spot_id, pinned_by
  ) VALUES (
    p_photo_id, p_target_type,
    CASE WHEN p_target_type = 'beach' THEN p_target_id END,
    CASE WHEN p_target_type = 'custom_spot' THEN p_target_id END,
    p_actor_id
  );
  INSERT INTO public.community_photo_moderation_events (
    photo_id, actor_id, action, reason, idempotency_key
  ) VALUES (p_photo_id, p_actor_id, 'admin_pin', 'manual_feature', p_idempotency_key);
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."pin_community_spot_photo_v1"("p_photo_id" "uuid", "p_actor_id" "uuid", "p_target_type" "text", "p_target_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preflight_community_spot_photo_upload_v1"("p_uploader_id" "uuid", "p_idempotency_key" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.community_photo_feature_config
    WHERE singleton AND read_enabled AND writes_enabled
  ) THEN
    RAISE EXCEPTION 'feature_disabled';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.community_photo_contributor_restrictions r
    WHERE r.contributor_id = p_uploader_id
      AND r.lifted_at IS NULL
      AND (r.restricted_until IS NULL OR r.restricted_until > now())
  ) THEN
    RAISE EXCEPTION 'contributor_restricted';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.community_photo_action_events e
    WHERE e.actor_id = p_uploader_id
      AND e.action = 'upload_failed'
      AND e.outcome = 'failed'
      AND e.idempotency_key = p_idempotency_key
  ) THEN
    RAISE EXCEPTION 'upload_attempt_failed';
  END IF;
  IF (
      SELECT count(*)
      FROM public.community_photo_action_events e
      WHERE e.actor_id = p_uploader_id
        AND e.action = 'upload_reserved'
        AND e.outcome = 'accepted'
        AND e.created_at > now() - interval '24 hours'
    ) >= 5
    AND NOT EXISTS (
      SELECT 1
      FROM public.community_photo_action_events e
      WHERE e.actor_id = p_uploader_id
        AND e.action = 'upload_reserved'
        AND e.outcome = 'accepted'
        AND e.idempotency_key = p_idempotency_key
    )
  THEN
    RAISE EXCEPTION 'rolling_upload_limit';
  END IF;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."preflight_community_spot_photo_upload_v1"("p_uploader_id" "uuid", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_custom_spot_analysis_state"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  coordinate_changed boolean := TG_OP = 'INSERT';
  fields jsonb := '{}'::jsonb;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    coordinate_changed := NEW.lat IS DISTINCT FROM OLD.lat
      OR NEW.lon IS DISTINCT FROM OLD.lon
      OR NEW.break_type IS DISTINCT FROM OLD.break_type;

    IF auth.uid() IS NOT NULL THEN
      fields := COALESCE(OLD.fingerprint_provenance->'fields', '{}'::jsonb);
      NEW.swell_access_factors := OLD.swell_access_factors;
      NEW.wind_exposure_factors := OLD.wind_exposure_factors;
      NEW.terrain_method := OLD.terrain_method;
      NEW.terrain_params := OLD.terrain_params;
      NEW.terrain_params_hash := OLD.terrain_params_hash;
      NEW.terrain_analyzed_at := OLD.terrain_analyzed_at;
      NEW.terrain_status := OLD.terrain_status;
      NEW.terrain_analysis_debug := OLD.terrain_analysis_debug;
      NEW.fingerprint_provenance_state := OLD.fingerprint_provenance_state;
      NEW.fingerprint_model_version := OLD.fingerprint_model_version;
      NEW.fingerprint_coordinate_hash := OLD.fingerprint_coordinate_hash;
      NEW.fingerprint_provenance := OLD.fingerprint_provenance;
      NEW.fingerprint_confidence := OLD.fingerprint_confidence;
      NEW.fingerprint_updated_at := OLD.fingerprint_updated_at;
      NEW.analysis_requested_at := OLD.analysis_requested_at;

      IF NEW.facing_direction_deg IS DISTINCT FROM OLD.facing_direction_deg THEN
        fields := CASE WHEN NEW.facing_direction_deg IS NULL THEN fields #- '{facing_direction_deg}'
          ELSE jsonb_set(fields, '{facing_direction_deg}', '"user_corrected"'::jsonb, true) END;
      END IF;
      IF NEW.swell_window_min_deg IS DISTINCT FROM OLD.swell_window_min_deg THEN
        fields := CASE WHEN NEW.swell_window_min_deg IS NULL THEN fields #- '{swell_window_min_deg}'
          ELSE jsonb_set(fields, '{swell_window_min_deg}', '"user_corrected"'::jsonb, true) END;
      END IF;
      IF NEW.swell_window_max_deg IS DISTINCT FROM OLD.swell_window_max_deg THEN
        fields := CASE WHEN NEW.swell_window_max_deg IS NULL THEN fields #- '{swell_window_max_deg}'
          ELSE jsonb_set(fields, '{swell_window_max_deg}', '"user_corrected"'::jsonb, true) END;
      END IF;
      IF NEW.offshore_direction_deg IS DISTINCT FROM OLD.offshore_direction_deg THEN
        fields := CASE WHEN NEW.offshore_direction_deg IS NULL THEN fields #- '{offshore_direction_deg}'
          ELSE jsonb_set(fields, '{offshore_direction_deg}', '"user_corrected"'::jsonb, true) END;
      END IF;
      IF NEW.exposure_level IS DISTINCT FROM OLD.exposure_level THEN
        fields := CASE WHEN NEW.exposure_level IS NULL THEN fields #- '{exposure_level}'
          ELSE jsonb_set(fields, '{exposure_level}', '"user_corrected"'::jsonb, true) END;
      END IF;
      IF NEW.preferred_tide_ft_min IS DISTINCT FROM OLD.preferred_tide_ft_min THEN
        fields := CASE WHEN NEW.preferred_tide_ft_min IS NULL THEN fields #- '{preferred_tide_ft_min}'
          ELSE jsonb_set(fields, '{preferred_tide_ft_min}', '"user_corrected"'::jsonb, true) END;
      END IF;
      IF NEW.preferred_tide_ft_max IS DISTINCT FROM OLD.preferred_tide_ft_max THEN
        fields := CASE WHEN NEW.preferred_tide_ft_max IS NULL THEN fields #- '{preferred_tide_ft_max}'
          ELSE jsonb_set(fields, '{preferred_tide_ft_max}', '"user_corrected"'::jsonb, true) END;
      END IF;
      IF NEW.preferred_tide_direction IS DISTINCT FROM OLD.preferred_tide_direction THEN
        fields := CASE WHEN NEW.preferred_tide_direction IS NULL THEN fields #- '{preferred_tide_direction}'
          ELSE jsonb_set(fields, '{preferred_tide_direction}', '"user_corrected"'::jsonb, true) END;
      END IF;
      IF NEW.tide_direction_sensitivity IS DISTINCT FROM OLD.tide_direction_sensitivity THEN
        fields := CASE WHEN NEW.tide_direction_sensitivity IS NULL THEN fields #- '{tide_direction_sensitivity}'
          ELSE jsonb_set(fields, '{tide_direction_sensitivity}', '"user_corrected"'::jsonb, true) END;
      END IF;
      IF NEW.skill_level IS DISTINCT FROM OLD.skill_level THEN
        fields := CASE WHEN NEW.skill_level IS NULL THEN fields #- '{skill_level}'
          ELSE jsonb_set(fields, '{skill_level}', '"user_corrected"'::jsonb, true) END;
      END IF;

      IF fields <> COALESCE(OLD.fingerprint_provenance->'fields', '{}'::jsonb) THEN
        IF NEW.facing_direction_deg IS NULL
          AND NEW.swell_window_min_deg IS NULL
          AND NEW.swell_window_max_deg IS NULL
          AND NEW.offshore_direction_deg IS NULL
          AND NEW.exposure_level IS NULL
          AND NEW.preferred_tide_ft_min IS NULL
          AND NEW.preferred_tide_ft_max IS NULL
          AND NEW.preferred_tide_direction IS NULL
          AND NEW.tide_direction_sensitivity IS NULL
          AND NEW.skill_level IS NULL THEN
          IF OLD.terrain_status = 'ok'
            AND OLD.fingerprint_model_version = 'custom_spot_terrain_v1'
            AND public.is_valid_directional_factor_array(OLD.swell_access_factors)
            AND OLD.swell_access_factors IS NOT NULL
            AND public.is_valid_directional_factor_array(OLD.wind_exposure_factors)
            AND OLD.wind_exposure_factors IS NOT NULL THEN
            NEW.fingerprint_provenance_state := 'modeled';
            NEW.fingerprint_confidence := 'modeled';
          ELSE
            NEW.fingerprint_provenance_state := 'unset';
            NEW.fingerprint_confidence := 'unset';
          END IF;
        ELSE
          NEW.fingerprint_provenance_state := 'user_corrected';
          NEW.fingerprint_confidence := 'user_set';
        END IF;
        NEW.fingerprint_provenance := jsonb_set(
          COALESCE(OLD.fingerprint_provenance, '{"schema_version":1}'::jsonb),
          '{fields}', fields, true
        );
        NEW.fingerprint_updated_at := now();
      END IF;
    ELSE
      fields := COALESCE(NEW.fingerprint_provenance->'fields', '{}'::jsonb);
    END IF;
  ELSIF auth.uid() IS NOT NULL THEN
    NEW.swell_access_factors := NULL;
    NEW.wind_exposure_factors := NULL;
    NEW.terrain_method := NULL;
    NEW.terrain_params := NULL;
    NEW.terrain_params_hash := NULL;
    NEW.terrain_analyzed_at := NULL;
    NEW.terrain_status := NULL;
    NEW.terrain_analysis_debug := NULL;
    NEW.fingerprint_provenance_state := 'unset';
    NEW.fingerprint_model_version := NULL;
    NEW.fingerprint_coordinate_hash := NULL;
    NEW.fingerprint_provenance := '{"schema_version":1,"fields":{}}'::jsonb;
    NEW.analysis_requested_at := NULL;
    IF NEW.fingerprint_confidence IS DISTINCT FROM 'user_set' THEN
      NEW.fingerprint_confidence := 'unset';
      NEW.fingerprint_updated_at := NULL;
    END IF;

    IF NEW.fingerprint_confidence = 'user_set' THEN
      IF NEW.facing_direction_deg IS NOT NULL THEN
        fields := jsonb_set(fields, '{facing_direction_deg}', '"user_corrected"'::jsonb, true);
      END IF;
      IF NEW.swell_window_min_deg IS NOT NULL THEN
        fields := jsonb_set(fields, '{swell_window_min_deg}', '"user_corrected"'::jsonb, true);
      END IF;
      IF NEW.swell_window_max_deg IS NOT NULL THEN
        fields := jsonb_set(fields, '{swell_window_max_deg}', '"user_corrected"'::jsonb, true);
      END IF;
      IF NEW.offshore_direction_deg IS NOT NULL THEN
        fields := jsonb_set(fields, '{offshore_direction_deg}', '"user_corrected"'::jsonb, true);
      END IF;
      IF NEW.exposure_level IS NOT NULL THEN
        fields := jsonb_set(fields, '{exposure_level}', '"user_corrected"'::jsonb, true);
      END IF;
      NEW.fingerprint_provenance_state := 'user_corrected';
    END IF;

    IF NEW.preferred_tide_ft_min IS NOT NULL THEN
      fields := jsonb_set(fields, '{preferred_tide_ft_min}', '"user_corrected"'::jsonb, true);
    END IF;
    IF NEW.preferred_tide_ft_max IS NOT NULL THEN
      fields := jsonb_set(fields, '{preferred_tide_ft_max}', '"user_corrected"'::jsonb, true);
    END IF;
    IF NEW.preferred_tide_direction IS NOT NULL THEN
      fields := jsonb_set(fields, '{preferred_tide_direction}', '"user_corrected"'::jsonb, true);
    END IF;
    IF NEW.tide_direction_sensitivity IS NOT NULL THEN
      fields := jsonb_set(fields, '{tide_direction_sensitivity}', '"user_corrected"'::jsonb, true);
    END IF;
    IF NEW.skill_level IS NOT NULL THEN
      fields := jsonb_set(fields, '{skill_level}', '"user_corrected"'::jsonb, true);
    END IF;
    IF fields <> '{}'::jsonb THEN
      NEW.fingerprint_provenance_state := 'user_corrected';
      NEW.fingerprint_confidence := 'user_set';
      NEW.fingerprint_updated_at := now();
    END IF;
  ELSE
    fields := COALESCE(NEW.fingerprint_provenance->'fields', '{}'::jsonb);
  END IF;

  NEW.fingerprint_provenance := jsonb_set(
    COALESCE(NEW.fingerprint_provenance, '{"schema_version":1}'::jsonb),
    '{fields}',
    fields,
    true
  );

  IF coordinate_changed AND NEW.deleted_at IS NULL THEN
    NEW.terrain_status := 'queued';
    NEW.analysis_requested_at := now();
    NEW.terrain_analyzed_at := NULL;
    NEW.terrain_method := NULL;
    NEW.terrain_params := NULL;
    NEW.terrain_params_hash := NULL;
    NEW.terrain_analysis_debug := NULL;
    NEW.fingerprint_model_version := NULL;
    NEW.fingerprint_coordinate_hash := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prepare_custom_spot_analysis_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preset_default_conditions"("p_preset" "text", "p_beach_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_tide_min numeric;
  v_tide_max numeric;
  v_effective_tide_min numeric;
  v_effective_tide_max numeric;
  v_preference_model jsonb;
  v_beginner_window jsonb;
  v_beginner_fit text;
  v_apply_sandy_beginner boolean;
  v_result jsonb;
  v_wind_mph numeric;
  v_time_start text;
  v_time_end text;
BEGIN
  CASE p_preset
    WHEN 'glass_off' THEN
      RETURN jsonb_build_object(
        'wind_direction', 'offshore',
        'wind_speed_max_kt', 5,
        'swell_height_min', 2
      );
    WHEN 'big_day' THEN
      RETURN jsonb_build_object(
        'swell_height_min', 6,
        'swell_period_min', 10
      );
    WHEN 'mellow_session' THEN
      SELECT
        b.preferred_tide_ft_min,
        b.preferred_tide_ft_max,
        b.preference_model
      INTO
        v_tide_min,
        v_tide_max,
        v_preference_model
      FROM public.beaches b
      WHERE b.id = p_beach_id;

      v_beginner_window := v_preference_model -> 'beginner_window';
      v_beginner_fit := lower(v_beginner_window ->> 'beginner_fit');
      v_effective_tide_min := COALESCE(
        NULLIF(v_beginner_window ->> 'preferred_tide_ft_min', '')::numeric,
        v_tide_min
      );
      v_effective_tide_max := COALESCE(
        NULLIF(v_beginner_window ->> 'preferred_tide_ft_max', '')::numeric,
        v_tide_max
      );
      v_apply_sandy_beginner :=
        v_beginner_window IS NOT NULL
        AND v_beginner_fit IN ('primary', 'conditional');

      IF v_apply_sandy_beginner THEN
        v_wind_mph := COALESCE(
          NULLIF(v_beginner_window ->> 'max_beginner_wind_mph', '')::numeric,
          10
        );
        v_time_start := COALESCE(v_beginner_window #>> '{best_time_local,start}', '06:00');
        v_time_end := COALESCE(v_beginner_window #>> '{best_time_local,end}', '10:00');
        v_result := jsonb_build_object(
          'swell_height_min',
          COALESCE(
            NULLIF(v_beginner_window #>> '{acceptable_wave_height_ft,min}', '')::numeric,
            0.5
          ),
          'swell_height_max',
          COALESCE(
            NULLIF(v_beginner_window #>> '{acceptable_wave_height_ft,max}', '')::numeric,
            3
          ),
          'wind_speed_max_kt',
          round(v_wind_mph * 0.868976)::integer,
          'avoid_tide_statuses',
          jsonb_build_array('high'),
          'local_time_start',
          v_time_start,
          'local_time_end',
          v_time_end,
          'beginner_sandy_window',
          true
        );
      ELSE
        v_result := jsonb_build_object(
          'swell_height_min', 1.5,
          'swell_height_max', 4,
          'wind_speed_max_kt', 8
        );
      END IF;

      IF v_effective_tide_min IS NOT NULL THEN
        v_result := v_result || jsonb_build_object('tide_height_min_ft', v_effective_tide_min);
      END IF;
      IF v_effective_tide_max IS NOT NULL THEN
        v_result := v_result || jsonb_build_object('tide_height_max_ft', v_effective_tide_max);
      END IF;
      RETURN v_result;
    ELSE
      RAISE EXCEPTION 'Unknown preset_type: %', p_preset;
  END CASE;
END;
$$;


ALTER FUNCTION "public"."preset_default_conditions"("p_preset" "text", "p_beach_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preset_default_name"("p_preset" "text", "p_beach_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_beach_name text;
  v_label text;
BEGIN
  SELECT name INTO v_beach_name FROM beaches WHERE id = p_beach_id;
  v_label := CASE p_preset
    WHEN 'glass_off'       THEN 'Glassy mornings'
    WHEN 'big_day'         THEN 'Big swells'
    WHEN 'mellow_session'  THEN 'Beginner-friendly'
    ELSE p_preset
  END;
  RETURN v_label || ' — ' || COALESCE(v_beach_name, 'beach');
END;
$$;


ALTER FUNCTION "public"."preset_default_name"("p_preset" "text", "p_beach_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_delete_on_protected"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
BEGIN
  -- Allow ephemeral-smoke-test users to be deleted regardless of the
  -- destructive flag. Marker is server-only (app_metadata).
  IF TG_TABLE_SCHEMA = 'auth' AND TG_TABLE_NAME = 'users' THEN
    IF (OLD.raw_app_meta_data->>'is_ephemeral_smoke_test')::boolean IS TRUE THEN
      RETURN OLD;
    END IF;
  ELSIF TG_TABLE_SCHEMA = 'public' AND TG_TABLE_NAME = 'profiles' THEN
    -- Orphan profiles (auth.users row already deleted) are always safe.
    IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = OLD.id) THEN
      RETURN OLD;
    END IF;
  END IF;

  -- Existing escape hatch: explicit DBA flag inside a transaction.
  IF current_setting('app.allow_destructive', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'DELETE blocked on % (user=%). Set app.allow_destructive=on inside a transaction if you truly need to proceed.',
      TG_TABLE_NAME, current_user;
  END IF;
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."prevent_delete_on_protected"() OWNER TO "postgres";


