    CONSTRAINT "install_evidence_surface_check" CHECK (("surface" = ANY (ARRAY['android_beta'::"text", 'landing-page'::"text", 'landing'::"text", 'download'::"text", 'features-page'::"text", 'plans-page'::"text", 'partner_landing'::"text", 'invite_landing'::"text", 'session_log_success'::"text", 'session_detail_fallback'::"text", 'app_handoff'::"text", 'pbsc-page'::"text", 'og_session_card'::"text", 'og_surf_call_card'::"text", 'map'::"text"])))
