    "a"."verified_at",
    "a"."mirror_verified_at",
    "a"."claim_message_instance_id",
    "message"."provider_id",
    "message"."campaign_id",
    "message"."campaign_version",
    "message"."handoff_at"
   FROM ("public"."pro_offer_awards" "a"
     LEFT JOIN "public"."email_contact_attempts" "message" ON (("message"."id" = "a"."claim_message_instance_id")));


