CREATE OR REPLACE VIEW "public"."nsm_activation" WITH ("security_invoker"='true') AS
 WITH "eligible" AS (
         SELECT "ue"."user_id",
            "ue"."created_at",
            COALESCE(NULLIF(("ue"."metadata" ->> 'source'::"text"), ''::"text"), 'unknown'::"text") AS "source",
            ("lower"(COALESCE(("ue"."metadata" ->> 'is_first_session'::"text"), 'false'::"text")) = 'true'::"text") AS "is_first_session"
           FROM ("public"."user_events" "ue"
             JOIN "public"."profiles" "p" ON (("p"."id" = "ue"."user_id")))
          WHERE (("ue"."event_type" = 'session_created'::"text") AND ("ue"."created_at" >= ("now"() - '180 days'::interval)) AND ("ue"."user_id" IS NOT NULL) AND (COALESCE("ue"."bot_flagged", false) = false) AND ("p"."deleted_at" IS NULL) AND (COALESCE("p"."is_mock", false) = false) AND (COALESCE("p"."is_system_account", false) = false) AND ("p"."analytics_is_real_user" = true) AND ("lower"(COALESCE(("ue"."metadata" ->> 'is_mock'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'mock'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'is_system_account'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'system'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'analytics_is_real_user'::"text"), 'true'::"text")) <> 'false'::"text"))
        ), "first_sessions_by_day" AS (
         SELECT ("date_trunc"('day'::"text", "eligible"."created_at"))::"date" AS "day",
            "eligible"."source",
            "count"(DISTINCT "eligible"."user_id") AS "first_session_users"
           FROM "eligible"
          WHERE "eligible"."is_first_session"
          GROUP BY (("date_trunc"('day'::"text", "eligible"."created_at"))::"date"), "eligible"."source"
        ), "new_users_by_day" AS (
         SELECT ("date_trunc"('day'::"text", "p"."created_at"))::"date" AS "day",
            "count"(*) AS "new_users"
           FROM "public"."profiles" "p"
          WHERE (("p"."created_at" >= ("now"() - '180 days'::interval)) AND ("p"."deleted_at" IS NULL) AND (COALESCE("p"."is_mock", false) = false) AND (COALESCE("p"."is_system_account", false) = false) AND ("p"."analytics_is_real_user" = true))
          GROUP BY (("date_trunc"('day'::"text", "p"."created_at"))::"date")
        )
 SELECT "fs"."day",
    "fs"."source",
    "fs"."first_session_users",
    COALESCE("nu"."new_users", (0)::bigint) AS "new_users",
        CASE
            WHEN (COALESCE("nu"."new_users", (0)::bigint) = 0) THEN NULL::numeric
            ELSE "round"((("fs"."first_session_users")::numeric / ("nu"."new_users")::numeric), 4)
        END AS "activation_rate"
   FROM ("first_sessions_by_day" "fs"
     LEFT JOIN "new_users_by_day" "nu" ON (("nu"."day" = "fs"."day")));


ALTER TABLE "public"."nsm_activation" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."nsm_daily_logged_sessions" WITH ("security_invoker"='true') AS
 WITH "eligible" AS (
         SELECT ("date_trunc"('day'::"text", "ue"."created_at"))::"date" AS "day",
            COALESCE(NULLIF(("ue"."metadata" ->> 'source'::"text"), ''::"text"), 'unknown'::"text") AS "source"
           FROM ("public"."user_events" "ue"
             JOIN "public"."profiles" "p" ON (("p"."id" = "ue"."user_id")))
          WHERE (("ue"."event_type" = 'session_created'::"text") AND ("ue"."created_at" >= ("now"() - '180 days'::interval)) AND ("ue"."user_id" IS NOT NULL) AND (COALESCE("ue"."bot_flagged", false) = false) AND ("p"."deleted_at" IS NULL) AND (COALESCE("p"."is_mock", false) = false) AND (COALESCE("p"."is_system_account", false) = false) AND ("p"."analytics_is_real_user" = true) AND ("lower"(COALESCE(("ue"."metadata" ->> 'is_mock'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'mock'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'is_system_account'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'system'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'analytics_is_real_user'::"text"), 'true'::"text")) <> 'false'::"text"))
        )
 SELECT "eligible"."day",
    "eligible"."source",
    "count"(*) AS "logged_sessions"
   FROM "eligible"
  GROUP BY "eligible"."day", "eligible"."source";


