CREATE OR REPLACE VIEW "public"."nsm_repeat_3plus_21d" WITH ("security_invoker"='true') AS
 WITH "days" AS (
         SELECT "generate_series"("date_trunc"('day'::"text", ("now"() - '120 days'::interval)), "date_trunc"('day'::"text", "now"()), '1 day'::interval) AS "day"
        ), "eligible" AS (
         SELECT "ue"."user_id",
            "ue"."created_at",
            COALESCE(NULLIF(("ue"."metadata" ->> 'source'::"text"), ''::"text"), 'unknown'::"text") AS "source"
           FROM ("public"."user_events" "ue"
             JOIN "public"."profiles" "p" ON (("p"."id" = "ue"."user_id")))
          WHERE (("ue"."event_type" = 'session_created'::"text") AND ("ue"."created_at" >= ("now"() - '140 days'::interval)) AND ("ue"."user_id" IS NOT NULL) AND (COALESCE("ue"."bot_flagged", false) = false) AND ("p"."deleted_at" IS NULL) AND (COALESCE("p"."is_mock", false) = false) AND (COALESCE("p"."is_system_account", false) = false) AND ("p"."analytics_is_real_user" = true) AND ("lower"(COALESCE(("ue"."metadata" ->> 'is_mock'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'mock'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'is_system_account'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'system'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'analytics_is_real_user'::"text"), 'true'::"text")) <> 'false'::"text"))
        ), "repeat_users" AS (
         SELECT ("d"."day")::"date" AS "day",
            "e"."user_id",
            ("array_agg"("e"."source" ORDER BY "e"."created_at" DESC))[1] AS "source",
            "count"(*) AS "sessions_in_21d"
           FROM ("days" "d"
             JOIN "eligible" "e" ON ((("e"."created_at" >= ("d"."day" - '20 days'::interval)) AND ("e"."created_at" < ("d"."day" + '1 day'::interval)))))
          GROUP BY "d"."day", "e"."user_id"
         HAVING ("count"(*) >= 3)
        )
 SELECT "repeat_users"."day",
    "repeat_users"."source",
    "count"(*) AS "repeat_users_3plus_21d"
   FROM "repeat_users"
  GROUP BY "repeat_users"."day", "repeat_users"."source";


ALTER TABLE "public"."nsm_repeat_3plus_21d" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."nsm_time_to_first_session" WITH ("security_invoker"='true') AS
 WITH "eligible" AS (
         SELECT "ue"."user_id",
            "ue"."created_at",
            COALESCE(NULLIF(("ue"."metadata" ->> 'source'::"text"), ''::"text"), 'unknown'::"text") AS "source"
           FROM ("public"."user_events" "ue"
             JOIN "public"."profiles" "p" ON (("p"."id" = "ue"."user_id")))
          WHERE (("ue"."event_type" = 'session_created'::"text") AND ("ue"."user_id" IS NOT NULL) AND (COALESCE("ue"."bot_flagged", false) = false) AND ("p"."deleted_at" IS NULL) AND (COALESCE("p"."is_mock", false) = false) AND (COALESCE("p"."is_system_account", false) = false) AND ("p"."analytics_is_real_user" = true) AND ("lower"(COALESCE(("ue"."metadata" ->> 'is_mock'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'mock'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'is_system_account'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'system'::"text"), 'false'::"text")) <> 'true'::"text") AND ("lower"(COALESCE(("ue"."metadata" ->> 'analytics_is_real_user'::"text"), 'true'::"text")) <> 'false'::"text"))
        ), "first_session" AS (
         SELECT DISTINCT ON ("eligible"."user_id") "eligible"."user_id",
            "eligible"."created_at" AS "first_session_at",
            "eligible"."source"
           FROM "eligible"
          ORDER BY "eligible"."user_id", "eligible"."created_at"
        ), "activated_users" AS (
         SELECT ("date_trunc"('day'::"text", "p"."created_at"))::"date" AS "signup_day",
            "fs"."source",
            (EXTRACT(epoch FROM ("fs"."first_session_at" - "p"."created_at")) / 3600.0) AS "hours_to_first_session"
           FROM ("public"."profiles" "p"
             JOIN "first_session" "fs" ON (("fs"."user_id" = "p"."id")))
          WHERE (("p"."created_at" >= ("now"() - '180 days'::interval)) AND ("p"."deleted_at" IS NULL) AND (COALESCE("p"."is_mock", false) = false) AND (COALESCE("p"."is_system_account", false) = false) AND ("p"."analytics_is_real_user" = true) AND ("fs"."first_session_at" >= "p"."created_at"))
        )
 SELECT "activated_users"."signup_day",
    "activated_users"."source",
    "count"(*) AS "activated_users",
    "round"(("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("activated_users"."hours_to_first_session")::double precision)))::numeric, 2) AS "median_hours_to_first_session",
    "round"(("percentile_cont"((0.75)::double precision) WITHIN GROUP (ORDER BY (("activated_users"."hours_to_first_session")::double precision)))::numeric, 2) AS "p75_hours_to_first_session"
   FROM "activated_users"
  GROUP BY "activated_users"."signup_day", "activated_users"."source";


ALTER TABLE "public"."nsm_time_to_first_session" OWNER TO "postgres";


