CREATE OR REPLACE VIEW "public"."session_activation_report" WITH ("security_invoker"='true') AS
 WITH "real_users" AS (
         SELECT "p"."id" AS "user_id",
            "p"."created_at" AS "signup_at"
           FROM "public"."profiles" "p"
          WHERE (("p"."deleted_at" IS NULL) AND (COALESCE("p"."is_mock", false) = false) AND (COALESCE("p"."is_system_account", false) = false) AND (COALESCE("p"."is_admin", false) = false) AND (COALESCE("p"."analytics_is_real_user", true) = true) AND (COALESCE("p"."email", ''::"text") !~~* '%test%'::"text") AND (COALESCE("p"."email", ''::"text") !~~* '%@local.test'::"text") AND (COALESCE("p"."email", ''::"text") !~~* '%@example.invalid'::"text"))
        ), "completed_sessions" AS (
         SELECT "s"."id" AS "session_id",
            "s"."user_id",
            "s"."beach_id",
            "s"."created_at",
            "s"."arrival_time",
            "s"."is_public",
            "row_number"() OVER (PARTITION BY "s"."user_id" ORDER BY "s"."created_at", "s"."id") AS "session_number"
           FROM ("public"."sessions" "s"
             JOIN "real_users" "ru_1" ON (("ru_1"."user_id" = "s"."user_id")))
          WHERE (("s"."status" = 'completed'::"text") AND ("s"."deleted_at" IS NULL))
        ), "first_sessions" AS (
         SELECT "completed_sessions"."user_id",
            "completed_sessions"."session_id" AS "first_session_id",
            "completed_sessions"."created_at" AS "first_session_at",
            "completed_sessions"."beach_id" AS "first_session_beach_id"
           FROM "completed_sessions"
          WHERE ("completed_sessions"."session_number" = 1)
        ), "second_sessions" AS (
         SELECT "cs"."user_id",
            "cs"."session_id" AS "second_session_within_14d_id",
            "cs"."created_at" AS "second_session_within_14d_at"
           FROM ("completed_sessions" "cs"
             JOIN "first_sessions" "fs_1" ON (("fs_1"."user_id" = "cs"."user_id")))
          WHERE (("cs"."session_number" = 2) AND ("cs"."created_at" < ("fs_1"."first_session_at" + '14 days'::interval)))
        ), "public_milestones" AS (
         SELECT "e"."user_id",
            "min"("e"."created_at") FILTER (WHERE "e"."informative") AS "first_qualified_public_session_at",
            "min"("e"."created_at") FILTER (WHERE "e"."warning") AS "first_warning_session_at",
            "min"("e"."created_at") FILTER (WHERE "e"."thin") AS "first_thin_public_session_at",
            "count"(*) FILTER (WHERE "e"."informative") AS "qualified_public_session_count",
            "count"(*) FILTER (WHERE "e"."warning") AS "warning_session_count",
            "count"(*) FILTER (WHERE "e"."thin") AS "thin_public_session_count"
           FROM "public"."public_session_feed_eligibility" "e"
          GROUP BY "e"."user_id"
        ), "session_counts" AS (
         SELECT "cs"."user_id",
            "count"(*) AS "completed_session_count",
            "count"(*) FILTER (WHERE ("cs"."is_public" = true)) AS "public_session_count"
           FROM "completed_sessions" "cs"
          GROUP BY "cs"."user_id"
        )
 SELECT "ru"."user_id",
    "ru"."signup_at",
    "fs"."first_session_id",
    "fs"."first_session_at",
    "fs"."first_session_beach_id",
        CASE
            WHEN ("fs"."first_session_at" IS NULL) THEN NULL::numeric
            ELSE "round"((EXTRACT(epoch FROM ("fs"."first_session_at" - "ru"."signup_at")) / 86400.0), 2)
        END AS "days_to_first_session",
    "ss"."second_session_within_14d_id",
    "ss"."second_session_within_14d_at",
    ("ss"."second_session_within_14d_id" IS NOT NULL) AS "has_second_session_within_14d",
    "pm"."first_qualified_public_session_at",
    "pm"."first_warning_session_at",
    "pm"."first_thin_public_session_at",
    COALESCE("sc"."completed_session_count", (0)::bigint) AS "completed_session_count",
    COALESCE("sc"."public_session_count", (0)::bigint) AS "public_session_count",
    COALESCE("pm"."qualified_public_session_count", (0)::bigint) AS "qualified_public_session_count",
    COALESCE("pm"."warning_session_count", (0)::bigint) AS "warning_session_count",
    COALESCE("pm"."thin_public_session_count", (0)::bigint) AS "thin_public_session_count"
   FROM (((("real_users" "ru"
     LEFT JOIN "first_sessions" "fs" ON (("fs"."user_id" = "ru"."user_id")))
     LEFT JOIN "second_sessions" "ss" ON (("ss"."user_id" = "ru"."user_id")))
     LEFT JOIN "public_milestones" "pm" ON (("pm"."user_id" = "ru"."user_id")))
     LEFT JOIN "session_counts" "sc" ON (("sc"."user_id" = "ru"."user_id")));


