CREATE TABLE IF NOT EXISTS "public"."trusted_forecast_decisions" (
    "decision_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "beach_id" "uuid" NOT NULL,
    "local_date" "date" NOT NULL,
    "local_timezone" "text" NOT NULL,
    "status" "text" NOT NULL,
    "primary_issue_id" "uuid",
    "baseline_max_face_ft" numeric(8,4),
    "trusted_min_face_ft" numeric(8,4),
    "trusted_max_face_ft" numeric(8,4),
    "signed_gap_ft" numeric(8,4),
    "applied_delta_ft" numeric(8,4) DEFAULT 0 NOT NULL,
    "policy_version" "text" NOT NULL,
    "build_key" "text" NOT NULL,
    "decided_at" timestamp with time zone DEFAULT "transaction_timestamp"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "trusted_forecast_decisions_applied_requires_delta_check" CHECK ((("status" = 'applied'::"text") = ("applied_delta_ft" <> (0)::numeric))),
    CONSTRAINT "trusted_forecast_decisions_applied_requires_primary_check" CHECK ((("status" <> ALL (ARRAY['applied'::"text", 'no_adjustment'::"text"])) OR (("primary_issue_id" IS NOT NULL) AND ("trusted_min_face_ft" IS NOT NULL) AND ("trusted_max_face_ft" IS NOT NULL) AND ("baseline_max_face_ft" IS NOT NULL)))),
    CONSTRAINT "trusted_forecast_decisions_delta_band_check" CHECK (("applied_delta_ft" = ANY (ARRAY['-0.5'::numeric, '-0.25'::numeric, (0)::numeric, 0.25, 0.5]))),
    CONSTRAINT "trusted_forecast_decisions_range_check" CHECK (((("trusted_min_face_ft" IS NULL) = ("trusted_max_face_ft" IS NULL)) AND (("trusted_min_face_ft" IS NULL) OR (("trusted_min_face_ft" >= (0)::numeric) AND ("trusted_max_face_ft" <= (60)::numeric) AND ("trusted_min_face_ft" <= "trusted_max_face_ft"))))),
    CONSTRAINT "trusted_forecast_decisions_status_check" CHECK (("status" = ANY (ARRAY['applied'::"text", 'no_adjustment'::"text", 'no_authority'::"text", 'blocked_conflict'::"text"])))
);


ALTER TABLE "public"."trusted_forecast_decisions" OWNER TO "postgres";


COMMENT ON TABLE "public"."trusted_forecast_decisions" IS 'Append-only, exactly one decision per beach and IANA local day (D-13, D-18).';



CREATE TABLE IF NOT EXISTS "public"."trusted_forecast_ingest_runs" (
    "ingest_run_id" "uuid" NOT NULL,
    "started_at" timestamp with time zone NOT NULL,
    "finished_at" timestamp with time zone NOT NULL,
    "source_count" integer NOT NULL,
    "ok_count" integer NOT NULL,
    "failed_count" integer NOT NULL,
    "issue_count" integer NOT NULL,
    "healthy" boolean NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "trusted_forecast_ingest_runs_counts_check" CHECK ((("source_count" >= 0) AND ("ok_count" >= 0) AND ("failed_count" >= 0) AND ("issue_count" >= 0) AND (("ok_count" + "failed_count") = "source_count"))),
    CONSTRAINT "trusted_forecast_ingest_runs_health_check" CHECK (("healthy" = ("failed_count" = 0))),
    CONSTRAINT "trusted_forecast_ingest_runs_window_check" CHECK (("finished_at" >= "started_at"))
);


ALTER TABLE "public"."trusted_forecast_ingest_runs" OWNER TO "postgres";


COMMENT ON TABLE "public"."trusted_forecast_ingest_runs" IS 'Append-only health record for each six-hour trusted-forecast ingestion run (D-04, D-18).';



CREATE TABLE IF NOT EXISTS "public"."trusted_forecast_ingest_source_results" (
    "source_result_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ingest_run_id" "uuid" NOT NULL,
    "source_key" "text" NOT NULL,
    "provider_lineage" "text" NOT NULL,
    "parser_key" "text" NOT NULL,
    "parser_version" "text" NOT NULL,
    "status" "text" NOT NULL,
    "failure_code" "text",
    "http_status" integer,
    "redirect_hops" integer,
    "attempts" integer,
    "issue_count" integer DEFAULT 0 NOT NULL,
    "authority_issue_count" integer DEFAULT 0 NOT NULL,
    "degraded_failure_code" "text",
    "degraded_item_count" integer DEFAULT 0 NOT NULL,
    "started_at" timestamp with time zone NOT NULL,
    "finished_at" timestamp with time zone NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "trusted_forecast_source_results_counts_check" CHECK ((("issue_count" >= 0) AND ("authority_issue_count" >= 0) AND ("authority_issue_count" <= "issue_count") AND ("degraded_item_count" >= 0) AND (("http_status" IS NULL) OR (("http_status" >= 100) AND ("http_status" <= 599))) AND (("redirect_hops" IS NULL) OR ("redirect_hops" >= 0)) AND (("attempts" IS NULL) OR ("attempts" >= 0)))),
    CONSTRAINT "trusted_forecast_source_results_degraded_check" CHECK (((("degraded_failure_code" IS NULL) AND ("degraded_item_count" = 0)) OR (("degraded_failure_code" IS NOT NULL) AND ("degraded_item_count" > 0) AND ("status" = 'ok'::"text")))),
    CONSTRAINT "trusted_forecast_source_results_failure_code_check" CHECK (
CASE
    WHEN ("status" = ANY (ARRAY['ok'::"text", 'skipped_disabled'::"text"])) THEN ("failure_code" IS NULL)
    ELSE ("failure_code" IS NOT NULL)
END),
    CONSTRAINT "trusted_forecast_source_results_status_check" CHECK (("status" = ANY (ARRAY['ok'::"text", 'no_issues'::"text", 'transport_failed'::"text", 'parser_failed'::"text", 'skipped_disabled'::"text"]))),
    CONSTRAINT "trusted_forecast_source_results_window_check" CHECK (("finished_at" >= "started_at"))
);


ALTER TABLE "public"."trusted_forecast_ingest_source_results" OWNER TO "postgres";


COMMENT ON TABLE "public"."trusted_forecast_ingest_source_results" IS 'Append-only per-source ingestion outcome. degraded_failure_code/degraded_item_count record partial item loss inside an otherwise healthy source. No FK to trusted_forecast_ingest_runs: the cron writes the run row last.';



CREATE TABLE IF NOT EXISTS "public"."trusted_forecast_issues" (
    "issue_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider_lineage" "text" NOT NULL,
    "source_key" "text" NOT NULL,
    "issued_at" timestamp with time zone NOT NULL,
    "valid_local_date" "date" NOT NULL,
    "valid_timezone" "text" NOT NULL,
    "valid_start_at" timestamp with time zone NOT NULL,
    "valid_end_at" timestamp with time zone NOT NULL,
    "validity_basis" "text" NOT NULL,
    "scope_type" "text" NOT NULL,
    "region_key" "text",
    "beach_id" "uuid",
    "exposure" "text" NOT NULL,
    "day_part" "text" NOT NULL,
    "measurement_basis" "text" NOT NULL,
    "min_face_ft" numeric(8,4),
    "max_face_ft" numeric(8,4),
    "direction_deg" numeric(8,4),
    "period_seconds" numeric(8,4),
    "parser_version" "text" NOT NULL,
    "source_hash" "text" NOT NULL,
    "issue_identity_key" "text" NOT NULL,
    "revision_hash" "text" NOT NULL,
    "supersedes_issue_id" "uuid",
    "authority_eligible" boolean NOT NULL,
    "evidence_class" "text" NOT NULL,
    "ingest_run_id" "uuid",
    "fetched_at" timestamp with time zone NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "trusted_forecast_issues_authority_check" CHECK ((("authority_eligible" = false) OR (("min_face_ft" IS NOT NULL) AND ("max_face_ft" IS NOT NULL) AND ("measurement_basis" = 'breaking_face_ft'::"text") AND ("evidence_class" = 'human_face_height_authority'::"text")))),
    CONSTRAINT "trusted_forecast_issues_day_part_check" CHECK (("day_part" = ANY (ARRAY['all_day'::"text", 'day'::"text", 'night'::"text"]))),
    CONSTRAINT "trusted_forecast_issues_direction_check" CHECK ((("direction_deg" IS NULL) OR (("direction_deg" >= (0)::numeric) AND ("direction_deg" < (360)::numeric)))),
    CONSTRAINT "trusted_forecast_issues_evidence_class_check" CHECK (("evidence_class" = ANY (ARRAY['human_face_height_authority'::"text", 'model_buoy_evidence'::"text", 'evidence_only'::"text"]))),
    CONSTRAINT "trusted_forecast_issues_identity_hex_check" CHECK (("issue_identity_key" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "trusted_forecast_issues_measurement_basis_check" CHECK (("measurement_basis" = ANY (ARRAY['breaking_face_ft'::"text", 'unspecified'::"text"]))),
    CONSTRAINT "trusted_forecast_issues_period_check" CHECK ((("period_seconds" IS NULL) OR (("period_seconds" > (0)::numeric) AND ("period_seconds" <= (120)::numeric)))),
    CONSTRAINT "trusted_forecast_issues_range_bounds_check" CHECK (((("min_face_ft" IS NULL) OR (("min_face_ft" >= (0)::numeric) AND ("min_face_ft" <= (60)::numeric))) AND (("max_face_ft" IS NULL) OR (("max_face_ft" >= (0)::numeric) AND ("max_face_ft" <= (60)::numeric))) AND (("min_face_ft" IS NULL) OR ("max_face_ft" IS NULL) OR ("min_face_ft" <= "max_face_ft")))),
    CONSTRAINT "trusted_forecast_issues_range_pairing_check" CHECK ((("min_face_ft" IS NULL) = ("max_face_ft" IS NULL))),
    CONSTRAINT "trusted_forecast_issues_revision_hex_check" CHECK (("revision_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "trusted_forecast_issues_scope_type_check" CHECK (("scope_type" = ANY (ARRAY['spot'::"text", 'regional'::"text"]))),
    CONSTRAINT "trusted_forecast_issues_validity_basis_check" CHECK (("validity_basis" = ANY (ARRAY['stated'::"text", 'derived_publication_day'::"text"]))),
    CONSTRAINT "trusted_forecast_issues_window_check" CHECK (("valid_end_at" > "valid_start_at"))
);


ALTER TABLE "public"."trusted_forecast_issues" OWNER TO "postgres";


COMMENT ON TABLE "public"."trusted_forecast_issues" IS 'Append-only normalized forecaster issue revisions (MFA-02, D-18). region_key carries chart spot slugs when scope_type=spot; exposure is free text across source families.';



COMMENT ON COLUMN "public"."trusted_forecast_issues"."validity_basis" IS 'Whether the source stated the validity window or it was derived from the publication day (stated|derived_publication_day).';



COMMENT ON COLUMN "public"."trusted_forecast_issues"."day_part" IS 'Sub-day window facet (all_day|day|night). Kept out of exposure so D-12 exposure compatibility stays spatial.';



