    CONSTRAINT "user_location_snapshots_lat_check" CHECK ((("lat" >= ('-90'::integer)::double precision) AND ("lat" <= (90)::double precision))),
    CONSTRAINT "user_location_snapshots_lon_check" CHECK ((("lon" >= ('-180'::integer)::double precision) AND ("lon" <= (180)::double precision))),
    CONSTRAINT "user_location_snapshots_source_check" CHECK (("source" = ANY (ARRAY['home'::"text", 'explore'::"text", 'week_scout'::"text", 'permission_recovery'::"text"]))),
    CONSTRAINT "user_location_snapshots_timezone_check" CHECK ((("length"("timezone") >= 1) AND ("length"("timezone") <= 64)))
);


ALTER TABLE "public"."user_location_snapshots" OWNER TO "postgres";


