CREATE UNIQUE INDEX "alert_queue_similarity_canonical_decision_dedupe" ON "public"."alert_queue" USING "btree" ("user_id", "beach_id", "window_start", (
CASE
    WHEN ("conditions_snapshot" ? 'session_decision'::"text") THEN (("conditions_snapshot" -> 'session_decision'::"text") ->> 'verdict'::"text")
    ELSE 'go'::"text"
END)) WHERE (("conditions_snapshot" ->> 'alert_type'::"text") = 'similarity_match'::"text");



COMMENT ON INDEX "public"."alert_queue_similarity_canonical_decision_dedupe" IS 'Deduplicates similarity alerts by user, beach, forecast window, and canonical session verdict; legacy missing verdicts are treated as go.';



