CREATE POLICY "Public can view approved media from public sessions" ON "public"."session_media" FOR SELECT USING ((("deleted_at" IS NULL) AND (("user_id" = "auth"."uid"()) OR (("moderation_status" = 'approved'::"text") AND (EXISTS ( SELECT 1
   FROM "public"."sessions" "s"
  WHERE (("s"."id" = "session_media"."session_id") AND ("s"."is_public" = true) AND ("s"."deleted_at" IS NULL))))))));



